INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1018','contact','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->contact[\'contact\']}</title>\r\n{$headerinclude}\r\n<style>\r\n    :root {\r\n        --primary-color: #3498db;\r\n        --primary-hover: #2980b9;\r\n        --secondary-color: #2c3e50;\r\n        --success-color: #2ecc71;\r\n        --light-bg: #f8f9fa;\r\n        --border-color: #e9ecef;\r\n        --text-muted: #6c757d;\r\n        --shadow-sm: 0 2px 8px rgba(0,0,0,0.08);\r\n        --shadow-md: 0 4px 16px rgba(0,0,0,0.1);\r\n    }\r\n    \r\n    \r\n    .contact-container {\r\n        max-width: 800px;\r\n        margin: 2rem auto;\r\n        animation: fadeIn 0.5s ease;\r\n        position: relative;\r\n        z-index: 1;\r\n    }\r\n    \r\n    @keyframes fadeIn {\r\n        from { opacity: 0; transform: translateY(20px); }\r\n        to { opacity: 1; transform: translateY(0); }\r\n    }\r\n    \r\n    .contact-card {\r\n        border: none;\r\n        border-radius: 20px;\r\n        box-shadow: var(--shadow-md);\r\n        overflow: hidden;\r\n        background: white;\r\n        transition: transform 0.3s ease, box-shadow 0.3s ease;\r\n        position: relative;\r\n        z-index: 1;\r\n    }\r\n    \r\n    .contact-card::before {\r\n        content: \'\';\r\n        position: absolute;\r\n        top: 0;\r\n        left: 0;\r\n        right: 0;\r\n        height: 4px;\r\n        background: linear-gradient(90deg, var(--primary-color), #4a6fa5);\r\n        z-index: 2;\r\n    }\r\n    \r\n    .contact-card:hover {\r\n        transform: translateY(-5px);\r\n        box-shadow: 0 8px 30px rgba(0,0,0,0.15);\r\n    }\r\n    \r\n    .card-header-custom {\r\n        background: linear-gradient(135deg, var(--primary-color), var(--primary-hover));\r\n        color: white;\r\n        padding: 2rem 1.5rem;\r\n        border-bottom: none;\r\n        position: relative;\r\n        overflow: hidden;\r\n    }\r\n    \r\n    .card-header-custom::before {\r\n        content: \'\';\r\n        position: absolute;\r\n        top: -50%;\r\n        left: -50%;\r\n        width: 200%;\r\n        height: 200%;\r\n        background: radial-gradient(circle, rgba(255,255,255,0.1) 0%, rgba(255,255,255,0) 70%);\r\n        z-index: 1;\r\n    }\r\n    \r\n    .card-header-custom::after {\r\n        content: \'\';\r\n        position: absolute;\r\n        bottom: 0;\r\n        left: 5%;\r\n        width: 90%;\r\n        height: 1px;\r\n        background: linear-gradient(90deg, transparent, rgba(255,255,255,0.3), transparent);\r\n        z-index: 1;\r\n    }\r\n    \r\n    .card-header-custom > * {\r\n        position: relative;\r\n        z-index: 2;\r\n    }\r\n    \r\n    .card-header-custom i {\r\n        font-size: 1.8rem;\r\n        margin-right: 12px;\r\n        vertical-align: middle;\r\n        filter: drop-shadow(0 2px 3px rgba(0,0,0,0.2));\r\n    }\r\n    \r\n    .card-header-custom h1 {\r\n        font-size: 1.8rem;\r\n        font-weight: 700;\r\n        margin: 0;\r\n        display: inline-block;\r\n        vertical-align: middle;\r\n        text-shadow: 0 2px 4px rgba(0,0,0,0.2);\r\n        letter-spacing: 0.5px;\r\n    }\r\n    \r\n    .card-header-custom p {\r\n        font-size: 1rem;\r\n        opacity: 0.9;\r\n        margin-top: 0.5rem;\r\n        text-shadow: 0 1px 2px rgba(0,0,0,0.1);\r\n    }\r\n    \r\n    .form-section {\r\n        padding: 1.75rem;\r\n        border-bottom: 1px solid var(--border-color);\r\n        transition: all 0.3s ease;\r\n        position: relative;\r\n        background: white;\r\n    }\r\n    \r\n    .form-section::before {\r\n        content: \'\';\r\n        position: absolute;\r\n        left: 0;\r\n        top: 0;\r\n        bottom: 0;\r\n        width: 3px;\r\n        background: var(--primary-color);\r\n        opacity: 0;\r\n        transition: opacity 0.3s ease;\r\n    }\r\n    \r\n    .form-section:hover::before {\r\n        opacity: 1;\r\n    }\r\n    \r\n    .form-section:hover {\r\n        background-color: #fafcff;\r\n    }\r\n    \r\n    .form-section:last-of-type {\r\n        border-bottom: none;\r\n    }\r\n    \r\n    .form-label {\r\n        font-weight: 700;\r\n        color: var(--secondary-color);\r\n        margin-bottom: 0.75rem;\r\n        display: flex;\r\n        align-items: center;\r\n        gap: 10px;\r\n        font-size: 1.05rem;\r\n    }\r\n    \r\n    .form-label i {\r\n        color: var(--primary-color);\r\n        font-size: 1.1em;\r\n        width: 24px;\r\n        text-align: center;\r\n    }\r\n    \r\n    .form-desc {\r\n        color: var(--text-muted);\r\n        font-size: 0.9rem;\r\n        margin-bottom: 1.25rem;\r\n        line-height: 1.5;\r\n        padding-left: 34px;\r\n    }\r\n    \r\n    .form-control-custom {\r\n        border: 2px solid #e1e8f0;\r\n        border-radius: 12px;\r\n        padding: 1rem 1.25rem;\r\n        font-size: 1rem;\r\n        transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);\r\n        background: #fdfdfe;\r\n        color: #2c3e50;\r\n        box-shadow: inset 0 1px 3px rgba(0,0,0,0.05);\r\n    }\r\n    \r\n    .form-control-custom:focus {\r\n        border-color: var(--primary-color);\r\n        box-shadow: 0 0 0 4px rgba(52, 152, 219, 0.15), inset 0 1px 3px rgba(0,0,0,0.05);\r\n        background: white;\r\n        transform: translateY(-1px);\r\n    }\r\n    \r\n    .form-control-custom::placeholder {\r\n        color: #a0aec0;\r\n        opacity: 0.7;\r\n    }\r\n    \r\n    textarea.form-control-custom {\r\n        resize: vertical;\r\n        min-height: 200px;\r\n        line-height: 1.6;\r\n        font-family: inherit;\r\n    }\r\n    \r\n    .btn-send {\r\n        background: linear-gradient(135deg, var(--primary-color), var(--primary-hover));\r\n        border: none;\r\n        border-radius: 12px;\r\n        padding: 1rem 3rem;\r\n        font-weight: 700;\r\n        font-size: 1.1rem;\r\n        transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);\r\n        position: relative;\r\n        overflow: hidden;\r\n        letter-spacing: 0.5px;\r\n        text-transform: uppercase;\r\n        box-shadow: 0 4px 15px rgba(52, 152, 219, 0.3);\r\n    }\r\n    \r\n    .btn-send::before {\r\n        content: \'\';\r\n        position: absolute;\r\n        top: 0;\r\n        left: -100%;\r\n        width: 100%;\r\n        height: 100%;\r\n        background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);\r\n        transition: left 0.7s ease;\r\n    }\r\n    \r\n    .btn-send:hover {\r\n        transform: translateY(-3px);\r\n        box-shadow: 0 8px 25px rgba(52, 152, 219, 0.4);\r\n    }\r\n    \r\n    .btn-send:hover::before {\r\n        left: 100%;\r\n    }\r\n    \r\n    .btn-send:active {\r\n        transform: translateY(-1px);\r\n        box-shadow: 0 4px 15px rgba(52, 152, 219, 0.3);\r\n    }\r\n    \r\n    .btn-send i {\r\n        margin-right: 10px;\r\n        transition: transform 0.3s ease;\r\n        font-size: 1.2em;\r\n    }\r\n    \r\n    .btn-send:hover i {\r\n        transform: translateX(5px) scale(1.1);\r\n    }\r\n    \r\n    .error-alert {\r\n        animation: shake 0.5s ease;\r\n    }\r\n    \r\n    @keyframes shake {\r\n        0%, 100% { transform: translateX(0); }\r\n        25% { transform: translateX(-5px); }\r\n        75% { transform: translateX(5px); }\r\n    }\r\n    \r\n    .captcha-container {\r\n        padding: 1.75rem;\r\n        background: linear-gradient(135deg, #f8fafc 0%, #edf2f7 100%);\r\n        border-radius: 12px;\r\n        margin: 1.75rem;\r\n        border: 2px dashed #cbd5e0;\r\n        text-align: center;\r\n    }\r\n    \r\n    .required::after {\r\n        content: \'*\';\r\n        color: #e74c3c;\r\n        margin-left: 5px;\r\n        font-weight: bold;\r\n    }\r\n    \r\n    .contact-icon {\r\n        width: 80px;\r\n        height: 80px;\r\n        background: linear-gradient(135deg, var(--primary-color), var(--primary-hover));\r\n        border-radius: 50%;\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        margin: -40px auto 30px;\r\n        box-shadow: 0 10px 25px rgba(52, 152, 219, 0.4);\r\n        color: white;\r\n        font-size: 2rem;\r\n        position: relative;\r\n        z-index: 2;\r\n        border: 4px solid white;\r\n        transition: transform 0.3s ease;\r\n    }\r\n    \r\n    .contact-icon:hover {\r\n        transform: scale(1.05) rotate(5deg);\r\n    }\r\n    \r\n    .form-footer {\r\n        background: linear-gradient(to right, #f8fafc, #ffffff);\r\n        padding: 2rem;\r\n        border-top: 1px solid var(--border-color);\r\n        text-align: center;\r\n    }\r\n    \r\n    .floating-shapes {\r\n        position: fixed;\r\n        z-index: 0;\r\n        opacity: 0.1;\r\n    }\r\n    \r\n    .shape-1 {\r\n        top: 10%;\r\n        left: 10%;\r\n        width: 100px;\r\n        height: 100px;\r\n        background: white;\r\n        border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;\r\n        animation: float 15s infinite ease-in-out;\r\n    }\r\n    \r\n    .shape-2 {\r\n        bottom: 20%;\r\n        right: 10%;\r\n        width: 150px;\r\n        height: 150px;\r\n        background: white;\r\n        border-radius: 63% 37% 54% 46% / 55% 48% 52% 45%;\r\n        animation: float 20s infinite ease-in-out reverse;\r\n    }\r\n    \r\n    @keyframes float {\r\n        0%, 100% { transform: translateY(0) rotate(0deg); }\r\n        50% { transform: translateY(-20px) rotate(180deg); }\r\n    }\r\n    \r\n    .success-message {\r\n        position: fixed;\r\n        bottom: 20px;\r\n        right: 20px;\r\n        background: var(--success-color);\r\n        color: white;\r\n        padding: 1rem 1.5rem;\r\n        border-radius: 10px;\r\n        box-shadow: var(--shadow-md);\r\n        display: none;\r\n        animation: slideIn 0.5s ease;\r\n        z-index: 1000;\r\n    }\r\n    \r\n    @keyframes slideIn {\r\n        from { transform: translateX(100%); opacity: 0; }\r\n        to { transform: translateX(0); opacity: 1; }\r\n    }\r\n    \r\n    @media (max-width: 768px) {\r\n        .contact-container {\r\n            margin: 1rem;\r\n            padding: 0;\r\n        }\r\n        \r\n        .contact-card {\r\n            border-radius: 16px;\r\n            margin: 1rem;\r\n        }\r\n        \r\n        .card-header-custom {\r\n            padding: 1.5rem 1rem;\r\n        }\r\n        \r\n        .card-header-custom h1 {\r\n            font-size: 1.5rem;\r\n        }\r\n        \r\n        .form-section {\r\n            padding: 1.25rem;\r\n        }\r\n        \r\n        .btn-send {\r\n            width: 100%;\r\n            padding: 1rem;\r\n        }\r\n        \r\n        .contact-icon {\r\n            width: 70px;\r\n            height: 70px;\r\n            margin: -35px auto 25px;\r\n            font-size: 1.7rem;\r\n        }\r\n    }\r\n</style>\r\n</head>\r\n<body>\r\n\r\n\r\n<!-- Декоративные элементы -->\r\n<div class=\"floating-shapes shape-1\"></div>\r\n<div class=\"floating-shapes shape-2\"></div>\r\n\r\n<div class=\"container mt-3\">\r\n    <div class=\"contact-icon\">\r\n        <i class=\"fa-solid fa-headset\"></i>\r\n    </div>\r\n    \r\n    <form action=\"contact.php\" method=\"post\">\r\n        <input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n        <input type=\"hidden\" name=\"from\" value=\"{$redirect_url}\" />\r\n        \r\n        <div class=\"contact-card\">\r\n            <div class=\"card-header bg-primary text-center text-white\">\r\n                <h1><i class=\"fa-solid fa-envelope-circle-check\"></i> {$lang->contact[\'contact\']}</h1>\r\n                <p class=\"mb-0 mt-3\">{$lang->contact[\'contact_desc\']}</p>\r\n            </div>\r\n            \r\n            <div class=\"card-body p-0\">\r\n                {$errors}\r\n                \r\n                <div class=\"form-section\">\r\n                    <label class=\"form-label required\">\r\n                        <i class=\"fa-solid fa-tag\"></i>\r\n                        {$lang->contact[\'contact_subject\']}\r\n                    </label>\r\n                    <p class=\"form-desc\">{$lang->contact[\'contact_subject_desc\']}</p>\r\n                    <input type=\"text\" name=\"subject\" class=\"form-control form-control-custom\" value=\"{$contact_subject}\" placeholder=\"{$lang->contact[\'contact_subject_placeholder\']}\" required />\r\n                </div>\r\n                \r\n                <div class=\"form-section\">\r\n                    <label class=\"form-label required\">\r\n                        <i class=\"fa-solid fa-message\"></i>\r\n                        {$lang->contact[\'contact_message\']}\r\n                    </label>\r\n                    <p class=\"form-desc\">{$lang->contact[\'contact_message_desc\']}</p>\r\n                    <textarea class=\"form-control form-control-custom\" name=\"message\" placeholder=\"{$lang->contact[\'contact_message_placeholder\']}\" required>{$contact_message}</textarea>\r\n                </div>\r\n                \r\n                <div class=\"form-section\">\r\n                    <label class=\"form-label required\">\r\n                        <i class=\"fa-solid fa-at\"></i>\r\n                        {$lang->contact[\'contact_email\']}\r\n                    </label>\r\n                    <p class=\"form-desc\">{$lang->contact[\'contact_email_desc\']}</p>\r\n                    <input type=\"email\" name=\"email\" class=\"form-control form-control-custom\" value=\"{$user_email}\" placeholder=\"your@email.com\" required />\r\n                </div>\r\n                \r\n                {$captcha}\r\n            </div>\r\n            \r\n            <div class=\"form-footer\">\r\n                <button type=\"submit\" class=\"btn btn-send\" name=\"submit\" value=\"{$lang->contact[\'contact_send\']}\">\r\n                    <i class=\"fa-solid fa-paper-plane\"></i> {$lang->contact[\'contact_send\']}\r\n                </button>\r\n            </div>\r\n        </div>\r\n    </form>\r\n</div>\r\n\r\n<div class=\"success-message\" id=\"successMessage\">\r\n    <i class=\"fa-solid fa-check-circle me-2\"></i>\r\n    <span>Сообщение успешно отправлено!</span>\r\n</div>\r\n\r\n{$footer}\r\n\r\n<script>\r\ndocument.addEventListener(\'DOMContentLoaded\', function() {\r\n    // Добавляем плавную валидацию\r\n    const form = document.querySelector(\'form\');\r\n    const inputs = form.querySelectorAll(\'input[required], textarea[required]\');\r\n    \r\n    inputs.forEach(input => {\r\n        input.addEventListener(\'invalid\', function(e) {\r\n            e.preventDefault();\r\n            this.classList.add(\'is-invalid\');\r\n            this.style.borderColor = \'#e74c3c\';\r\n            \r\n            // Анимация ошибки\r\n            this.parentElement.classList.add(\'error-alert\');\r\n            setTimeout(() => {\r\n                this.parentElement.classList.remove(\'error-alert\');\r\n            }, 500);\r\n            \r\n            // Добавляем иконку ошибки\r\n            if (!this.parentElement.querySelector(\'.error-icon\')) {\r\n                const errorIcon = document.createElement(\'i\');\r\n                errorIcon.className = \'fa-solid fa-exclamation-circle error-icon\';\r\n                errorIcon.style.color = \'#e74c3c\';\r\n                errorIcon.style.position = \'absolute\';\r\n                errorIcon.style.right = \'15px\';\r\n                errorIcon.style.top = \'50%\';\r\n                errorIcon.style.transform = \'translateY(-50%)\';\r\n                this.parentElement.style.position = \'relative\';\r\n                this.parentElement.appendChild(errorIcon);\r\n            }\r\n        });\r\n        \r\n        input.addEventListener(\'input\', function() {\r\n            if (this.classList.contains(\'is-invalid\')) {\r\n                this.classList.remove(\'is-invalid\');\r\n                this.style.borderColor = \'\';\r\n                const errorIcon = this.parentElement.querySelector(\'.error-icon\');\r\n                if (errorIcon) {\r\n                    errorIcon.remove();\r\n                }\r\n            }\r\n        });\r\n    });\r\n    \r\n    // Анимация при фокусе\r\n    const formControls = form.querySelectorAll(\'.form-control-custom\');\r\n    formControls.forEach(control => {\r\n        control.addEventListener(\'focus\', function() {\r\n            this.parentElement.style.backgroundColor = \'rgba(52, 152, 219, 0.03)\';\r\n        });\r\n        \r\n        control.addEventListener(\'blur\', function() {\r\n            this.parentElement.style.backgroundColor = \'\';\r\n        });\r\n    });\r\n    \r\n    // Подсчет символов для текстового поля\r\n    const textarea = form.querySelector(\'textarea[name=\"message\"]\');\r\n    if (textarea) {\r\n        const charCounter = document.createElement(\'div\');\r\n        charCounter.className = \'text-end small mt-2\';\r\n        charCounter.style.fontSize = \'0.85rem\';\r\n        charCounter.style.fontWeight = \'500\';\r\n        textarea.parentElement.appendChild(charCounter);\r\n        \r\n        function updateCharCount() {\r\n            const length = textarea.value.length;\r\n            charCounter.textContent = length + \' символов\';\r\n            \r\n            if (length > 1000) {\r\n                charCounter.style.color = \'#e74c3c\';\r\n            } else if (length > 500) {\r\n                charCounter.style.color = \'#f39c12\';\r\n            } else {\r\n                charCounter.style.color = \'var(--text-muted)\';\r\n            }\r\n        }\r\n        \r\n        textarea.addEventListener(\'input\', updateCharCount);\r\n        updateCharCount();\r\n    }\r\n    \r\n    // Показ успешного сообщения\r\n    const successMessage = document.getElementById(\'successMessage\');\r\n    form.addEventListener(\'submit\', function(e) {\r\n        const isValid = form.checkValidity();\r\n        if (isValid) {\r\n            e.preventDefault();\r\n            \r\n            // Показываем анимацию отправки\r\n            const submitBtn = form.querySelector(\'.btn-send\');\r\n            const originalText = submitBtn.innerHTML;\r\n            submitBtn.innerHTML = \'<i class=\"fa-solid fa-spinner fa-spin\"></i> Отправка...\';\r\n            submitBtn.disabled = true;\r\n            \r\n            // Имитация отправки\r\n            setTimeout(() => {\r\n                // В реальном приложении здесь будет AJAX запрос\r\n                successMessage.style.display = \'block\';\r\n                submitBtn.innerHTML = originalText;\r\n                submitBtn.disabled = false;\r\n                \r\n                // Скрываем сообщение через 5 секунд\r\n                setTimeout(() => {\r\n                    successMessage.style.display = \'none\';\r\n                }, 5000);\r\n            }, 1500);\r\n        }\r\n    });\r\n    \r\n    // Параллакс эффект для декоративных элементов\r\n    window.addEventListener(\'mousemove\', (e) => {\r\n        const shapes = document.querySelectorAll(\'.floating-shapes\');\r\n        const mouseX = e.clientX / window.innerWidth;\r\n        const mouseY = e.clientY / window.innerHeight;\r\n        \r\n        shapes.forEach((shape, index) => {\r\n            const speed = index === 0 ? 0.02 : 0.01;\r\n            const x = (mouseX - 0.5) * speed * 100;\r\n            const y = (mouseY - 0.5) * speed * 100;\r\n            shape.style.transform = `translate(${x}px, ${y}px)`;\r\n        });\r\n    });\r\n});\r\n</script>\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1019','debug_summary','<div class=\"container-md\"><div id=\"debug\" class=\"card shadow-sm p-3 mt-4\">\r\n	<div class=\"row\">\r\n		<div class=\"col align-self-center\">{$generated_in} {$debug_weight} - {$sql_queries} / {$server_load} / {$memory_usage}</div>\r\n		<div class=\"col-auto align-self-center text-end\"><a href=\"{$debuglink}\" target=\"_blank\" class=\"btn btn-sm btn-secondary\">{$lang->debug_advanced_details}</a></div>\r\n	</div></div></div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1020','delete_attachments_button','<input type=\"hidden\" name=\"action\" value=\"do_attachments\" />\r\n<button type=\"submit\" class=\"btn btn-primary btn-sm\" value=\"{$lang->usercp[\'delete_attachments\']}\"><i class=\"fa-solid fa-trash\"></i> &nbsp;{$lang->usercp[\'delete_attachments\']}</button>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1021','editpost','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->editpost[\'edit_post\']}</title>\r\n\r\n{$post_javascript}\r\n		\r\n</head>\r\n<body>\r\n\r\n	\r\n	<div class=\"container-md\">\r\n		\r\n{$preview}\r\n{$post_errors}\r\n{$attacherror}\r\n{$moderation_notice}\r\n{$deletebox}\r\n<form id=\"editpost\" action=\"editpost.php?pid={$pid}&amp;processed=1\" method=\"post\" enctype=\"multipart/form-data\" name=\"input\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div id=\"fileIdsContainer\"></div>\r\n	\r\n	\r\n\r\n		<div class=\"row m-0 mb-3 p-0 pb-2 border-bottom\">\r\n			<div class=\"col align-self-center m-0 p-0\">\r\n{$editreason}\r\n			</div>\r\n	</div>\r\n	\r\n	<div class=\"row m-0 mb-3 p-0 pb-2 border-bottom\">\r\n{$prefixselect} \r\n			 <div class=\"col align-self-center m-0 p-0\">\r\n			 <input type=\"text\" class=\"form-control border mb-3\" name=\"subject\" maxlength=\"85\" value=\"{$subject}\" tabindex=\"1\" />\r\n		</div>\r\n	</div>\r\n		{$codebuttons}	 \r\n<div class=\"row\">\r\n	<div class=\"col\">\r\n<textarea id=\"message\" name=\"message\" class=\"form-control form-control-sm border\" style=\"height: 400px\" rows=\"20\" cols=\"70\" tabindex=\"2\" >{$message}</textarea>\r\n		</div>\r\n\r\n	</div>\r\n	\r\n	\r\n\r\n<div class=\"mt-2 mb-3\">\r\n{$postoptions}		\r\n<a class=\"links\" data-bs-toggle=\"collapse\" aria-expanded=\"false\" aria-controls=\"collapse-1\" href=\"#collapse-attach\" role=\"button\"><i class=\"fa-solid fa-paperclip\"></i> &nbsp;{$lang->editpost[\'attachments\']}</a>		\r\n{$pollbox}\r\n<button type=\"submit\" class=\"btn-thread\" name=\"previewpost\" value=\"{$lang->editpost[\'preview_post\']}\" tabindex=\"5\"><i class=\"fa-solid fa-pen\"></i> &nbsp;{$lang->editpost[\'preview_post\']}</button>\r\n{$captcha}\r\n		\r\n\r\n<!-- pollop -->\r\n<div id=\"collapse-pollop\" class=\"collapse mt-4\">\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->editpost[\'poll\']}</div>\r\n<div class=\"row g-3 border-bottom m-auto pb-4 pt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->editpost[\'poll\']}\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"text-desc mb-3\">{$lang->editpost[\'poll_desc\']}</div>\r\n<label><input type=\"checkbox\" class=\"form-check-input\" name=\"postpoll\" value=\"1\" {$postpollchecked} />&nbsp; {$lang->editpost[\'poll_check\']}</label>	\r\n<div class=\"mt-3\">{$lang->editpost[\'num_options\']}<input type=\"text\" class=\"form-control border form-control-sm border\" style=\"width: 250px\" name=\"numpolloptions\" value=\"{$numpolloptions}\" size=\"10\" /> &nbsp;{$lang->editpost[\'max_options\']}\r\n</div>	\r\n</div>\r\n</div>\r\n</div>\r\n<!-- pollop -->	\r\n <!-- attach -->\r\n<div id=\"collapse-attach\" class=\"collapse mt-4\">\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->editpost[\'attachments\']}</div>\r\n<div class=\"row g-3 border-bottom m-auto pb-4 pt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->editpost[\'attachments\']}\r\n</div>\r\n<div class=\"col\">\r\n{$attachbox}\r\n</div>\r\n</div>\r\n</div>\r\n<!-- attach -->\r\n <!-- modop -->\r\n<div id=\"collapse-modop\" class=\"collapse mt-4\">\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->mod_options}</div>\r\n<div class=\"row g-3 border-bottom m-auto pb-4 pt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->mod_options}\r\n</div>\r\n<div class=\"col\">\r\n{$closeoption}\r\n{$stickoption}\r\n</div>\r\n</div>\r\n</div>\r\n<!-- modop -->	\r\n<!-- postop -->\r\n<div id=\"collapse-postop\" class=\"collapse mt-4\">\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->editpost[\'post_options\']}</div>\r\n<div class=\"row g-3 border-bottom m-auto pb-4 pt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->editpost[\'post_options\']}\r\n</div>\r\n<div class=\"col\">\r\n{$signature} \r\n\r\n</div>\r\n</div>\r\n{$subscriptionmethod}		\r\n</div>\r\n<!-- postop -->		\r\n			\r\n        </div>\r\n	</div>\r\n\r\n	<div class=\"card-footer text-center\">\r\n		<button type=\"submit\" class=\"btn btn-primary lift\" name=\"submitbutton\" value=\"{$lang->editpost[\'update_post\']}\" tabindex=\"3\" accesskey=\"s\"><i class=\"fa-solid fa-pen\"></i> &nbsp;{$lang->editpost[\'update_post\']}</button>\r\n	</div>\r\n		\r\n<input type=\"hidden\" name=\"action\" value=\"do_editpost\" />\r\n<input type=\"hidden\" name=\"attachmentaid\" value=\"\" />\r\n<input type=\"hidden\" name=\"attachmentact\" value=\"\" />\r\n</form>\r\n	</div></div>\r\n\r\n<script>\r\ndocument.addEventListener(\'DOMContentLoaded\', function() {\r\n    // Показываем родительский элемент fileInput\r\n    if (Post.fileInput && Post.fileInput.parentElement && Post.fileInput.parentElement.parentElement) {\r\n        Post.fileInput.parentElement.parentElement.style.display = \'\';\r\n    }\r\n    \r\n    // Скрываем родительский элемент dropZone\r\n    if (Post.dropZone && Post.dropZone.parentElement && Post.dropZone.parentElement.parentElement) {\r\n        Post.dropZone.parentElement.parentElement.style.display = \'none\';\r\n    }\r\n});\r\n</script>	\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1022','editpost_delete','<form action=\"editpost.php\" method=\"post\" name=\"editpost\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n	\r\n<div class=\"card border-0 mb-4\">\r\n	<div class=\"card-header rounded-bottom text-19 fw-bold\">\r\n		{$lang->editpost[\'edit_post\']}\r\n	</div>\r\n	<div class=\"card-body\">\r\n		\r\n		<div class=\"row g-2 pb-3 border-bottom\">\r\n			<div class=\"col-lg-auto align-self-center border-end pe-3 me-3\">\r\n		\r\n		<input type=\"checkbox\" class=\"form-check-input\" name=\"delete\" value=\"1\" tabindex=\"9\" /> {$lang->editpost[\'delete_q\']}\r\n				\r\n			</div>\r\n			<div class=\"col-lg align-self-center\">\r\n		<i class=\"fa-solid fa-circle-exclamation text-danger\"></i> {$lang->editpost[\'delete_2\']}\r\n			</div>\r\n			<div class=\"col-lg-auto text-end align-self-center\">\r\n<input type=\"submit\" class=\"btn btn-danger\" name=\"submit\" value=\"{$lang->editpost[\'delete_now\']}\" tabindex=\"10\" />\r\n				<input type=\"hidden\" name=\"action\" value=\"deletepost\" />\r\n<input type=\"hidden\" name=\"pid\" value=\"{$pid}\" />\r\n			</div>\r\n		</div>\r\n		</div></div>\r\n</form>	','2','1837','','1720609281');
