INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1031','footer','	<div class=\"container mt-3\">\r\n\r\n	<div class=\"container-fluid mt-5 py-3 bg-nav\">\r\n<div class=\"container-md\">\r\n	\r\n\r\n	\r\n\r\n	\r\n	\r\n<div class=\"row flex m-auto text-14\">\r\n	{$contact_us}\r\n	{$showteamlink}\r\n	<div class=\"col-lg d-flex flex-column justify-content-between\">\r\n	<a href=\"{$BASEURL}\" class=\"links\"><i class=\"fa-solid fa-house\"></i> &nbsp;{$SITENAME}</a>\r\n	</div>\r\n	<div class=\"col-lg d-flex flex-column justify-content-between\">\r\n	<a href=\"#top\" class=\"links\"><i class=\"fa-solid fa-circle-arrow-up\"></i> &nbsp;{$lang->global[\'bottomlinks_returntop\']}</a>\r\n	</div>\r\n	<div class=\"col-lg d-flex flex-column justify-content-between\">\r\n	<a href=\"{$BASEURL}/misc.php?action=markread{$post_code_string}\" class=\"links\"><i class=\"fa-solid fa-circle-dot\"></i> &nbsp;{$lang->global[\'bottomlinks_markread\']}</a>\r\n	</div>\r\n	<div class=\"col-lg d-flex flex-column justify-content-between\">\r\n	<a href=\"{$BASEURL}/misc.php?action=syndication\" class=\"links\"><i class=\"fa-solid fa-square-rss\"></i> &nbsp;{$lang->global[\'bottomlinks_syndication\']}</a>\r\n	</div>\r\n	<div class=\"col-lg-auto d-flex flex-column justify-content-between\">\r\n	<a href=\"{$BASEURL}/misc.php?action=help\" class=\"links\"><i class=\"fa-solid fa-circle-question\"></i> &nbsp;{$lang->global[\'toplinks_help\']}</a>\r\n	</div>\r\n	</div>\r\n	\r\n		</div>\r\n	</div>\r\n	\r\n	<div class=\"container-md\">\r\n	\r\n	{$auto_dst_detection}\r\n	<div class=\"row g-1 mt-3 mb-3 text-14\">\r\n		<div class=\"col-lg-auto align-self-center text-center text-sm-center text-md-center text-lg-start text-xl-start text-xxl-start\">\r\n				  \r\n		</div>\r\n		<div class=\"col-lg-auto align-self-center\">\r\n		\r\n		</div>\r\n		<div class=\"col-lg align-self-center text-center text-sm-center text-md-center text-lg-end text-xl-end text-xxl-end mt-3 mt-sm-3 mt-md-3 mt-lg-0 mt-xl-0 mt-xxl-0 text-muted\">\r\n			\r\n			\r\n			<!-- MyBB is free software developed and maintained by a volunteer community.\r\n					It would be much appreciated by the MyBB Group if you left the full copyright and \"powered by\" notice intact,\r\n					to show your support for MyBB.  If you choose to remove or modify the copyright below,\r\n					you may be refused support on the MyBB Community Forums.\r\n\r\n					This is free software, support us and we\'ll support you.\r\n\r\n                    Curves \'1.9\' is developed and built by Curves UI (https://www.curvesui.com/). If you remove either\r\n                    the Curves UI or MyBB copyright notices, you will be refused support. -->\r\n				\r\n		</div>\r\n	</div>\r\n	</div>\r\n		\r\n	</div>\r\n\r\n<!-- new -->\r\n	</div>\r\n	</div>','2','1837','','1728811321');
