INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1033','footer_languageselect','\r\n\r\n\r\n<form method=\"POST\" action=\"{$lang_redirect_url[\'location\']}\" id=\"lang_select\">\r\n	{$theme_redirect_url[\'form_html\']}\r\n	<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n	<div class=\"row g-1\">\r\n	<div class=\"col-auto align-self-center\">\r\n		<select name=\"language\" onchange=\"MyBB.changeLanguage();\" class=\"form-select form-select-sm border pe-5 w-auto\">\r\n		<optgroup label=\"{$lang->select_language}\">\r\n			{$lang_options}\r\n		</optgroup>\r\n	</select>\r\n		</div>\r\n		<div class=\"col-auto align-self-center\">\r\n	{$gobutton}\r\n		</div>\r\n	</div>\r\n</form>','2','1837','','1720609281');
