INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1079','forumjump_advanced','<form action=\"forumdisplay.php\" method=\"get\">\r\n\r\n<select name=\"{$name}\" class=\"form-select border form-select-sm\">\r\n<option value=\"-4\">{$lang->forumjump_pms}</option>\r\n<option value=\"-3\">{$lang->forumjump_usercp}</option>\r\n<option value=\"-5\">{$lang->forumjump_wol}</option>\r\n<option value=\"-2\">{$lang->forumjump_search}</option>\r\n<option value=\"-1\">{$lang->forumjump_home}</option>\r\n{$forumjumpbits}\r\n</select>\r\n{$gobutton}\r\n</form>\r\n<script type=\"text/javascript\">\r\n$(\".forumjump\").on(\'change\', function() {\r\n	var option = $(this).val();\r\n\r\n	if(option < 0)\r\n	{\r\n		window.location = \'forumdisplay.php?fid=\'+option;\r\n	}\r\n	else\r\n	{\r\n		window.location = {$forum_link};\r\n	}\r\n});\r\n</script>','2','1830','','1720609281');
