INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1093','header_welcomeblock_guest','<ul class=\"list-inline\" style=\"margin-bottom: 0px\">\r\n<li class=\"list-inline-item\"><a href=\"{$mybb->settings[\'bburl\']}/member.php?action=login\" onclick=\"$(\'#quick_login\').modal({ fadeDuration: 250, keepelement: true, zIndex: (typeof modal_zindex !== \'undefined\' ? modal_zindex : 9999) }); return false;\" class=\"login\"><i class=\"fa-solid fa-right-to-bracket fs-6\"></i> &nbsp;{$lang->welcome_login}</a></li>\r\n<li class=\"list-inline-item\"><a href=\"{$mybb->settings[\'bburl\']}/member.php?action=register\"><i class=\"fa-solid fa-user fs-6\"></i> &nbsp;{$lang->welcome_register}</a>\r\n</li>\r\n</ul>\r\n\r\n<div class=\"modal p-0 m-0\" id=\"quick_login\" style=\"display: none;\">\r\n	<form method=\"post\" action=\"{$mybb->settings[\'bburl\']}/member.php\">\r\n						<input name=\"action\" type=\"hidden\" value=\"do_login\" />\r\n						<input name=\"url\" type=\"hidden\" value=\"\" />\r\n						<input name=\"quick_login\" type=\"hidden\" value=\"1\" />\r\n						<input name=\"my_post_key\" type=\"hidden\" value=\"{$mybb->post_code}\" />\r\n		<div class=\"card border-dark\" style=\"overflow-y: auto; max-height: 500px;\">\r\n			<div class=\"card-header text-19 fw-bold border-0 py-3\"><i class=\"fa-solid fa-key\"></i> &nbsp;{$lang->login}</div>\r\n			<div class=\"card-body\">{$loginform}\r\n	</div>\r\n</div>\r\n	</form>\r\n<script type=\"text/javascript\">\r\n					$(\"#quick_login input[name=\'url\']\").val($(location).attr(\'href\'));\r\n				</script>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1094','header_welcomeblock_guest_login_modal','	<div class=\"py-3 border-bottom\">\r\n	<label>{$lang->username}</label>\r\n	<input type=\"text\" class=\"form-control border form-control-sm\" name=\"username\" value=\"\" />\r\n</div>\r\n<div class=\"py-3 border-bottom\">\r\n	<label>{$lang->password}</label><br />\r\n	<a href=\"{$mybb->settings[\'bburl\']}/member.php?action=lostpw\" class=\"lost_password\">{$lang->lost_password}</a>\r\n	<input type=\"password\" class=\"form-control border form-control-sm\" name=\"password\" value=\"\" />\r\n</div>\r\n<div class=\"py-3\">\r\n	<input type=\"checkbox\" class=\"form-check-input\" name=\"remember\" value=\"yes\" /> {$lang->remember_me}?\r\n</div>\r\n						\r\n{$captcha}\r\n</div>\r\n<div class=\"card-footer text-center\">\r\n\r\n		<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->login}\"><i class=\"fa-solid fa-right-to-bracket\"></i> &nbsp;{$lang->login}</button>\r\n	<input type=\"hidden\" name=\"action\" value=\"do_login\" />\r\n<input type=\"hidden\" name=\"url\" value=\"{$redirect_url}\" />\r\n<input name=\"my_post_key\" type=\"hidden\" value=\"{$mybb->post_code}\" />\r\n</form>\r\n	</div>','2','1837','','1720609281');
