INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1116','managegroup_user','\r\n<div class=\"row py-2 m-0 border-bottom\">\r\n		<div class=\"col-lg-4 align-self-center text-muted\">\r\n			{$user[\'profilelink\']} {$leader}\r\n		</div>\r\n	<div class=\"col-lg align-self-center text-muted\">\r\n		{$regdate}\r\n	</div>\r\n	<div class=\"col-lg align-self-center\">\r\n		Posts {$user[\'postnum\']}\r\n	</div>\r\n	<div class=\"col-auto align-self-center\">\r\n		{$checkbox}\r\n	</div>\r\n	</div>','2','1837','','1720609281');
