INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1118','memberlist','<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>{$SITENAME} - {$lang->memberlist[\'member_list\']}</title>\r\n    \r\n    <style>\r\n        .alphabet-nav {\r\n            background: #ffffff;\r\n            border: 1px solid #e9ecef;\r\n           \r\n        }\r\n        \r\n        .alphabet-link {\r\n            color: #495057;\r\n            text-decoration: none;\r\n            font-weight: 500;\r\n            font-size: 1rem;\r\n            padding: 0.4rem 0.7rem;\r\n            border-radius: 6px;\r\n            transition: all 0.2s ease;\r\n            display: inline-block;\r\n        }\r\n        \r\n        .alphabet-link:hover {\r\n            background: #f8f9fa;\r\n            color: #007bff;\r\n            transform: translateY(-1px);\r\n        }\r\n        \r\n        .search-card {\r\n            background: #ffffff;\r\n            border: 1px solid #e9ecef;\r\n            box-shadow: 0 2px 8px rgba(0,0,0,0.04);\r\n        }\r\n        \r\n        .section-title {\r\n            color: #495057;\r\n            font-weight: 600;\r\n            font-size: 1.1rem;\r\n        }\r\n        \r\n        .form-control-light {\r\n            border: 1px solid #e9ecef;\r\n            border-radius: 8px;\r\n            padding: 0.6rem 0.8rem;\r\n            transition: all 0.2s ease;\r\n            background: #ffffff;\r\n        }\r\n        \r\n        .form-control-light:focus {\r\n            border-color: #007bff;\r\n           \r\n        }\r\n        \r\n        .radio-toolbar-light {\r\n            display: flex;\r\n            gap: 0.8rem;\r\n            flex-wrap: wrap;\r\n        }\r\n        \r\n        .radio-toolbar-light input[type=\"radio\"] {\r\n            display: none;\r\n        }\r\n        \r\n        .radio-toolbar-light label {\r\n            padding: 0.6rem 1.2rem;\r\n            border: 1px solid #e9ecef;\r\n            border-radius: 6px;\r\n            cursor: pointer;\r\n            transition: all 0.2s ease;\r\n            font-weight: 400;\r\n            background: #ffffff;\r\n            color: #495057;\r\n        }\r\n        \r\n        .radio-toolbar-light input[type=\"radio\"]:checked + label {\r\n            background: #007bff;\r\n            color: white;\r\n            border-color: #007bff;\r\n        }\r\n        \r\n        .btn-light {\r\n            background: #007bff;\r\n            color: white;\r\n            border: none;\r\n            border-radius: 6px;\r\n            padding: 0.6rem 1.5rem;\r\n            font-weight: 500;\r\n            transition: all 0.2s ease;\r\n        }\r\n        \r\n        .btn-light:hover {\r\n            background: #0056b3;\r\n            color: white;\r\n            transform: translateY(-1px);\r\n        }\r\n        \r\n        .advanced-search-link {\r\n            color: #007bff;\r\n            text-decoration: none;\r\n            font-weight: 500;\r\n            transition: all 0.2s ease;\r\n            display: inline-flex;\r\n            align-items: center;\r\n            gap: 0.4rem;\r\n        }\r\n        \r\n        .advanced-search-link:hover {\r\n            color: #0056b3;\r\n        }\r\n        \r\n        .user-card {\r\n            background: white;\r\n            border-radius: 8px;\r\n            \r\n            transition: all 0.2s ease;\r\n            border: 1px solid #e9ecef;\r\n        }\r\n        \r\n        .user-card:hover {\r\n            box-shadow: 0 2px 8px rgba(0,0,0,0.08);\r\n            transform: translateY(-2px);\r\n        }\r\n        \r\n        .select2-container--default .select2-selection--single {\r\n            border: 1px solid #e9ecef;\r\n            border-radius: 8px;\r\n            height: 42px;\r\n            padding: 0.4rem;\r\n        }\r\n        \r\n        .pagination-light .page-link {\r\n            border-radius: 6px;\r\n            margin: 0 0.1rem;\r\n            border: 1px solid #e9ecef;\r\n            color: #495057;\r\n        }\r\n        \r\n        .pagination-light .page-item.active .page-link {\r\n            background: #007bff;\r\n            border-color: #007bff;\r\n            color: white;\r\n        }\r\n        \r\n        .card {\r\n            border: 1px solid #e9ecef;\r\n            \r\n        }\r\n        \r\n       \r\n    </style>\r\n</head>\r\n<body class=\"bg-light-custom\">\r\n\r\n<div class=\"container-md py-3\">\r\n    <!-- Pagination Top -->\r\n    <div class=\"mb-3 pagination-light\">{$multipage}</div>\r\n    \r\n    \r\n	\r\n	\r\n<!-- Alphabet Navigation -->\r\n<!-- Alphabet Navigation -->\r\n<div class=\"card mb-4 border-0 shadow-sm\">\r\n    <div class=\"card-body p-4\">\r\n        <div class=\"text-center\">\r\n            <div class=\"alphabet-grid\">\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'a\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'a\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'b\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'b\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'c\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'c\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'d\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'d\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'e\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'e\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'f\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'f\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'g\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'g\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'h\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'h\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'i\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'i\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'j\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'j\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'k\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'k\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'l\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'l\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'m\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'m\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'n\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'n\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'o\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'o\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'p\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'p\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'q\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'q\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'r\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'r\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'s\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'s\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'t\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'t\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'u\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'u\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'v\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'v\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'w\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'w\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'x\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'x\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'y\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'y\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n                <a href=\"memberlist.php?username_match=begins&amp;username={$lang->memberlist[\'z\']}\" class=\"alphabet-letter bg-primary\">\r\n                    <span class=\"letter\">{$lang->memberlist[\'z\']}</span>\r\n                    <span class=\"hover-effect\"></span>\r\n                </a>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<style>\r\n.alphabet-grid {\r\n    display: grid;\r\n    grid-template-columns: repeat(auto-fit, minmax(40px, 1fr));\r\n    gap: 8px;\r\n    max-width: 600px;\r\n    margin: 0 auto;\r\n}\r\n\r\n.alphabet-letter {\r\n    position: relative;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    height: 40px;\r\n    color: white;\r\n    text-decoration: none;\r\n    border-radius: 8px;\r\n    font-weight: 600;\r\n    font-size: 1.1rem;\r\n    transition: all 0.3s ease;\r\n    overflow: hidden;\r\n    border: none;\r\n}\r\n\r\n.alphabet-letter:hover {\r\n    transform: translateY(-2px);\r\n    box-shadow: 0 4px 15px rgba(13, 110, 253, 0.4);\r\n    color: white;\r\n    text-decoration: none;\r\n}\r\n\r\n.alphabet-letter .hover-effect {\r\n    position: absolute;\r\n    top: 0;\r\n    left: -100%;\r\n    width: 100%;\r\n    height: 100%;\r\n    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);\r\n    transition: left 0.5s ease;\r\n}\r\n\r\n.alphabet-letter:hover .hover-effect {\r\n    left: 100%;\r\n}\r\n\r\n.alphabet-letter .letter {\r\n    position: relative;\r\n    z-index: 2;\r\n}\r\n\r\n/* Адаптивность */\r\n@media (max-width: 576px) {\r\n    .alphabet-grid {\r\n        grid-template-columns: repeat(6, 1fr);\r\n        gap: 6px;\r\n    }\r\n    \r\n    .alphabet-letter {\r\n        height: 35px;\r\n        font-size: 1rem;\r\n    }\r\n}\r\n</style>\r\n\r\n\r\n	\r\n	\r\n	\r\n	\r\n	\r\n    \r\n    <!-- Users Grid -->\r\n    <div class=\"row g-3 mb-4\">\r\n        {$users}\r\n    </div>\r\n    \r\n    <!-- Pagination Bottom -->\r\n    <div class=\"mb-4 pagination-light\">{$multipage}</div>\r\n    \r\n    <!-- Search Form -->\r\n    <div class=\"card search-card\">\r\n        <div class=\"card-body p-4\">\r\n            <form method=\"post\" action=\"memberlist.php\">\r\n                <!-- Search Section -->\r\n                <div class=\"row align-items-center mb-4\">\r\n                    <div class=\"col-lg-3 d-none d-lg-block\">\r\n                        <div class=\"section-title\">\r\n                            <i class=\"fas fa-search me-2\"></i>\r\n                            {$lang->memberlist[\'search_members\']}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-lg-9\">\r\n                        <div class=\"row g-3\">\r\n                            <div class=\"col-md-6\">\r\n                                <label class=\"form-label fw-semibold\">{$lang->memberlist[\'username\']}</label>\r\n                                <input type=\"text\" class=\"form-control form-control-light\" name=\"username\" id=\"username\" value=\"{$search_username}\" placeholder=\"Enter username...\" />\r\n                            </div>\r\n                            <div class=\"col-md-6\">\r\n                                <label class=\"form-label fw-semibold\">{$lang->memberlist[\'website\']}</label>\r\n                                <input type=\"text\" class=\"form-control form-control-light\" name=\"website\" id=\"website\" value=\"{$search_website}\" placeholder=\"Enter website...\" />\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                \r\n                <!-- Sort Section -->\r\n                <div class=\"row align-items-center\">\r\n                    <div class=\"col-lg-3 d-none d-lg-block\">\r\n                        <div class=\"section-title\">\r\n                            <i class=\"fas fa-sort me-2\"></i>\r\n                            {$lang->memberlist[\'sort_by\']}\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-lg-9\">\r\n                        <div class=\"row g-3\">\r\n                            <div class=\"col-md-6\">\r\n                                <label class=\"form-label fw-semibold mb-2\">Sort Order</label>\r\n                                <div class=\"radio-toolbar-light\">\r\n                                    <input type=\"radio\" name=\"order\" id=\"order_asc\" value=\"ascending\"{$order_check[\'ascending\']} />\r\n                                    <label for=\"order_asc\">{$lang->memberlist[\'order_asc\']}</label>\r\n                                    <input type=\"radio\" name=\"order\" id=\"order_desc\" value=\"descending\"{$order_check[\'descending\']} />\r\n                                    <label for=\"order_desc\">{$lang->memberlist[\'order_desc\']}</label>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"col-md-6\">\r\n                                <label class=\"form-label fw-semibold\">Sort By</label>\r\n                                <select name=\"sort\" id=\"sort\" class=\"form-select form-control-light\">\r\n                                    <option value=\"username\"{$sort_selected[\'username\']}>{$lang->memberlist[\'sort_by_username\']}</option>\r\n                                    <option value=\"regdate\"{$sort_selected[\'regdate\']}>{$lang->memberlist[\'sort_by_regdate\']}</option>\r\n                                    <option value=\"lastvisit\"{$sort_selected[\'lastvisit\']}>{$lang->memberlist[\'sort_by_lastvisit\']}</option>\r\n                                    <option value=\"postnum\"{$sort_selected[\'postnum\']}>{$lang->memberlist[\'sort_by_posts\']}</option>\r\n                                    <option value=\"threadnum\"{$sort_selected[\'threadnum\']}>{$lang->memberlist[\'sort_by_threads\']}</option>\r\n                                    {$referrals_option}\r\n                                </select>\r\n                            </div>\r\n                        </div>\r\n                        \r\n                        <div class=\"mt-3 pt-3 border-top\">\r\n                            <a href=\"memberlist.php?action=search\" class=\"advanced-search-link\">\r\n                                <i class=\"fas fa-sliders-h\"></i>\r\n                                {$lang->memberlist[\'advanced_search\']}\r\n                            </a>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                \r\n                <!-- Submit Button -->\r\n                <div class=\"text-center mt-4\">\r\n                    <button type=\"submit\" class=\"btn btn-light\" name=\"submit\" value=\"{$lang->memberlist[\'search\']}\">\r\n                        <i class=\"fas fa-search me-2\"></i>\r\n                        {$lang->memberlist[\'search\']}\r\n                    </button>\r\n                </div>\r\n            </form>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<script type=\"text/javascript\">\r\nclass MemberSearch {\r\n    constructor() {\r\n        this.timeout = null;\r\n        this.init();\r\n    }\r\n\r\n    init() {\r\n        document.addEventListener(\'DOMContentLoaded\', () => {\r\n            this.setupUsernameSearch();\r\n            this.setupLabelClick();\r\n        });\r\n    }\r\n\r\n    setupUsernameSearch() {\r\n        const usernameInput = document.getElementById(\'username\');\r\n        if (!usernameInput) return;\r\n\r\n        const suggestionsContainer = this.createSuggestionsContainer();\r\n        \r\n        if (usernameInput.parentNode) {\r\n            usernameInput.parentNode.appendChild(suggestionsContainer);\r\n        }\r\n\r\n        usernameInput.addEventListener(\'input\', function(e) {\r\n            this.handleUsernameInput(e.target.value, suggestionsContainer);\r\n        }.bind(this));\r\n\r\n        usernameInput.addEventListener(\'focus\', function() {\r\n            if (usernameInput.value.length >= 2) {\r\n                this.handleUsernameInput(usernameInput.value, suggestionsContainer);\r\n            }\r\n        }.bind(this));\r\n\r\n        usernameInput.addEventListener(\'blur\', function() {\r\n            setTimeout(function() {\r\n                if (suggestionsContainer) {\r\n                    suggestionsContainer.style.display = \'none\';\r\n                }\r\n            }, 200);\r\n        });\r\n\r\n        usernameInput.addEventListener(\'keydown\', function(e) {\r\n            this.handleKeyboardNavigation(e, suggestionsContainer);\r\n        }.bind(this));\r\n    }\r\n\r\n    createSuggestionsContainer() {\r\n        const container = document.createElement(\'div\');\r\n        container.className = \'username-suggestions\';\r\n        container.style.position = \'absolute\';\r\n        container.style.background = \'white\';\r\n        container.style.border = \'1px solid #ddd\';\r\n        container.style.borderRadius = \'4px\';\r\n        container.style.maxHeight = \'200px\';\r\n        container.style.overflowY = \'auto\';\r\n        container.style.zIndex = \'1000\';\r\n        container.style.width = \'100%\';\r\n        container.style.boxShadow = \'0 2px 8px rgba(0,0,0,0.1)\';\r\n        container.style.display = \'none\';\r\n        return container;\r\n    }\r\n\r\n    handleUsernameInput(query, container) {\r\n        if (!container || query.length < 2) {\r\n            if (container) container.style.display = \'none\';\r\n            return;\r\n        }\r\n\r\n        clearTimeout(this.timeout);\r\n        var self = this;\r\n        this.timeout = setTimeout(function() {\r\n            self.fetchUsers(query).then(function(users) {\r\n                self.displaySuggestions(users, container);\r\n            }).catch(function(error) {\r\n                console.error(\'Search error:\', error);\r\n            });\r\n        }, 300);\r\n    }\r\n\r\n    fetchUsers(query) {\r\n        return new Promise(function(resolve, reject) {\r\n            var formData = new FormData();\r\n            formData.append(\'query\', query);\r\n            \r\n            fetch(\'xmlhttp.php?action=get_users\', {\r\n                method: \'POST\',\r\n                body: formData\r\n            }).then(function(response) {\r\n                if (!response.ok) {\r\n                    throw new Error(\'HTTP error! status: \' + response.status);\r\n                }\r\n                return response.json();\r\n            }).then(function(data) {\r\n                resolve(data);\r\n            }).catch(function(error) {\r\n                console.error(\'Fetch error:\', error);\r\n                resolve([]);\r\n            });\r\n        });\r\n    }\r\n\r\n    displaySuggestions(users, container) {\r\n        if (!container || !users || !Array.isArray(users) || users.length === 0) {\r\n            if (container) container.style.display = \'none\';\r\n            return;\r\n        }\r\n\r\n        container.innerHTML = \'\';\r\n        \r\n        var self = this;\r\n        users.forEach(function(user) {\r\n            var suggestion = document.createElement(\'div\');\r\n            suggestion.className = \'username-suggestion\';\r\n            suggestion.style.padding = \'8px 12px\';\r\n            suggestion.style.cursor = \'pointer\';\r\n            suggestion.style.borderBottom = \'1px solid #f0f0f0\';\r\n            suggestion.style.transition = \'background-color 0.2s\';\r\n            \r\n            var userText = user.text || user.username || user.id || \'\';\r\n            suggestion.textContent = userText;\r\n            \r\n            suggestion.addEventListener(\'mouseenter\', function() {\r\n                this.style.backgroundColor = \'#f8f9fa\';\r\n            });\r\n            \r\n            suggestion.addEventListener(\'mouseleave\', function() {\r\n                this.style.backgroundColor = \'\';\r\n            });\r\n            \r\n            suggestion.addEventListener(\'click\', function() {\r\n                var usernameInput = document.getElementById(\'username\');\r\n                if (usernameInput) {\r\n                    usernameInput.value = userText;\r\n                }\r\n                container.style.display = \'none\';\r\n            });\r\n            \r\n            container.appendChild(suggestion);\r\n        });\r\n\r\n        container.style.display = \'block\';\r\n    }\r\n\r\n    handleKeyboardNavigation(e, container) {\r\n        if (!container) return;\r\n        \r\n        var suggestions = container.querySelectorAll(\'.username-suggestion\');\r\n        if (suggestions.length === 0) return;\r\n\r\n        var activeSuggestion = container.querySelector(\'.suggestion-active\');\r\n        var currentIndex = -1;\r\n\r\n        if (activeSuggestion) {\r\n            currentIndex = Array.from(suggestions).indexOf(activeSuggestion);\r\n        }\r\n\r\n        if (e.key === \'ArrowDown\') {\r\n            e.preventDefault();\r\n            var nextIndex = (currentIndex + 1) % suggestions.length;\r\n            this.setActiveSuggestion(suggestions, nextIndex);\r\n        } else if (e.key === \'ArrowUp\') {\r\n            e.preventDefault();\r\n            var prevIndex = currentIndex <= 0 ? suggestions.length - 1 : currentIndex - 1;\r\n            this.setActiveSuggestion(suggestions, prevIndex);\r\n        } else if (e.key === \'Enter\' && activeSuggestion) {\r\n            e.preventDefault();\r\n            activeSuggestion.click();\r\n        }\r\n    }\r\n\r\n    setActiveSuggestion(suggestions, index) {\r\n        for (var i = 0; i < suggestions.length; i++) {\r\n            suggestions[i].classList.remove(\'suggestion-active\');\r\n            suggestions[i].style.backgroundColor = \'\';\r\n            suggestions[i].style.color = \'\';\r\n        }\r\n        \r\n        if (suggestions[index]) {\r\n            suggestions[index].classList.add(\'suggestion-active\');\r\n            suggestions[index].style.backgroundColor = \'#007bff\';\r\n            suggestions[index].style.color = \'white\';\r\n        }\r\n    }\r\n\r\n    setupLabelClick() {\r\n        var usernameLabel = document.querySelector(\'[for=\"username\"]\');\r\n        var usernameInput = document.getElementById(\'username\');\r\n\r\n        if (usernameLabel && usernameInput) {\r\n            usernameLabel.addEventListener(\'click\', function(e) {\r\n                e.preventDefault();\r\n                usernameInput.focus();\r\n            });\r\n        }\r\n    }\r\n}\r\n\r\n// Добавляем базовые стили только если их еще нет\r\nif (!document.querySelector(\'style[data-member-search]\')) {\r\n    var style = document.createElement(\'style\');\r\n    style.setAttribute(\'data-member-search\', \'true\');\r\n    style.textContent = \'.username-suggestion:hover{background-color:#f8f9fa!important;color:inherit!important}.username-suggestion.suggestion-active{background-color:#007bff!important;color:white!important}#username{width:100%;position:relative}.username-suggestions{margin-top:2px}.username-suggestions div:last-child{border-bottom:none}\';\r\n    document.head.appendChild(style);\r\n}\r\n\r\n// Инициализируем поиск\r\nnew MemberSearch();\r\n</script>\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1119','memberlist_error','{$lang->memberlist[\'error_no_members\']}','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1120','memberlist_search','<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$lang->memberlist[\'search_member_list\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n	<form method=\"post\" action=\"memberlist.php\">\r\n	<div class=\"container-md\">\r\n	<div class=\"card\">\r\n<div class=\"card-body\">\r\n\r\n	<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->memberlist[\'username\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->memberlist[\'username\']}\r\n</div>\r\n<div class=\"col\">\r\n<select name=\"username_match\" class=\"form-select form-select-sm border pe-5 w-auto\">\r\n			<option value=\"begins\">{$lang->memberlist[\'begins_with\']}</option>\r\n			<option value=\"contains\">{$lang->memberlist[\'username_contains\']}</option>\r\n			<option value=\"exact\">{$lang->memberlist[\'username_exact\']}</option>\r\n		</select>\r\n	\r\n	<input type=\"text\" class=\"form-control form-control-sm border mt-2\" name=\"username\" id=\"username\" />\r\n</div>\r\n</div>\r\n\r\n	<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->memberlist[\'search_website\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->memberlist[\'search_website\']}\r\n</div>\r\n<div class=\"col\">\r\n<input type=\"text\" class=\"form-control form-control-sm border\" name=\"website\" id=\"website\" />\r\n</div>\r\n</div>\r\n	\r\n{$contact_fields[\'skype\']}\r\n{$contact_fields[\'google\']}\r\n{$contact_fields[\'icq\']}	\r\n	\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->memberlist[\'search_options\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->memberlist[\'search_options\']}\r\n</div>\r\n<div class=\"col\">\r\n<label for=\"sort\">{$lang->memberlist[\'sort_by\']}</label>\r\n\r\n		<select name=\"sort\" id=\"sort\" class=\"form-select form-select-sm border pe-5 w-auto\">\r\n			<option value=\"username\">{$lang->memberlist[\'sort_by_username\']}</option>\r\n			<option value=\"added\">{$lang->memberlist[\'sort_by_regdate\']}</option>\r\n			<option value=\"lastvisit\">{$lang->memberlist[\'sort_by_lastvisit\']}</option>\r\n			<option value=\"postnum\">{$lang->memberlist[\'sort_by_posts\']}</option>\r\n			<option value=\"threadnum\">{$lang->memberlist[\'sort_by_threads\']}</option>\r\n			{$referrals_option}\r\n		</select>\r\n	\r\n	<div class=\"radio-toolbar mt-2\">\r\n		<input type=\"radio\" name=\"order\" id=\"order_asc\" value=\"asc\" />\r\n  <label for=\"order_asc\">{$lang->memberlist[\'order_asc\']}</label>\r\n		<input type=\"radio\" name=\"order\" id=\"order_desc\" value=\"desc\" checked=\"checked\" />\r\n		<label for=\"order_desc\">{$lang->memberlist[\'order_desc\']}</label>\r\n	</div>\r\n</div>\r\n</div>	\r\n\r\n	<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->memberlist[\'per_page\']}</div>\r\n<div class=\"row g-3 m-auto pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->memberlist[\'per_page\']}\r\n</div>\r\n<div class=\"col\">\r\n<input type=\"text\" class=\"form-control form-control-sm border\" style=\"width: 100px\" size=\"4\" name=\"perpage\" id=\"perpage\" value=\"15\" />\r\n</div>\r\n</div>\r\n		</div>\r\n<div class=\"card-footer text-center\">\r\n	<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->memberlist[\'search\']}\"><i class=\"fa-solid fa-magnifying-glass\"></i> &nbsp;{$lang->memberlist[\'search\']}</button>\r\n		</div>\r\n	\r\n	</div>\r\n		</div></div></div>\r\n</form>\r\n\r\n<link rel=\"stylesheet\" href=\"{$BASEURL}/scripts/select2/select2-2.css?ver=1807\">\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/select2/select2.min.js?ver=1806\"></script>\r\n<script type=\"text/javascript\">\r\n<!--\r\n\r\n	MyBB.select2();\r\n	$(\"#username\").select2({\r\n		placeholder: \"{$lang->memberlist[\'search_user\']}\",\r\n		minimumInputLength: 2,\r\n		multiple: false,\r\n		allowClear: true,\r\n		ajax: { // instead of writing the function to execute the request we use Select2\'s convenient helper\r\n			url: \"xmlhttp.php?action=get_users\",\r\n			dataType: \'json\',\r\n			data: function (term, page) {\r\n				return {\r\n					query: term, // search term\r\n				};\r\n			},\r\n			results: function (data, page) { // parse the results into the format expected by Select2.\r\n				// since we are using custom formatting functions we do not need to alter remote JSON data\r\n				return {results: data};\r\n			}\r\n		},\r\n		initSelection: function(element, callback) {\r\n			var value = $(element).val();\r\n			if (value !== \"\") {\r\n				callback({\r\n					id: value,\r\n					text: value\r\n				});\r\n			}\r\n		},\r\n       // Allow the user entered text to be selected as well\r\n       createSearchChoice:function(term, data) {\r\n			if ( $(data).filter( function() {\r\n				return this.text.localeCompare(term)===0;\r\n			}).length===0) {\r\n				return {id:term, text:term};\r\n			}\r\n		},\r\n	});\r\n\r\n  	$(\'[for=username]\').on(\'click\', function(){\r\n		$(\"#username\").select2(\'open\');\r\n		return false;\r\n	});\r\n\r\n// -->\r\n</script>\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1121','memberlist_search_contact_field','<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang_string}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang_string}\r\n</div>\r\n<div class=\"col\">\r\n<input type=\"text\" class=\"form-control form-control-sm border\" name=\"{$field}\" id=\"{$field}\" />\r\n</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1122','memberlist_user','<div class=\"col-lg-6\">\r\n	<div class=\"card\">\r\n		<div class=\"card-body\">\r\n	<div class=\"row\">\r\n		<div class=\"col-auto\">\r\n			{$user[\'avatar\']}\r\n		</div>\r\n		<div class=\"col\">\r\n			<h6 class=\"mb-0\">{$user[\'profilelink\']}</h6>\r\n			{$user[\'usertitle\']} <br /><span class=\"small\">\r\n			<span class=\"text-muted\">{$lang->memberlist[\'posts\']}</span> {$user[\'postnum\']} / <span class=\"text-muted\">{$lang->memberlist[\'threads\']}</span> {$user[\'threadnum\']}<br />\r\n			<span class=\"text-muted\">{$lang->memberlist[\'joined\']}:</span> {$user[\'added\']}<br />\r\n			<span class=\"text-muted\">{$lang->memberlist[\'lastvisit\']}:</span> {$user[\'lastvisit\']}</span>\r\n		</div>\r\n	</div>\r\n		</div>\r\n	</div>\r\n</div>','2','1837','','1720609281');
