INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1190','misc_help_search','<div class=\"card\">\r\n	<div class=\"card-body\">\r\n		\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->misc[\'search\']}</div>\r\n<div class=\"row g-3 m-auto pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->misc[\'search\']}\r\n</div>\r\n<div class=\"col\">\r\n<form action=\"misc.php\" method=\"post\">\r\n<input type=\"text\" name=\"keywords\" value=\"{$lang->misc[\'enter_keywords\']}\" onfocus=\"if(this.value == \'{$lang->enter_keywords}\') { this.value = \'\'; }\" onblur=\"if(this.value==\'\') { this.value=\'{$lang->misc[\'enter_keywords\']}\'; }\" class=\"form-control border form-control-sm\" size=\"25\" />\r\n	\r\n	<div class=\"mt-2\">\r\n  <input name=\"name\" id=\"name\" class=\"form-check-input\" checked=\"checked\" value=\"1\" type=\"checkbox\">\r\n  <label for=\"name\" class=\"form-check-label\">{$lang->misc[\'search_by_name\']}</label>\r\n<br />\r\n\r\n  <input name=\"document\" id=\"document\" class=\"form-check-input\" checked=\"checked\" value=\"1\" type=\"checkbox\">\r\n  <label for=\"document\" class=\"form-check-label\">{$lang->misc[\'search_by_document\']}</label>\r\n</div>\r\n</div>\r\n</div>\r\n	\r\n		</div>\r\n		<div class=\"card-footer text-center\">\r\n			<input type=\"hidden\" name=\"action\" value=\"do_helpsearch\" />\r\n<input type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->misc[\'search_help_documents\']}\" />\r\n</div>\r\n</form>\r\n</div>','2','1837','','1720609281');
