INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1194','misc_syndication','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->misc[\'syndication\']}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n	<div class=\"container-md\">\r\n		<form method=\"post\" action=\"misc.php?action=syndication\">\r\n	<div class=\"card\">\r\n<div class=\"card-body\">\r\n	\r\n	{$lang->misc[\'syndication_note\']}\r\n	\r\n\r\n{$feedurl}\r\n\r\n<label>{$lang->misc[\'syndication_forum\']}</label><br /><span class=\"text-desc\">{$lang->misc[\'syndication_forum_desc\']}</span>\r\n{$forumselect}\r\n\r\n	<div class=\"py-3 border-bottom\">\r\n		<label>{$lang->misc[\'syndication_version\']}</label><br /><span class=\"text-desc\">{$lang->misc[\'syndication_version_desc\']}</span>\r\n		<br /><br />\r\n	\r\n	\r\n<input type=\"radio\" class=\"form-check-input\" name=\"version\" value=\"rss2.0\" {$rss2check} />&nbsp; {$lang->misc[\'syndication_version_rss2\']}<br />\r\n<input type=\"radio\" class=\"form-check-input\" name=\"version\" value=\"atom1.0\" {$atom1check} />&nbsp; {$lang->misc[\'syndication_version_atom1\']}<br />\r\n<input type=\"radio\" class=\"form-check-input\" name=\"version\" value=\"json\" {$json1check} />&nbsp; {$lang->misc[\'syndication_version_json1\']}\r\n		\r\n	</div>\r\n\r\n		<div class=\"py-3\">\r\n			<label>{$lang->misc[\'syndication_limit\']}</label><br /><span class=\"text-desc\">{$lang->misc[\'syndication_limit_desc\']}</span>\r\n		\r\n		\r\n<input type=\"text\" class=\"form-control form-control-sm border w-25\" name=\"limit\" value=\"{$limit}\" size=\"3\" /> {$lang->misc[\'syndication_threads_time\']}\r\n			\r\n	</div>\r\n		</div>\r\n\r\n\r\n<div class=\"card-footer text-center\">\r\n	<button type=\"submit\" class=\"btn btn-primary\" name=\"make\" value=\"{$lang->misc[\'syndication_generate\']}\"><i class=\"fa-solid fa-rss\"></i> &nbsp;{$lang->misc[\'syndication_generate\']}</button>\r\n		</div>\r\n</form>\r\n			</div></div></div>\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
