INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1201','modcp','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->modcp[\'modcp\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n	\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n{$modcp_nav}\r\n</div>\r\n<div class=\"col\">\r\n						\r\n\r\n{$latestfivemodactions}\r\n	\r\n<div class=\"card mb-4\">\r\n	<div class=\"card-footer border-bottom border-top-0 text-19 fw-bold\">\r\n		{$lang->modcp[\'bans_ending_soon\']}\r\n	</div>\r\n	<div class=\"card-body pt-2 pb-0\">\r\n		<div class=\"d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n				<div class=\"row pb-2 border-2 fw-bold\">\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'username\']}\r\n			</div>\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'reason\']}\r\n			</div>\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'ban_length\']}\r\n			</div>\r\n				<div class=\"col\">\r\n				{$lang->modcp[\'ban_bannedby\']}\r\n			</div>	\r\n			</div></div>\r\n		\r\n{$bannedusers}\r\n	</div>\r\n	</div>\r\n\r\n<form action=\"modcp.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"action\" value=\"do_modnotes\" />\r\n	\r\n<div class=\"card mb-4\">\r\n	<div class=\"card-footer border-bottom border-top-0 text-19 fw-bold\">\r\n		{$lang->modcp[\'moderator_notes\']}\r\n	</div>\r\n	<div class=\"card-body\">	\r\n	<span class=\"text-desc\"><i class=\"fa-solid fa-circle-info\"></i> {$lang->modcp[\'notes_public_all\']}</span>\r\n\r\n		<textarea name=\"modnotes\" class=\"form-control border form-control-sm mt-2\" style=\"height: 200px;\" rows=\"5\" cols=\"45\">{$modnotes}</textarea>\r\n		\r\n	</div>\r\n	<div class=\"card-footer text-center\">\r\n<button type=\"submit\" class=\"btn btn-primary\" name=\"notessubmit\" value=\"{$lang->modcp[\'save_notes\']}\"><i class=\"fa-solid fa-note-sticky\"></i> &nbsp;{$lang->modcp[\'save_notes\']}</button>\r\n	</div>\r\n</form>\r\n				</div>\r\n			</div>\r\n			</div>\r\n	</div>\r\n\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
