INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1245','modcp_latestfivemodactions','<div class=\"card mb-4\">\r\n	<div class=\"card-footer border-bottom border-top-0 text-19 fw-bold\">\r\n		{$lang->modcp[\'latest_5_modactions\']}\r\n	</div>\r\n	<div class=\"card-body pt-2 pb-0\">	\r\n		<div class=\"d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n		<div class=\"row pb-2 fw-bold\">\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'username\']} &mdash; {$lang->modcp[\'date\']}\r\n			</div>\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'action\']}\r\n			</div>\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'information\']}\r\n			</div>\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'ip\']}\r\n			</div>\r\n			</div></div>\r\n		\r\n		\r\n		{$modlogresults}\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1246','modcp_modlogs','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->modcp[\'modlogs\']}</title>\r\n\r\n</head>\r\n<body>\r\n	\r\n		<div class=\"container-md\">\r\n		\r\n		<div class=\"row\">\r\n			\r\n			<div class=\"col-lg-3\">\r\n\r\n{$modcp_nav}\r\n			</div>\r\n			<div class=\"col\">\r\n					\r\n				<div class=\"card mb-4\">\r\n	<div class=\"card-footer border-bottom border-top-0 text-19 fw-bold\">\r\n		{$lang->modcp[\'modlogs\']}\r\n	</div>\r\n	<div class=\"card-body pt-2 pb-0\">	\r\n		<div class=\"d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n		<div class=\"row pb-2 fw-bold\">\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'username\']} &mdash; {$lang->modcp[\'date\']}\r\n			</div>\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'action\']}\r\n			</div>\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'information\']}\r\n			</div>\r\n			<div class=\"col\">\r\n				{$lang->modcp[\'ip\']}\r\n			</div>\r\n			</div></div>\r\n		\r\n		\r\n		{$results}\r\n	</div>\r\n</div>\r\n				\r\n			\r\n				\r\n				\r\n				\r\n\r\n<div class=\"card mb-4\">\r\n	<div class=\"card-footer border-bottom border-top-0 text-19 fw-bold\">\r\n		{$lang->modcp[\'filter_modlogs\']}\r\n	</div>\r\n	<div class=\"card-body\">	\r\n	<form action=\"modcp.php?action=modlogs\" method=\"post\">\r\n		\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->modcp[\'forum\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->modcp[\'forum\']}\r\n</div>\r\n<div class=\"col\">\r\n{$forum_select}\r\n</div>\r\n</div>		\r\n		\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->modcp[\'from_moderator\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->modcp[\'from_moderator\']}\r\n</div>\r\n<div class=\"col\">\r\n<select name=\"uid\" class=\"form-select border form-select-sm pe-5 w-auto\">\r\n<option value=\"\">{$lang->modcp[\'all_moderators\']}</option>\r\n<option value=\"\">----------</option>\r\n{$user_options}\r\n</select>\r\n</div>\r\n</div>		\r\n		\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->modcp[\'sort_by\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->modcp[\'sort_by\']}\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"pb-3 mb-3 border-bottom\">\r\n<select name=\"sortby\" class=\"form-select border form-select-sm w-auto pe-5\">\r\n<option value=\"dateline\"{$sortbysel[\'dateline\']}>{$lang->modcp[\'date\']}</option>\r\n<option value=\"username\"{$sortbysel[\'username\']}>{$lang->modcp[\'username\']}</option>\r\n<option value=\"forum\"{$sortbysel[\'forum\']}>{$lang->modcp[\'forum_name\']}</option>\r\n<option value=\"thread\"{$sortbysel[\'thread\']}>{$lang->modcp[\'thread_subject\']}</option>\r\n</select>\r\n</div>\r\n<select name=\"order\" class=\"form-select border form-select-sm w-auto pe-5\">\r\n<option value=\"asc\"{$ordersel[\'asc\']}>{$lang->modcp[\'asc\']}</option>\r\n<option value=\"desc\"{$ordersel[\'desc\']}>{$lang->modcp[\'desc\']}</option>\r\n</select>\r\n</div>\r\n</div>		\r\n		\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->modcp[\'per_page\']}</div>\r\n<div class=\"row g-3 m-auto pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->modcp[\'per_page\']}\r\n</div>\r\n<div class=\"col\">\r\n<input type=\"text\" name=\"perpage\" value=\"{$perpage}\" size=\"4\"style=\"width: 60px\" class=\"form-control border form-control-sm\" />\r\n</div>\r\n</div>	\r\n		</div>\r\n					<div class=\"card-footer text-center\">\r\n						<button type=\"submit\" class=\"btn btn-primary\" value=\"{$lang->modcp[\'filter_logs\']}\"><i class=\"fa-solid fa-sort\"></i> &nbsp;{$lang->modcp[\'filter_logs\']}</button>\r\n					</div>\r\n				</form>\r\n			\r\n	</div>\r\n\r\n	</div></div>\r\n\r\n</div>\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
