INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1251','modcp_modqueue_attachments','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->modcp[\'attachments_awaiting_moderation\']}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n		<div class=\"container-md\">\r\n		\r\n		<div class=\"row\">\r\n			\r\n			<div class=\"col-lg-3\">\r\n\r\n{$modcp_nav}\r\n			</div>\r\n			<div class=\"col\">\r\n				<div class=\"card mb-4\">\r\n	<div class=\"card-footer border-top-0 border-bottom text-19 fw-bold\">\r\n		{$lang->modcp[\'attachments_awaiting_moderation\']}\r\n	</div>\r\n	<div class=\"card-body pt-2 pb-0\">\r\n		\r\n		<form action=\"modcp.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"action\" value=\"do_modqueue\" />\r\n		\r\n		<div class=\"row pb-2 fw-bold border-bottom\">\r\n			<div class=\"col\">\r\n				{$thread_link} &mdash; {$post_link} &mdash; {$lang->modcp[\'attachments\']}\r\n			</div>\r\n		</div>\r\n{$attachments}\r\n{$mass_controls}\r\n			\r\n			</div>\r\n\r\n<div class=\"card-footer text-center\"><button type=\"submit\" class=\"btn btn-primary\" name=\"reportsubmit\" value=\"{$lang->modcp[\'perform_actions\']}\"><i class=\"fa-solid fa-check\"></i> &nbsp;{$lang->modcp[\'perform_actions\']}</button></div>\r\n\r\n</form>\r\n	</div>\r\n	{$multipage}\r\n	</div></div>\r\n</div>\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1252','modcp_modqueue_attachments_attachment','<div class=\"row py-2 g-1 border-bottom\">\r\n	<div class=\"col-lg align-self-center\">\r\n		<a href=\"attachment.php?aid={$attachment[\'aid\']}\" target=\"_blank\">{$attachment[\'filename\']}</a> ({$attachment[\'filesize\']})\r\n	</div>\r\n	<div class=\"col-lg align-self-center\">\r\n		{$lang->post} <a href=\"{$link}\">{$attachment[\'postsubject\']}</a>, <span class=\"text-desc\">{$attachdate}</span>\r\n	</div>\r\n	<div class=\"col-lg align-self-center text-lg-end\">\r\n		<div class=\"radio-toolbar\">\r\n		<input type=\"radio\" class=\"radio_ignore\" name=\"attachments[{$attachment[\'aid\']}]\" id=\"1\" value=\"ignore\" checked=\"checked\" />\r\n			<label for=\"1\">{$lang->ignore}</label>\r\n		\r\n<input type=\"radio\" class=\"radio_delete\" name=\"attachments[{$attachment[\'aid\']}]\" id=\"2\" value=\"delete\" />\r\n			<label for=\"2\">{$lang->delete}</label>\r\n<input type=\"radio\" class=\"radio_approve\" name=\"attachments[{$attachment[\'aid\']}]\" id=\"3\" value=\"approve\" />\r\n			<label for=\"3\">{$lang->approve}</label>\r\n		</div>\r\n	</div>\r\n</div>','2','1837','','1720609281');
