INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1281','modcp_reports_allreport','<div class=\"row py-2 border-top inline_row\">\r\n	<div class=\"col-lg align-self-center\">\r\n		<span class=\"d-inline-block d-sm-inline-block d-md-inline-block d-lg-none d-xl-none d-xxl-none fw-bold\">{$lang->report_info}:&nbsp;</span>{$report_data[\'content\']}\r\n	</div>\r\n	<div class=\"col-lg align-self-center\">\r\n		<span class=\"d-inline-block d-sm-inline-block d-md-inline-block d-lg-none d-xl-none d-xxl-none fw-bold\">{$lang->report_type}:&nbsp;</span>{$report_data[\'comment\']}\r\n	</div>\r\n	<div class=\"col-lg align-self-center\">\r\n		<span class=\"d-inline-block d-sm-inline-block d-md-inline-block d-lg-none d-xl-none d-xxl-none fw-bold\">{$lang->report_count}:&nbsp;</span>{$report_data[\'reports\']}\r\n	</div>\r\n	<div class=\"col-lg align-self-center\">\r\n		<a href=\"{$report[\'reporterlink\']}\" target=\"_blank\">{$report[\'username\']}</a>, {$report_data[\'time\']}</span>\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1282','modcp_reports_allreports','<html>\r\n<head>\r\n<title>{$mybb->settings[\'bbname\']} - {$lang->all_reports}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n	<div class=\"container-md\">\r\n		\r\n		<div class=\"row\">\r\n			\r\n			<div class=\"col-lg-3\">\r\n\r\n{$modcp_nav}\r\n			</div>\r\n			<div class=\"col\">\r\n				\r\n		<div class=\"card mb-4\">\r\n	<div class=\"card-footer border-top-0 border-bottom text-19 fw-bold\">\r\n		{$lang->all_reports}\r\n	</div>\r\n	<div class=\"card-body pt-2 pb-0\">\r\n		\r\n		<div class=\"row pb-2 fw-bold\">\r\n			<div class=\"col d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n				{$lang->report_info}\r\n			</div>\r\n			<div class=\"col d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n				{$lang->report_type}\r\n			</div>\r\n			<div class=\"col d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n				{$lang->report_count}\r\n			</div>\r\n			<div class=\"col d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n				{$lang->report_lastpost}\r\n			</div>\r\n		</div>\r\n\r\n				\r\n				{$allreports}\r\n	</div></div>\r\n			{$allreportspages}\r\n			</div></div></div>\r\n{$footer}\r\n</body>\r\n</html>','2','1837','','1720609281');
