INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1350','newreply_threadreview','\r\n<table border=\"0\" cellspacing=\"{$theme[\'borderwidth\']}\" cellpadding=\"{$theme[\'tablespace\']}\" class=\"tborder tfixed\">\r\n<tr>\r\n<td class=\"thead\" style=\"text-align: center;\"><strong>{$lang->thread_review}</strong></td>\r\n</tr>\r\n{$reviewbits}\r\n{$reviewmore}\r\n</table>','2','1830','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1351','newthread','<html>\r\n<head>\r\n<title>{$lang->newthread[\'newthread_in\']}</title>\r\n\r\n\r\n{$post_javascript}\r\n\r\n</head>\r\n<body>\r\n	<div class=\"container-md\">		\r\n{$preview}\r\n{$thread_errors}\r\n{$attacherror}\r\n{$moderation_notice}\r\n		\r\n\r\n<form action=\"newthread.php?fid={$fid}&amp;processed=1\" method=\"post\" enctype=\"multipart/form-data\" name=\"input\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n\r\n<div id=\"fileIdsContainer\"></div>	\r\n\r\n	\r\n	<div class=\"row m-0 mb-3 p-0 pb-2 border-bottom\">\r\n		\r\n		\r\n		<div class=\"col align-self-center m-0 p-0\">\r\n	<input type=\"text\" class=\"form-control form-control border mb-3\" name=\"subject\" maxlength=\"85\" placeholder=\"{$lang->newthread[\'thread_subject\']}\" value=\"{$subject}\" tabindex=\"1\" />\r\n		</div>\r\n	</div>\r\n	\r\n\r\n			{$codebuttons}\r\n\r\n\r\n<div class=\"row\">\r\n	<div class=\"col\">\r\n\r\n\r\n\r\n\r\n      \r\n      <textarea class=\"form-control\" id=\"message\" name=\"message\" style=\"height: 400px\" tabindex=\"2\" placeholder=\"Write your Thread using BBCode...\">{$message}</textarea>\r\n   \r\n    \r\n	\r\n	\r\n	\r\n	</div>\r\n	\r\n	\r\n	\r\n	\r\n\r\n	</div>\r\n	\r\n	\r\n\r\n<div class=\"mt-2 mb-3\">\r\n{$postoptions}		\r\n{$modoptions}\r\n<a class=\"links\" data-bs-toggle=\"collapse\" aria-expanded=\"false\" aria-controls=\"collapse-1\" href=\"#collapse-attach\" role=\"button\"><i class=\"fa-solid fa-paperclip\"></i> &nbsp;{$lang->newthread[\'attachments\']}</a>		\r\n{$pollbox}\r\n<button type=\"submit\" class=\"btn-thread\" name=\"previewpost\" value=\"{$lang->newthread[\'preview_post\']}\" tabindex=\"5\"><i class=\"fa-solid fa-pen\"></i> &nbsp;{$lang->newthread[\'preview_post\']}</button>\r\n{$savedraftbutton}		\r\n	</div>\r\n	\r\n	\r\n	\r\n\r\n<!-- pollop -->\r\n<div id=\"collapse-pollop\" class=\"collapse\">\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->newthread[\'poll\']}</div>\r\n<div class=\"row g-3 border-bottom m-auto pb-4 pt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->newthread[\'poll\']}\r\n</div>\r\n<div class=\"col\">\r\n<div class=\"text-desc mb-3\">{$lang->newthread[\'poll_desc\']}</div>\r\n<label><input type=\"checkbox\" class=\"form-check-input\" name=\"postpoll\" value=\"1\" {$postpollchecked} />&nbsp; {$lang->newthread[\'poll_check\']}</label>	\r\n<div class=\"mt-3\">{$lang->newthread[\'num_options\']}<input type=\"text\" class=\"form-control border form-control-sm border\" style=\"width: 250px\" name=\"numpolloptions\" value=\"{$numpolloptions}\" size=\"10\" /> &nbsp;{$max_options}\r\n</div>	\r\n</div>\r\n</div>\r\n</div>\r\n<!-- pollop -->		\r\n <!-- attach -->\r\n<div id=\"collapse-attach\" class=\"collapse\">\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->newthread[\'attachments\']}</div>\r\n<div class=\"row g-3 border-bottom m-auto pb-4 pt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->newthread[\'attachments\']}\r\n</div>\r\n<div class=\"col\">\r\n{$attachbox}\r\n</div>\r\n</div>\r\n</div>\r\n<!-- attach -->\r\n <!-- modop -->\r\n<div id=\"collapse-modop\" class=\"collapse\">\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->newthread[\'mod_options\']}</div>\r\n<div class=\"row g-3 border-bottom m-auto pb-4 pt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->newthread[\'mod_options\']}\r\n</div>\r\n<div class=\"col\">\r\n{$closeoption}\r\n{$stickoption}\r\n</div>\r\n</div>\r\n</div>\r\n<!-- modop -->		\r\n<!-- postop -->\r\n<div id=\"collapse-postop\" class=\"collapse\">\r\n<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->newthread[\'post_options\']}</div>\r\n<div class=\"row g-3 border-bottom m-auto pb-4 pt-0 mb-2\">\r\n\r\n<div class=\"col\">\r\n\r\n</div>\r\n</div>\r\n{$subscriptionmethod}		\r\n</div>\r\n<!-- postop -->		\r\n	\r\n	{$multiquote_external}\r\n\r\n\r\n	</div>\r\n	<div class=\"card-footer text-center\">\r\n<button type=\"post_thread\" class=\"btn btn-primary\" name=\"post_thread\" value=\"{$lang->newthread[\'post_thread\']}\" tabindex=\"4\" accesskey=\"s\"><i class=\"fa-solid fa-pencil\"></i> &nbsp;{$lang->newthread[\'post_thread\']}</button></div>\r\n</div>\r\n<input type=\"hidden\" name=\"action\" value=\"do_newthread\" />\r\n<input type=\"hidden\" name=\"posthash\" value=\"{$posthash}\" />\r\n<input type=\"hidden\" name=\"attachmentaid\" value=\"\" />\r\n<input type=\"hidden\" name=\"attachmentact\" value=\"\" />\r\n<input type=\"hidden\" name=\"quoted_ids\" value=\"{$quoted_ids}\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n{$editdraftpid}\r\n</form>\r\n\r\n	</div></div>\r\n\r\n		\r\n		\r\n	\r\n\r\n<script>\r\ndocument.addEventListener(\'DOMContentLoaded\', function() {\r\n    // Заменяем старый jQuery код на чистый JavaScript\r\n    if (Post.fileInput && Post.fileInput.parentElement && Post.fileInput.parentElement.parentElement) {\r\n        Post.fileInput.parentElement.parentElement.style.display = \'block\';\r\n    }\r\n    if (Post.dropZone && Post.dropZone.parentElement && Post.dropZone.parentElement.parentElement) {\r\n        Post.dropZone.parentElement.parentElement.style.display = \'none\';\r\n    }\r\n});\r\n</script>\r\n</body>\r\n</html>','2','1837','','1720609281');
