INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1451','private_empty','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->private[\'empty_folders\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n<form action=\"private.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">\r\n				\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	\r\n	<div class=\"border-bottom pb-3 mb-3\">{$lang->private[\'empty_note\']}</div>\r\n\r\n	<strong>{$lang->private[\'empty_q\']}</strong>\r\n	<div class=\"py-2\">\r\n{$folderlist}\r\n	</div>\r\n\r\n	<div class=\"border-top py-3\"><input type=\"checkbox\" class=\"form-check-input\" name=\"keepunread\" value=\"1\" checked=\"checked\" /> {$lang->private[\'keep_unread\']}</div>\r\n\r\n	</div>\r\n	<div class=\"card-footer text-center\">\r\n<input type=\"hidden\" name=\"action\" value=\"do_empty\" />\r\n<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->private[\'delete\']}\"><i class=\"fa-solid fa-trash\"></i> &nbsp;{$lang->private[\'delete\']}</button>\r\n	</div></div>\r\n	</div>\r\n\r\n</form>\r\n	</div></div>\r\n\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1452','private_emptyexportlink','<div class=\"col-lg-auto\">\r\n<a href=\"private.php?action=empty\" class=\"links\"><i class=\"fa-solid fa-trash\"></i> &nbsp;{$lang->private[\'empty_folders2\']}</a>\r\n</div>\r\n<div class=\"col-lg-auto\">\r\n<a href=\"private.php?action=export\" class=\"links\"><i class=\"fa-solid fa-download\"></i> &nbsp;{$lang->private[\'export_messages2\']}</a>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1453','private_empty_folder','<div class=\"py-2\">\r\n<input type=\"checkbox\" class=\"form-check-input\" name=\"empty[{$fid}]\" value=\"1\" /> &nbsp;&nbsp;{$foldername} &nbsp;<span class=\"fw-bold\">{$foldercount}</span>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1454','private_folders','<html>\r\n<head>\r\n<title>{$SITENAME} - {$lang->private[\'pm_folders\']}</title>\r\n\r\n</head>\r\n<body>\r\n\r\n<form action=\"private.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">\r\n				\r\n<div class=\"card\">\r\n<div class=\"card-body\">\r\n	\r\n	<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->private[\'existing_folders\']}</div>\r\n<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->private[\'existing_folders\']}\r\n</div>\r\n<div class=\"col\">\r\n	<div class=\"mb-3 border-bottom pb-3\">\r\n		{$lang->private[\'edit_folder_note\']}\r\n	</div>\r\n{$folderlist}\r\n</div>\r\n</div>\r\n	\r\n		<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->private[\'new_folders\']}</div>\r\n<div class=\"row g-3 m-auto pt-0 mt-0 mb-2\">\r\n<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n{$lang->private[\'new_folders\']}\r\n</div>\r\n<div class=\"col\">\r\n	<div class=\"mb-3 border-bottom pb-3\">\r\n		{$lang->private[\'add_folders_note\']}\r\n	</div>\r\n{$newfolders}\r\n</div>\r\n</div>\r\n	\r\n	</div>\r\n	<div class=\"card-footer text-center\">\r\n		<input type=\"hidden\" name=\"action\" value=\"do_folders\" />\r\n<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->private[\'update_folders\']}\"><i class=\"fa-solid fa-folder-open\"></i> &nbsp;{$lang->private[\'update_folders\']}</button>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n\r\n</form>\r\n\r\n\r\n</body>\r\n</html>','2','1837','','1720609281');
