INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1509','showteam_moderators_mod','<div class=\"col-lg-6 mb-2 mt-2\">\r\n	<div class=\"card\">\r\n		<div class=\"card-body\">\r\n			<h6 class=\"mb-0\"><a href=\"{$user[\'profilelink\']}\">{$user[\'username\']}</a></h6>\r\n			{$scopelist} <br />\r\n			<span class=\"text-muted\">{$lang->showteam[\'lastvisit\']}:</span> {$user[\'lastvisit\']}\r\n			<br /><br />\r\n			{$emailcode} {$pmcode}\r\n		</div>\r\n	</div>\r\n</div>','2','1837','','1720609281');
