INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1512','showthread','<html>\r\n<head>\r\n<title>{$thread[\'subject\']}</title>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\n	var quickdelete_confirm = \"Are you sure you want to delete this post?\";\r\n	var quickrestore_confirm = \"Are you sure you want to restore this post?\";\r\n	var allowEditReason = \"1\";\r\n	var thread_deleted = \"{$thread_deleted}\";\r\n	var visible_replies = \"{$thread[\'replies\']}\";\r\n	\r\n	lang.save_changes = \"Save Changes\";\r\n	lang.cancel_edit = \"Cancel Edit\";\r\n	lang.quick_edit_update_error = \"There was an error editing your reply:\";\r\n	lang.quick_reply_post_error = \"There was an error posting your reply:\";\r\n	lang.quick_delete_error = \"There was an error deleting your reply:\";\r\n	lang.quick_delete_success = \"The post was deleted successfully.\";\r\n	lang.quick_delete_thread_success = \"The thread was deleted successfully.\";\r\n	lang.quick_restore_error = \"There was an error restoring your reply:\";\r\n	lang.quick_restore_success = \"The post was restored successfully.\";\r\n	lang.editreason = \"Edit Reason\";\r\n	lang.post_deleted_error = \"You can not perform this action to a deleted post.\";\r\n	lang.softdelete_thread = \"Soft Delete Thread\";\r\n	lang.restore_thread = \"Restore Thread\";\r\n	const forumBaseUrl = \"{$test}\";\r\n// -->\r\n</script>\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/thread.js?ver=1827\"></script>\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/toast.js\"></script>\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/edit_post.js\"></script>\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/delete_post.js\"></script>\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/report_post.js\"></script>\r\n\r\n\r\n</head>\r\n<body>\r\n\r\n\r\n	\r\n	\r\n<div class=\"container-md\">\r\n	\r\n\r\n	\r\n<div class=\"row mb-3 p-0 m-0\">\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg col-xl col-xxl p-0 align-self-center text-center text-sm-center text-md-center text-lg-start text-xl-start text-xxl-start mt-3 mt-sm-3 mt-md-3 mt-lg-0 mt-xl-0 mt-xxl-0\">\r\n		{$multipage}\r\n	</div>\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg-auto col-xl-auto col-xxl-auto m-0 p-0 text-center text-sm-center text-md-center text-lg-end text-xl-end text-xxl-end align-self-center order-first order-sm-first order-md-first order-lg-last order-xl-last order-xxl-last\">\r\n		\r\n		{$addremovesubscription} {$newreply}\r\n			\r\n		\r\n	</div>\r\n	</div>\r\n\r\n{$pollbox}\r\n	<div id=\"posts\">{$posts}</div>\r\n	\r\n	\r\n	\r\n\r\n	\r\n	\r\n	<div class=\"row mt-3 mb-3 p-0 m-0\">\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg col-xl col-xxl p-0 align-self-center text-center text-sm-center text-md-center text-lg-start text-xl-start text-xxl-start mb-3 mb-sm-3 mb-md-3 mb-lg-0 mb-xl-0 mb-xxl-0\">\r\n		{$multipage}\r\n	</div>\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg-auto col-xl-auto col-xxl-auto m-0 p-0 text-center text-sm-center text-md-center text-lg-end text-xl-end text-xxl-end align-self-center\">\r\n		\r\n		 {$newreply}\r\n			\r\n		\r\n	</div>\r\n	</div>\r\n	\r\n	\r\n{$quickreply}\r\n\r\n<div class=\"container-md\">	\r\n<div class=\"row mt-5 m-0 p-0 border-top border-bottom\">\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg-5 col-xl-5 col-xxl-5 align-self-center py-3\">\r\n		{$search_thread}\r\n	</div>\r\n	<div class=\"col-12 col-sm-12 col-md-12 col-lg col-xl col-xxl text-center text-sm-center text-md-center text-lg-end text-xl-end text-xxl-end align-self-center py-3\"><a href=\"{$next_oldest_link}\" class=\"links\"><i class=\"fa-solid fa-angles-left\"></i> {$lang->showthread[\'next_oldest\']}</a> &nbsp;&nbsp;&nbsp;&nbsp; <a href=\"{$next_newest_link}\" class=\"links\">{$lang->showthread[\'next_newest\']} <i class=\"fa-solid fa-angles-right\"></i></a>\r\n	</div>\r\n	\r\n	</div>\r\n	\r\n		<div class=\"row m-0 p-0 mt-2 text-end\">\r\n			<div class=\"col-12 text-center text-sm-center text-md-center text-lg-end text-xl-end text-xxl-end align-self-center\">\r\n					{$addpoll}{$printthread}&nbsp;&nbsp; {$sendthread}\r\n			</div></div>\r\n	\r\n	{$moderationoptions}\r\n	\r\n		{$usersbrowsing}\r\n	\r\n</div>\r\n	\r\n\r\n	</div>\r\n	<script type=\"text/javascript\">\r\n		var thread_deleted = \"{$thread_deleted}\";\r\n		if(thread_deleted == \"1\")\r\n		{\r\n			$(\"#quick_reply_form, .new_reply_button, .thread_tools, .inline_rating\").hide();\r\n			$(\"#moderator_options_selector option.option_mirage\").attr(\"disabled\",\"disabled\");\r\n		}\r\n	</script>\r\n	\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1513','showthread_add_poll','<a href=\"polls.php?action=newpoll&amp;tid={$tid}\" title=\"{$lang->showthread[\'add_poll_to_thread\']}\" class=\"links\"><i class=\"fa-solid fa-square-poll-vertical\"></i></a> &nbsp;&nbsp;','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1514','showthread_inlinemoderation','<div class=\"col-lg\">\r\n<script type=\"text/javascript\" src=\"{$BASEURL}/scripts/inline_moderation.js?ver=1821\"></script>\r\n<form action=\"moderation.php\" method=\"post\" style=\"margin-top: 0; margin-bottom: 0;\" id=\"inlinemoderation_options\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n<input type=\"hidden\" name=\"modtype\" value=\"inlinepost\" />\r\n    <div class=\"row g-1\">\r\n        <div class=\"col d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n            &nbsp;\r\n        </div>\r\n        <div class=\"col-auto\">\r\n            <select name=\"action\" id=\"inlinemoderation_options_selector\" class=\"form-select form-select-sm border w-auto pe-5\">\r\n                {$standardposttools}\r\n                {$customposttools}\r\n            </select>\r\n        </div>\r\n        <div class=\"col-auto\">\r\n            <input type=\"submit\" class=\"btn btn-sm btn-primary\" name=\"go\" value=\"{$lang->showthread[\'go\']} ({$inlinecount})\" id=\"inline_go\" />\r\n            <input type=\"button\" class=\"btn btn-sm btn-primary\" onclick=\"inlineModeration.clearChecked();\" value=\"{$lang->showthread[\'clear\']}\" />\r\n        </div>\r\n    </div>\r\n</form>\r\n</div>\r\n\r\n<!-- Модальное окно подтверждения удаления -->\r\n<div class=\"modal fade\" id=\"deletePostsModal\" tabindex=\"-1\" aria-labelledby=\"deletePostsModalLabel\" aria-hidden=\"true\">\r\n    <div class=\"modal-dialog modal-dialog-centered modal-lg\">\r\n        <div class=\"modal-content border-0 shadow\">\r\n\r\n            <!-- Header -->\r\n            <div class=\"modal-header bg-danger text-white py-3\">\r\n                <div class=\"d-flex align-items-center gap-2\">\r\n                    <i class=\"fas fa-exclamation-triangle fa-lg\"></i>\r\n                    <div>\r\n                        <h5 class=\"modal-title mb-0\" id=\"deletePostsModalLabel\">Delete Posts Permanently</h5>\r\n                        <small class=\"opacity-75\">Irreversible Action Required</small>\r\n                    </div>\r\n                </div>\r\n                <button type=\"button\" class=\"btn-close btn-close-white\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\r\n            </div>\r\n\r\n            <!-- Body -->\r\n            <div class=\"modal-body p-0\">\r\n\r\n                <!-- Предупреждение -->\r\n                <div class=\"px-4 pt-4 pb-3\">\r\n                    <div class=\"alert alert-danger border-start border-danger border-4 bg-danger bg-opacity-10 mb-0\" role=\"alert\">\r\n                        <div class=\"d-flex gap-3 align-items-center\">\r\n                            <i class=\"fas fa-radiation-alt fa-lg text-danger\"></i>\r\n                            <div>\r\n                                <p class=\"mb-2 small\">You are about to <strong>permanently delete</strong> the posts below. This action <strong>cannot be undone</strong>.</p>\r\n                                <div class=\"d-flex flex-wrap gap-2\">\r\n                                    <span class=\"badge bg-secondary\">\r\n                                        <i class=\"fas fa-link me-1\"></i>Thread ID: <strong>{$tid}</strong>\r\n                                    </span>\r\n                                    <span class=\"badge bg-danger\">\r\n                                        <i class=\"fas fa-comments me-1\"></i>Posts to delete: <strong id=\"modal_post_count\">0</strong>\r\n                                    </span>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n                <!-- Превью постов -->\r\n                <div class=\"px-4 pb-3\">\r\n                    <h6 class=\"text-muted mb-2\">\r\n                        <i class=\"fas fa-eye me-1\"></i>Posts to be deleted:\r\n                    </h6>\r\n                    <div id=\"modal_posts_preview\" style=\"max-height: 380px; overflow-y: auto;\">\r\n                        <!-- Посты вставляются сюда через JS -->\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n\r\n            <!-- Footer -->\r\n            <div class=\"modal-footer d-flex justify-content-between border-top\">\r\n                <button type=\"button\" class=\"btn btn-outline-secondary btn-sm\" data-bs-dismiss=\"modal\">\r\n                    <i class=\"fas fa-times me-1\"></i>Cancel\r\n                </button>\r\n                <button type=\"button\" class=\"btn btn-danger btn-sm px-4\" id=\"confirmDeleteBtn\">\r\n                    <i class=\"fas fa-trash-alt me-1\"></i>Delete Permanently\r\n                </button>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\n    var go_text = \"{$lang->showthread[\'inline_go\']}\";\r\n    var all_text = \"{$threadcount}\";\r\n    var inlineType = \"thread\";\r\n    var inlineId = {$tid};\r\n\r\n    document.addEventListener(\'DOMContentLoaded\', function() {\r\n        var selector    = document.getElementById(\"inlinemoderation_options_selector\");\r\n        var form        = document.getElementById(\"inlinemoderation_options\");\r\n        var deleteModal = null;\r\n\r\n        if (typeof bootstrap !== \'undefined\') {\r\n            var modalElement = document.getElementById(\'deletePostsModal\');\r\n            if (modalElement) {\r\n                deleteModal = new bootstrap.Modal(modalElement);\r\n            }\r\n        }\r\n\r\n        if (selector && form) {\r\n\r\n            form.addEventListener(\'submit\', function(e) {\r\n                if (selector.value === \'multideleteposts\') {\r\n                    e.preventDefault();\r\n\r\n                    var selectedPosts = document.querySelectorAll(\'input[name^=\"inlinemod_\"]:checked\');\r\n                    var selectedCount = selectedPosts.length;\r\n\r\n                    if (selectedCount === 0) {\r\n                        alert(\'Please select at least one post.\');\r\n                        return;\r\n                    }\r\n\r\n                    // Обновляем счётчик\r\n                    document.getElementById(\'modal_post_count\').textContent = selectedCount;\r\n\r\n                    // Собираем pid\r\n                    var postIds = Array.from(selectedPosts).map(function(el) {\r\n                        return el.name.replace(\'inlinemod_\', \'\');\r\n                    });\r\n\r\n                    // Строим превью постов\r\n                    var previewContainer = document.getElementById(\'modal_posts_preview\');\r\n                    previewContainer.innerHTML = \'\';\r\n\r\n                    postIds.forEach(function(pid, index) {\r\n                        var postEl = document.getElementById(\'post_\' + pid);\r\n                        var preview = document.createElement(\'div\');\r\n                        preview.className = \'card mb-2 border-danger border-opacity-25\';\r\n\r\n                        if (postEl) {\r\n                            // Берём имя автора\r\n                            var authorEl  = postEl.querySelector(\'.card-title\');\r\n                            var authorText = authorEl ? authorEl.innerText.trim() : \'Unknown\';\r\n\r\n                            // Берём текст поста\r\n                            var contentEl  = document.getElementById(\'pid_\' + pid);\r\n                            var contentHTML = contentEl ? contentEl.innerHTML : \'\';\r\n\r\n                            // Клонируем контент чтобы не трогать оригинал\r\nvar tempDiv = document.createElement(\'div\');\r\ntempDiv.innerHTML = contentHTML;\r\n\r\n// Убираем вложенные цитаты и подписи чтобы не раздувать превью\r\nvar toRemove = tempDiv.querySelectorAll(\'.post_body blockquote, .signature\');\r\ntoRemove.forEach(function(el) { el.remove(); });\r\n\r\n// Обрезаем если слишком много текста\r\nvar plainText = tempDiv.innerText || tempDiv.textContent || \'\';\r\nif (plainText.length > 400) {\r\n    // Оставляем HTML но добавляем fade-out эффект\r\n    var shortHTML = tempDiv.innerHTML;\r\n    var previewHTML =\r\n        \'<div style=\"max-height: 120px; overflow: hidden; position: relative;\">\' +\r\n            shortHTML +\r\n            \'<div style=\"position: absolute; bottom: 0; left: 0; right: 0; height: 40px; \' +\r\n                \'background: linear-gradient(transparent, white);\"></div>\' +\r\n        \'</div>\';\r\n} else {\r\n    var previewHTML = tempDiv.innerHTML;\r\n}\r\n\r\npreview.innerHTML =\r\n    \'<div class=\"card-header py-2 px-3 bg-danger bg-opacity-10 d-flex justify-content-between align-items-center\">\' +\r\n        \'<span class=\"small fw-bold text-danger\">\' +\r\n            \'<i class=\"fas fa-user me-1\"></i>\' + authorText +\r\n        \'</span>\' +\r\n        \'<span class=\"badge bg-secondary small\">PID: \' + pid + \'</span>\' +\r\n    \'</div>\' +\r\n    \'<div class=\"card-body py-2 px-3 small\">\' +\r\n        previewHTML +\r\n    \'</div>\';\r\n								\r\n								\r\n								\r\n                        } else {\r\n                            preview.innerHTML =\r\n                                \'<div class=\"card-body py-2 px-3\">\' +\r\n                                    \'<p class=\"small text-muted mb-0\">\' +\r\n                                        \'<i class=\"fas fa-question-circle me-1\"></i>Post ID: \' + pid +\r\n                                    \'</p>\' +\r\n                                \'</div>\';\r\n                        }\r\n\r\n                        previewContainer.appendChild(preview);\r\n                    });\r\n\r\n                    // Удаляем старую скрытую форму\r\n                    var oldForm = document.getElementById(\'deletePostsHiddenForm\');\r\n                    if (oldForm) { oldForm.remove(); }\r\n\r\n                    // Создаём скрытую форму\r\n                    var hiddenForm = document.createElement(\'form\');\r\n                    hiddenForm.method        = \'post\';\r\n                    hiddenForm.action        = \'moderation.php\';\r\n                    hiddenForm.style.display = \'none\';\r\n                    hiddenForm.id            = \'deletePostsHiddenForm\';\r\n\r\n                    var fields = {\r\n                        \'my_post_key\': document.querySelector(\'#inlinemoderation_options input[name=\"my_post_key\"]\').value,\r\n                        \'tid\':         \'{$tid}\',\r\n                        \'modtype\':     \'inlinepost\',\r\n                        \'action\':      \'do_multideleteposts\',\r\n                        \'posts\':       postIds.join(\',\'),\r\n                        \'url\':         window.location.href\r\n                    };\r\n\r\n                    for (var key in fields) {\r\n                        var input   = document.createElement(\'input\');\r\n                        input.type  = \'hidden\';\r\n                        input.name  = key;\r\n                        input.value = fields[key];\r\n                        hiddenForm.appendChild(input);\r\n                    }\r\n\r\n                    document.body.appendChild(hiddenForm);\r\n\r\n                    document.getElementById(\'confirmDeleteBtn\').onclick = function() {\r\n                        hiddenForm.submit();\r\n                        if (deleteModal) { deleteModal.hide(); }\r\n                    };\r\n\r\n                    if (deleteModal) { deleteModal.show(); }\r\n                }\r\n                // Остальные действия — сабмит как обычно\r\n            });\r\n\r\n            selector.addEventListener(\'change\', function() {\r\n                form.dispatchEvent(new Event(\'submit\'));\r\n            });\r\n        }\r\n    });\r\n// -->\r\n</script>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1515','showthread_moderationoptions','<div class=\"row mt-5 g-1 m-0 py-3 border-top border-bottom\">\r\n    <div class=\"col-lg-6\">\r\n<form action=\"moderation.php\" method=\"post\" style=\"margin-top: 0; margin-bottom: 0;\" id=\"moderator_options\">\r\n    <input type=\"hidden\" name=\"modtype\" value=\"thread\" />\r\n    <input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n    <input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"row g-1 text-lg-start\">\r\n<div class=\"col-auto\">\r\n    <select name=\"action\" id=\"moderator_options_selector\" class=\"form-select form-select-sm w-auto pe-5\">\r\n        <option value=\"delayedmoderation\">{$lang->showthread[\'delayed_moderation\']}</option>\r\n        {$standardthreadtools}\r\n        {$customthreadtools}\r\n    </select>\r\n</div>\r\n<div class=\"col-auto\">\r\n    {$gobutton}\r\n</div>\r\n</div>\r\n</form>\r\n    </div>\r\n{$inlinemod}\r\n</div>\r\n\r\n<style>\r\n.dt-warning-icon {\r\n    width: 80px;\r\n    height: 80px;\r\n    background: linear-gradient(135deg, #f56565 0%, #e53e3e 100%);\r\n    border-radius: 50%;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    margin: 0 auto 1.5rem;\r\n    box-shadow: 0 4px 12px rgba(229, 62, 62, 0.2);\r\n}\r\n.dt-warning-icon i { font-size: 36px; color: white; }\r\n.dt-thread-preview {\r\n    background: linear-gradient(135deg, #f7fafc 0%, #edf2f7 100%);\r\n    border: 1px solid #e2e8f0;\r\n    border-left: 4px solid #e53e3e;\r\n    padding: 1rem;\r\n    border-radius: 8px;\r\n}\r\n.dt-consequences-list {\r\n    list-style: none;\r\n    padding-left: 0;\r\n    margin: 0;\r\n}\r\n.dt-consequences-list li {\r\n    padding: 0.5rem 0;\r\n    border-bottom: 1px solid #e2e8f0;\r\n    font-size: 0.9rem;\r\n}\r\n.dt-consequences-list li:last-child { border-bottom: none; }\r\n.dt-consequences-list li i { width: 24px; color: #e53e3e; }\r\n.btn-delete-thread {\r\n    background: linear-gradient(135deg, #f56565 0%, #e53e3e 100%);\r\n    border: none;\r\n    padding: 0.6rem 1.8rem;\r\n    font-weight: 600;\r\n    letter-spacing: 0.5px;\r\n    transition: all 0.3s ease;\r\n}\r\n.btn-delete-thread:hover {\r\n    transform: translateY(-2px);\r\n    box-shadow: 0 6px 20px rgba(229, 62, 62, 0.3);\r\n}\r\n.btn-delete-thread:disabled { opacity: 0.6; transform: none; }\r\n#deleteThreadModal .form-check-input:checked {\r\n    background-color: #e53e3e;\r\n    border-color: #e53e3e;\r\n}\r\n.mt-method-option {\r\n    cursor: pointer;\r\n    border: 2px solid #dee2e6;\r\n    border-radius: .5rem;\r\n    padding: 1rem;\r\n    margin-bottom: .75rem;\r\n    transition: all .2s;\r\n}\r\n.mt-method-option:hover { background-color: #f8f9fa; }\r\n.mt-method-option.selected {\r\n    border-color: #0d6efd;\r\n    background-color: #e7f1ff;\r\n}\r\n</style>\r\n\r\n<!-- Модалка удаления темы -->\r\n<div class=\"modal fade\" id=\"deleteThreadModal\" tabindex=\"-1\" aria-labelledby=\"deleteThreadModalLabel\" aria-hidden=\"true\">\r\n    <div class=\"modal-dialog modal-dialog-centered modal-lg\">\r\n        <div class=\"modal-content border-0 shadow\">\r\n            <div class=\"modal-header border-0 py-4 text-white\" style=\"background: linear-gradient(135deg, #f56565 0%, #e53e3e 100%);\">\r\n                <h4 class=\"modal-title w-100 text-center mb-0\" id=\"deleteThreadModalLabel\">\r\n                    <i class=\"fas fa-trash-alt me-2\"></i>Delete Thread\r\n                </h4>\r\n                <button type=\"button\" class=\"btn-close btn-close-white position-absolute top-0 end-0 m-3\" data-bs-dismiss=\"modal\"></button>\r\n            </div>\r\n            <div class=\"modal-body p-4\">\r\n                <div class=\"dt-warning-icon\">\r\n                    <i class=\"fas fa-exclamation-triangle\"></i>\r\n                </div>\r\n                <div class=\"dt-thread-preview mb-4\">\r\n                    <div class=\"d-flex align-items-start\">\r\n                        <i class=\"fas fa-file-alt text-danger fs-4 mt-1 me-3\"></i>\r\n                        <div>\r\n                            <h5 class=\"mb-1\" style=\"overflow-wrap:break-word;\">{$thread[\'subject\']}</h5>\r\n                            <div class=\"text-muted small\">\r\n                                <i class=\"fas fa-hashtag me-1\"></i>TID: <strong>{$tid}</strong>\r\n                                &nbsp;&nbsp;\r\n                                <i class=\"fas fa-user me-1\"></i>{$thread[\'username\']}\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class=\"alert alert-danger border-danger mb-4\">\r\n                    <div class=\"d-flex\">\r\n                        <i class=\"fas fa-exclamation-circle text-danger fs-5 me-3 mt-1\"></i>\r\n                        <div>\r\n                            <h5 class=\"alert-heading mb-2\">Permanent Deletion Warning</h5>\r\n                            <p class=\"mb-2 small\">You are about to permanently delete this thread. This action cannot be undone.</p>\r\n                            <ul class=\"dt-consequences-list mt-3\">\r\n                                <li class=\"d-flex align-items-center\"><i class=\"fas fa-comments me-2\"></i>All posts in this thread will be permanently deleted</li>\r\n                                <li class=\"d-flex align-items-center\"><i class=\"fas fa-paperclip me-2\"></i>All attachments will be removed from the server</li>\r\n                                <li class=\"d-flex align-items-center\"><i class=\"fas fa-chart-bar me-2\"></i>Any poll associated with this thread will be deleted</li>\r\n                                <li class=\"d-flex align-items-center\"><i class=\"fas fa-history me-2\"></i>Thread statistics and activity will be lost</li>\r\n                            </ul>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                <div class=\"p-3 bg-light rounded mb-3\">\r\n                    <div class=\"form-check mb-2\">\r\n                        <input class=\"form-check-input\" type=\"checkbox\" id=\"dt_confirm1\">\r\n                        <label class=\"form-check-label fw-bold text-danger\" for=\"dt_confirm1\">\r\n                            <i class=\"fas fa-check-circle me-1\"></i>\r\n                            I understand this action is permanent and cannot be undone\r\n                        </label>\r\n                    </div>\r\n                    <div class=\"form-check\">\r\n                        <input class=\"form-check-input\" type=\"checkbox\" id=\"dt_confirm2\">\r\n                        <label class=\"form-check-label text-muted\" for=\"dt_confirm2\">\r\n                            I have ensured all important content is backed up elsewhere\r\n                        </label>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            <div class=\"card-footer bg-transparent d-flex justify-content-between align-items-center py-3\">\r\n                <button type=\"button\" class=\"btn btn-outline-secondary\" data-bs-dismiss=\"modal\">\r\n                    <i class=\"fas fa-arrow-left me-1\"></i>Cancel\r\n                </button>\r\n                <button type=\"button\" class=\"btn btn-delete-thread text-white\" id=\"confirmDeleteThreadBtn\" disabled>\r\n                    <i class=\"fas fa-trash-alt me-2\"></i>Delete Thread Permanently\r\n                </button>\r\n            </div>\r\n            <div class=\"card-footer bg-transparent border-top-0 text-center pt-0 pb-3\">\r\n                <small class=\"text-muted\"><i class=\"fas fa-shield-alt me-1\"></i>Admin Action • {$SITENAME}</small>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<!-- Модалка слияния тредов -->\r\n<div class=\"modal fade\" id=\"mergeThreadModal\" tabindex=\"-1\" aria-labelledby=\"mergeThreadModalLabel\" aria-hidden=\"true\">\r\n    <div class=\"modal-dialog modal-dialog-centered modal-lg\">\r\n        <div class=\"modal-content border-0 shadow\">\r\n            <div class=\"modal-header bg-primary text-white py-3\">\r\n                <div class=\"d-flex align-items-center gap-2\">\r\n                    <i class=\"fas fa-code-branch fa-lg\"></i>\r\n                    <div>\r\n                        <h5 class=\"modal-title mb-0\" id=\"mergeThreadModalLabel\">Merge Threads</h5>\r\n                        <small class=\"opacity-75\">Combine multiple threads into one</small>\r\n                    </div>\r\n                </div>\r\n                <button type=\"button\" class=\"btn-close btn-close-white\" data-bs-dismiss=\"modal\"></button>\r\n            </div>\r\n            <div class=\"modal-body p-4\">\r\n                <form action=\"moderation.php\" method=\"post\" id=\"mergeThreadForm\">\r\n                    <input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n                    <input type=\"hidden\" name=\"action\" value=\"do_merge\" />\r\n                    <input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n                    <div class=\"p-3 bg-light rounded mb-4 border-start border-primary border-4\">\r\n                        <small class=\"text-muted d-block mb-1\">Current Thread</small>\r\n                        <strong>{$thread[\'subject\']}</strong>\r\n                        <small class=\"text-muted d-block mt-1\">\r\n                            <i class=\"fas fa-hashtag me-1\"></i>Thread ID: {$tid}\r\n                        </small>\r\n                    </div>\r\n                    <div class=\"mb-4\">\r\n                        <label class=\"form-label fw-bold\">\r\n                            <i class=\"fas fa-heading me-1 text-primary\"></i>New Subject\r\n                        </label>\r\n                        <div class=\"input-group\">\r\n                            <span class=\"input-group-text\"><i class=\"fas fa-heading\"></i></span>\r\n                            <input type=\"text\" class=\"form-control\" name=\"subject\"\r\n                                   value=\"{$thread[\'subject\']}\" placeholder=\"Enter new thread subject\" required>\r\n                        </div>\r\n                        <small class=\"text-muted mt-1 d-block\">This will be the new subject for the merged thread</small>\r\n                    </div>\r\n                    <div class=\"mb-4\">\r\n                        <label class=\"form-label fw-bold\">\r\n                            <i class=\"fas fa-link me-1 text-primary\"></i>Thread URL to Merge\r\n                        </label>\r\n                        <div class=\"input-group\">\r\n                            <span class=\"input-group-text\"><i class=\"fas fa-external-link-alt\"></i></span>\r\n                            <input type=\"text\" class=\"form-control\" name=\"threadurl\"\r\n                                   placeholder=\"https://example.com/thread-123\" required>\r\n                        </div>\r\n                        <div class=\"mt-3 p-3 bg-light rounded small\">\r\n                            <h6 class=\"text-primary mb-2\"><i class=\"fas fa-info-circle me-1\"></i>Instructions:</h6>\r\n                            <ul class=\"mb-0 ps-3\">\r\n                                <li>Copy the full URL of the thread you want to merge into this one</li>\r\n                                <li>The thread you specify will be <strong>deleted</strong></li>\r\n                                <li>All posts from that thread will be merged into this one</li>\r\n                                <li>This action cannot be undone</li>\r\n                            </ul>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"alert alert-warning border-warning small\">\r\n                        <div class=\"d-flex\">\r\n                            <i class=\"fas fa-exclamation-triangle text-warning me-2 mt-1\"></i>\r\n                            <div>\r\n                                <strong>Warning:</strong> This action is permanent. Once threads are merged,\r\n                                they cannot be separated. Please double-check the thread URL before proceeding.\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </form>\r\n            </div>\r\n            <div class=\"modal-footer d-flex justify-content-between\">\r\n                <button type=\"button\" class=\"btn btn-outline-secondary btn-sm\" data-bs-dismiss=\"modal\">\r\n                    <i class=\"fas fa-arrow-left me-1\"></i>Cancel\r\n                </button>\r\n                <button type=\"submit\" form=\"mergeThreadForm\" name=\"submit\" class=\"btn btn-primary btn-sm px-4\">\r\n                    <i class=\"fas fa-code-branch me-1\"></i>Merge Threads\r\n                </button>\r\n            </div>\r\n            <div class=\"card-footer bg-transparent border-top-0 text-center py-2\">\r\n                <small class=\"text-muted\"><i class=\"fas fa-shield-alt me-1\"></i>Moderation Action • {$SITENAME}</small>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<!-- Модалка перемещения треда -->\r\n<div class=\"modal fade\" id=\"moveThreadModal\" tabindex=\"-1\" aria-labelledby=\"moveThreadModalLabel\" aria-hidden=\"true\">\r\n    <div class=\"modal-dialog modal-dialog-centered modal-lg\">\r\n        <div class=\"modal-content border-0 shadow\">\r\n            <div class=\"modal-header bg-primary text-white py-3\">\r\n                <div class=\"d-flex align-items-center gap-2\">\r\n                    <i class=\"fas fa-exchange-alt fa-lg\"></i>\r\n                    <div>\r\n                        <h5 class=\"modal-title mb-0\" id=\"moveThreadModalLabel\">Move / Copy Thread</h5>\r\n                        <small class=\"opacity-75\">Transfer thread to another forum</small>\r\n                    </div>\r\n                </div>\r\n                <button type=\"button\" class=\"btn-close btn-close-white\" data-bs-dismiss=\"modal\"></button>\r\n            </div>\r\n            <div class=\"modal-body p-4\">\r\n                <form action=\"moderation.php\" method=\"post\" id=\"moveThreadForm\">\r\n                    <input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n                    <input type=\"hidden\" name=\"action\" value=\"do_move\" />\r\n                    <input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n\r\n                    <!-- Инфо о треде -->\r\n                    <div class=\"row text-center mb-4 g-2\">\r\n                        <div class=\"col-md-4\">\r\n                            <div class=\"p-3 bg-light rounded\">\r\n                                <i class=\"fas fa-comment text-primary mb-1 d-block\"></i>\r\n                                <div class=\"fw-bold small\">Title</div>\r\n                                <div class=\"small text-muted\" style=\"overflow-wrap:break-word;\">{$thread[\'subject\']}</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-md-4\">\r\n                            <div class=\"p-3 bg-light rounded\">\r\n                                <i class=\"fas fa-hashtag text-primary mb-1 d-block\"></i>\r\n                                <div class=\"fw-bold small\">Thread ID</div>\r\n                                <div class=\"small text-muted\">#{$tid}</div>\r\n                            </div>\r\n                        </div>\r\n                        <div class=\"col-md-4\">\r\n                            <div class=\"p-3 bg-light rounded\">\r\n                                <i class=\"fas fa-user text-primary mb-1 d-block\"></i>\r\n                                <div class=\"fw-bold small\">Author</div>\r\n                                <div class=\"small text-muted\">{$thread[\'username\']}</div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Форум назначения -->\r\n                    <div class=\"mb-4\">\r\n                        <label class=\"form-label fw-bold\">\r\n                            <i class=\"fas fa-folder me-2 text-primary\"></i>Destination Forum\r\n                        </label>\r\n                        {$forumjump}\r\n                        <div class=\"form-text\">Select the forum where you want to move or copy this thread.</div>\r\n                    </div>\r\n\r\n                    <!-- Метод -->\r\n                    <div class=\"mb-3\">\r\n                        <label class=\"form-label fw-bold\">\r\n                            <i class=\"fas fa-cogs me-2 text-primary\"></i>Transfer Method\r\n                        </label>\r\n\r\n                        <div class=\"mt-method-option\" onclick=\"mtSelectMethod(\'move\', this)\">\r\n                            <div class=\"d-flex align-items-center\">\r\n                                <i class=\"fas fa-arrow-right fa-lg me-3 text-primary\"></i>\r\n                                <div class=\"flex-grow-1\">\r\n                                    <div class=\"fw-bold small\">Move Thread</div>\r\n                                    <small class=\"text-muted\">Transfer to new forum (original will be removed)</small>\r\n                                </div>\r\n                                <div class=\"mt-radio-circle border border-primary rounded-circle d-flex align-items-center justify-content-center\" style=\"width:20px;height:20px;\">\r\n                                    <div class=\"mt-radio-inner rounded-circle bg-primary\" style=\"width:10px;height:10px;display:none;\"></div>\r\n                                </div>\r\n                            </div>\r\n                            <input type=\"radio\" name=\"method\" value=\"move\" class=\"d-none\" />\r\n                        </div>\r\n\r\n                        <div class=\"mt-method-option selected\" onclick=\"mtSelectMethod(\'redirect\', this)\">\r\n                            <div class=\"d-flex align-items-center\">\r\n                                <i class=\"fas fa-link fa-lg me-3 text-primary\"></i>\r\n                                <div class=\"flex-grow-1\">\r\n                                    <div class=\"fw-bold small\">Move with Redirect</div>\r\n                                    <small class=\"text-muted\">Move and leave redirect link in original forum</small>\r\n                                </div>\r\n                                <div class=\"mt-radio-circle border border-primary rounded-circle d-flex align-items-center justify-content-center\" style=\"width:20px;height:20px;\">\r\n                                    <div class=\"mt-radio-inner rounded-circle bg-primary\" style=\"width:10px;height:10px;\"></div>\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"mt-2\">\r\n                                <input type=\"number\" name=\"redirect_expire\" class=\"form-control form-control-sm\"\r\n                                       placeholder=\"Redirect days (leave blank for infinite)\" min=\"1\" max=\"365\" />\r\n                            </div>\r\n                            <input type=\"radio\" name=\"method\" value=\"redirect\" checked class=\"d-none\" />\r\n                        </div>\r\n\r\n                        <div class=\"mt-method-option\" onclick=\"mtSelectMethod(\'copy\', this)\">\r\n                            <div class=\"d-flex align-items-center\">\r\n                                <i class=\"fas fa-copy fa-lg me-3 text-primary\"></i>\r\n                                <div class=\"flex-grow-1\">\r\n                                    <div class=\"fw-bold small\">Copy Thread</div>\r\n                                    <small class=\"text-muted\">Create a copy in new forum (original remains)</small>\r\n                                </div>\r\n                                <div class=\"mt-radio-circle border border-primary rounded-circle d-flex align-items-center justify-content-center\" style=\"width:20px;height:20px;\">\r\n                                    <div class=\"mt-radio-inner rounded-circle bg-primary\" style=\"width:10px;height:10px;display:none;\"></div>\r\n                                </div>\r\n                            </div>\r\n                            <input type=\"radio\" name=\"method\" value=\"copy\" class=\"d-none\" />\r\n                        </div>\r\n                    </div>\r\n\r\n                </form>\r\n            </div>\r\n            <div class=\"modal-footer d-flex justify-content-between\">\r\n                <button type=\"button\" class=\"btn btn-outline-secondary btn-sm\" data-bs-dismiss=\"modal\">\r\n                    <i class=\"fas fa-arrow-left me-1\"></i>Cancel\r\n                </button>\r\n                <button type=\"submit\" form=\"moveThreadForm\" name=\"submit\" value=\"Move / Copy Thread\" class=\"btn btn-primary btn-sm px-4\">\r\n                    <i class=\"fas fa-exchange-alt me-1\"></i>Process Thread\r\n                </button>\r\n            </div>\r\n            <div class=\"card-footer bg-transparent border-top-0 text-center py-2\">\r\n                <small class=\"text-muted\"><i class=\"fas fa-shield-alt me-1\"></i>Moderation Action • {$SITENAME}</small>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<script type=\"text/javascript\">\r\n<!--\r\ndocument.addEventListener(\'DOMContentLoaded\', function() {\r\n    var selector    = document.getElementById(\"moderator_options_selector\");\r\n    var form        = document.getElementById(\"moderator_options\");\r\n    var confirm1    = document.getElementById(\'dt_confirm1\');\r\n    var confirm2    = document.getElementById(\'dt_confirm2\');\r\n    var confirmBtn  = document.getElementById(\'confirmDeleteThreadBtn\');\r\n    var deleteModal = null;\r\n    var mergeModal  = null;\r\n    var moveModal   = null;\r\n\r\n    if (typeof bootstrap !== \'undefined\') {\r\n        var deleteModalEl = document.getElementById(\'deleteThreadModal\');\r\n        if (deleteModalEl) {\r\n            deleteModal = new bootstrap.Modal(deleteModalEl);\r\n            deleteModalEl.addEventListener(\'hidden.bs.modal\', function() {\r\n                confirm1.checked = false;\r\n                confirm2.checked = false;\r\n                confirmBtn.disabled  = true;\r\n                confirmBtn.innerHTML = \'<i class=\"fas fa-trash-alt me-2\"></i>Delete Thread Permanently\';\r\n            });\r\n        }\r\n\r\n        var mergeModalEl = document.getElementById(\'mergeThreadModal\');\r\n        if (mergeModalEl) {\r\n            mergeModal = new bootstrap.Modal(mergeModalEl);\r\n            mergeModalEl.addEventListener(\'hidden.bs.modal\', function() {\r\n                var urlInput = document.querySelector(\'#mergeThreadForm input[name=\"threadurl\"]\');\r\n                if (urlInput) { urlInput.value = \'\'; }\r\n            });\r\n        }\r\n\r\n        var moveModalEl = document.getElementById(\'moveThreadModal\');\r\n        if (moveModalEl) {\r\n            moveModal = new bootstrap.Modal(moveModalEl);\r\n        }\r\n    }\r\n\r\n    function checkConfirm() {\r\n        confirmBtn.disabled = !(confirm1.checked && confirm2.checked);\r\n    }\r\n    confirm1.addEventListener(\'change\', checkConfirm);\r\n    confirm2.addEventListener(\'change\', checkConfirm);\r\n\r\n    if (selector && form) {\r\n        form.addEventListener(\'submit\', function(e) {\r\n\r\n            if (selector.value === \'deletethread\') {\r\n                e.preventDefault();\r\n                var oldForm = document.getElementById(\'deleteThreadHiddenForm\');\r\n                if (oldForm) { oldForm.remove(); }\r\n                var hiddenForm       = document.createElement(\'form\');\r\n                hiddenForm.method    = \'post\';\r\n                hiddenForm.action    = \'moderation.php\';\r\n                hiddenForm.style.display = \'none\';\r\n                hiddenForm.id        = \'deleteThreadHiddenForm\';\r\n                var fields = {\r\n                    \'my_post_key\': document.querySelector(\'#moderator_options input[name=\"my_post_key\"]\').value,\r\n                    \'modtype\':     \'thread\',\r\n                    \'tid\':         \'{$tid}\',\r\n                    \'action\':      \'do_deletethread\'\r\n                };\r\n                for (var key in fields) {\r\n                    var input   = document.createElement(\'input\');\r\n                    input.type  = \'hidden\';\r\n                    input.name  = key;\r\n                    input.value = fields[key];\r\n                    hiddenForm.appendChild(input);\r\n                }\r\n                document.body.appendChild(hiddenForm);\r\n                confirmBtn.onclick = function() {\r\n                    if (!confirm1.checked || !confirm2.checked) { return; }\r\n                    confirmBtn.disabled  = true;\r\n                    confirmBtn.innerHTML = \'<i class=\"fas fa-spinner fa-spin me-2\"></i>Deleting...\';\r\n                    hiddenForm.submit();\r\n                    if (deleteModal) { deleteModal.hide(); }\r\n                };\r\n                if (deleteModal) { deleteModal.show(); }\r\n                return;\r\n            }\r\n\r\n            if (selector.value === \'merge\') {\r\n                e.preventDefault();\r\n                if (mergeModal) { mergeModal.show(); }\r\n                return;\r\n            }\r\n\r\n            if (selector.value === \'move\') {\r\n                e.preventDefault();\r\n                if (moveModal) { moveModal.show(); }\r\n                return;\r\n            }\r\n\r\n            // Остальные действия — сабмит как обычно\r\n        });\r\n\r\n        selector.addEventListener(\'change\', function() {\r\n            form.dispatchEvent(new Event(\'submit\'));\r\n        });\r\n    }\r\n});\r\n\r\nfunction mtSelectMethod(method, el) {\r\n    document.querySelectorAll(\'.mt-method-option\').forEach(function(opt) {\r\n        opt.classList.remove(\'selected\');\r\n        opt.querySelector(\'.mt-radio-inner\').style.display = \'none\';\r\n        opt.querySelector(\'input[type=radio]\').checked = false;\r\n    });\r\n    el.classList.add(\'selected\');\r\n    el.querySelector(\'.mt-radio-inner\').style.display = \'block\';\r\n    el.querySelector(\'input[type=radio]\').checked = true;\r\n}\r\n//-->\r\n</script>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1516','showthread_newreply','<a href=\"newreply.php?tid={$tid}\" class=\"btn btn-primary\" type=\"button\"><i class=\"fa-solid fa-comment\"></i> &nbsp;{$lang->showthread[\'post_reply\']}</a>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1517','showthread_newreply_closed','<button class=\"btn btn-primary\" disabled>{$lang->thread_closed}</button>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1518','showthread_poll','<form action=\"polls.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<input type=\"hidden\" name=\"action\" value=\"vote\" />\r\n<input type=\"hidden\" name=\"pid\" value=\"{$poll[\'pid\']}\" />\r\n	\r\n				<div class=\"card border-0 mb-4\">\r\n	<div class=\"card-header rounded text-19 fw-bold\">\r\n		{$poll[\'question\']}<span class=\"badge bg-primary border border-white float-end text-uppercase small fw-normal\">{$lang->poll}</span>\r\n	</div>\r\n	<div class=\"card-body\">\r\n		<div class=\"row pb-3\">\r\n			<div class=\"col\">\r\n <span class=\"text-desc\">{$publicnote} {$closeon}</span>\r\n			</div>\r\n		</div>\r\n{$polloptions}\r\n		\r\n</div>\r\n					<div class=\"card-footer border-top-0 rounded\">\r\n						\r\n						<div class=\"row g-1\">\r\n							<div class=\"col-auto\">\r\n						 <button type=\"submit\" class=\"btn btn-primary btn-sm\" value=\"{$lang->vote}\">{$lang->vote}</button>\r\n							</div>\r\n							<div class=\"col text-end align-self-center\">\r\n								{$edit_poll} <a href=\"polls.php?action=showresults&amp;pid={$poll[\'pid\']}\"><i class=\"fa-solid fa-square-poll-horizontal\"></i> {$lang->show_results}</a>\r\n							</div>\r\n						</div>\r\n					\r\n				\r\n					\r\n				\r\n\r\n					</div></div>\r\n</form>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1519','showthread_poll_editpoll','<a href=\"polls.php?action=editpoll&amp;pid={$poll[\'pid\']}\" title=\"{$lang->edit_poll}\"><i class=\"fa-solid fa-pencil\"></i> {$lang->edit_poll}</a>&nbsp;&nbsp;','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1520','showthread_poll_option','<div class=\"row py-3 border-top text-forum\">\r\n	<div class=\"col\" style=\"margin-bottom: 4px; width: 20px\">\r\n<label class=\"text-forum fw-normal\"><input type=\"radio\" class=\"form-check-input\" name=\"option\" id=\"option_{$number}\" value=\"{$number}\" /> &nbsp;&nbsp;{$option}</label>\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1521','showthread_poll_option_multiple','<div class=\"row py-3 border-top text-forum\">\r\n	<div class=\"col\" style=\"margin-bottom: 4px; width: 20px\">\r\n<label class=\"text-forum fw-normal\"><input type=\"checkbox\" class=\"form-check-input\" name=\"option[{$number}]\" id=\"option_{$number}\" value=\"1\" />&nbsp;&nbsp;{$option}</label>\r\n	</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1522','showthread_poll_resultbit','<div class=\"row pt-3 border-top text-forum\">\r\n<div class=\"col-auto text-forum\">\r\n	{$option}{$votestar}\r\n</div>\r\n	<div class=\"col-lg text-end align-self-center\">\r\n	 {$votes} ({$percent}%)\r\n	</div>\r\n</div>\r\n<div class=\"row pb-3 text-forum\">\r\n	\r\n	\r\n	<div class=\"col-lg\">\r\n	<div class=\"progress mb-1\" style=\"height: 25px\">\r\n  <div class=\"progress-bar pg-primary\" role=\"progressbar\" style=\"width:{$percent}%\"  aria-valuenow=\"{$percent}\" aria-valuemin=\"0\" aria-valuemax=\"100\"></div>\r\n</div>\r\n</div>	\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1523','showthread_poll_results','<div class=\"card border-0 mb-4\">\r\n	<div class=\"card-header rounded text-19 fw-bold\">\r\n		{$poll[\'question\']}<span class=\"badge bg-primary border border-white float-end text-uppercase small fw-normal\">{$lang->poll}</span>\r\n	</div>\r\n	<div class=\"card-body\">\r\n		<div class=\"row pb-3\">\r\n			<div class=\"col\">\r\n <span class=\"text-desc\">{$pollstatus} {$undovote} {$publicnote} {$closeon}</span>\r\n			</div>\r\n		</div>\r\n{$polloptions}\r\n		<div class=\"text-end\"><span class=\"text-forum\">{$lang->total} {$lang->total_votes} {$totpercent}</span></div>\r\n</div>\r\n					<div class=\"card-footer border-top-0 rounded\">\r\n						\r\n						<div class=\"row g-1\">\r\n							<div class=\"col-auto\">\r\n						 <button type=\"submit\" class=\"btn btn-primary btn-sm\" value=\"{$lang->vote}\">{$lang->vote}</button>\r\n							</div>\r\n							<div class=\"col text-end align-self-center\">\r\n								{$edit_poll} &nbsp; <a href=\"polls.php?action=showresults&amp;pid={$poll[\'pid\']}\"><i class=\"fa-solid fa-square-poll-horizontal\"></i> {$lang->show_results}</a>\r\n							</div>\r\n						</div>\r\n				</div></div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1524','showthread_printthread','<a href=\"printthread.php?tid={$tid}\" class=\"links\"><i class=\"fa-solid fa-print\" title=\"{$lang->view_printable}\"></i></a>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1525','showthread_quickreply','<div id=\"quickreply_spinner\" class=\"showthread_spinner\" style=\"display: none\"><i class=\"fa-solid fa-circle-notch fa-spin\" style=\"color: #0b59e0;\"></i></div>\r\n\r\n{$moderation_notice}\r\n<form method=\"post\" action=\"newreply.php?tid={$tid}&amp;processed=1\" name=\"quick_reply_form\" id=\"quick_reply_form\">\r\n	<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n	<input type=\"hidden\" name=\"subject\" value=\"RE: {$reply_subject}\" />\r\n	<input type=\"hidden\" name=\"action\" value=\"do_newreply\" />\r\n	<input type=\"hidden\" name=\"posthash\" value=\"{$posthash}\" id=\"posthash\" />\r\n	<input type=\"hidden\" name=\"quoted_ids\" value=\"\" id=\"quoted_ids\" />\r\n	<input type=\"hidden\" name=\"lastpid\" id=\"lastpid\" value=\"{$last_pid}\" />\r\n	<input type=\"hidden\" name=\"from_page\" value=\"{$page}\" />\r\n	<input type=\"hidden\" name=\"tid\" value=\"{$tid}\" />\r\n	<input type=\"hidden\" name=\"method\" value=\"quickreply\" />\r\n	\r\n	\r\n	\r\n<div class=\"row d-flex g-2 mb-4 mt-5\">\r\n    <div class=\"col-auto d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\"><img src=\"{$CURUSER[\'avatar\']}\" class=\"rounded d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block img-fluid\" style=\"width: 100px;\"></div>\r\n    <div class=\"col\">\r\n		<div class=\"editor_control_bar mb-3 border border-top-5 p-2\" id=\"quickreply_multiquote\" style=\"display: none;\">\r\n					{$lang->showthread[\'quickreply_multiquote_selected\']} <a href=\"./newreply.php?tid={$tid}&amp;load_all_quotes=1\" onclick=\"return Thread.loadMultiQuoted();\">{$lang->showthread[\'quickreply_multiquote_now\']}</a> {$lang->showthread[\'or\']} <a href=\"javascript:void(0)\" onclick=\"Thread.clearMultiQuoted(); return false;\">{$lang->showthread[\'quickreply_multiquote_deselect\']}</a>.\r\n		</div>\r\n        <div class=\"card\">\r\n            <div class=\"card-body\">\r\n				<h6 class=\"mb-2\">{$CURUSER[\'username\']}</h6>\r\n		<textarea class=\"form-control form-control-sm border-0 p-0\" style=\"resize: none; height: 150px;\"  name=\"message\" id=\"message\" tabindex=\"1\" placeholder=\"Write a reply to this message...\"></textarea>\r\n			\r\n				\r\n	<div id=\"collapse-reply\" class=\"collapse bg-nav p-2\">\r\n{$closeoption}\r\n </div>\r\n				</div>\r\n			\r\n				<div class=\"card-footer border-top-0\">\r\n					<button type=\"submit\" class=\"btn btn-primary\" value=\"{$lang->showthread[\'post_reply\']}\" tabindex=\"2\" accesskey=\"s\" id=\"quick_reply_submit\"><i class=\"fa-solid fa-comment\"></i> &nbsp;{$lang->showthread[\'post_reply\']}</button> <a class=\"btn btn-thread ms-3 me-3\" data-bs-toggle=\"collapse\" aria-expanded=\"false\" aria-controls=\"collapse-1\" href=\"#collapse-reply\" role=\"button\"><i class=\"fa-solid fa-gear\"></i></a> <button type=\"submit\" class=\"btn btn-thread\" name=\"previewpost\" value=\"{$lang->showthread[\'preview_post\']}\" tabindex=\"3\"><i class=\"fa-solid fa-pencil\"></i> &nbsp;{$lang->showthread[\'preview_post\']}</button>\r\n				</div>\r\n			</div>\r\n	</div>\r\n	</div>\r\n	</div>\r\n\r\n	\r\n</form>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1526','showthread_quickreply_options_close','<input type=\"checkbox\" class=\"form-check-input\" name=\"modoptions[closethread]\" value=\"1\"{$closelinkch} /> {$lang->close_thread} <br />','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1527','showthread_quickreply_options_signature','<input type=\"checkbox\" class=\"form-check-input\" name=\"postoptions[signature]\" value=\"1\" {$postoptionschecked[\'signature\']} /> {$lang->showthread[\'signature\']} <br />','2','1837','','1720609281');
