INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1580','usercp_latest_subscribed_threads','<div class=\"d-none d-sm-none d-md-none d-lg-block d-xl-block d-xxl-block\">\r\n<div class=\"row pe-3 ps-3 pb-3\">\r\n	<div class=\"col-auto p-2 align-self-center d-flex justify-content-center\" style=\"width:auto\">\r\n		<i class=\"bi bi-chat\"></i>\r\n	\r\n	</div>\r\n\r\n		<div class=\"col-5 align-self-center\">\r\n			\r\n			<a href=\"{$thread[\'threadlink\']}\" style=\"font-size: 18px; font-weight: 600\">{$thread[\'subject\']}</a> <br />\r\n			<span class=\"text-muted\" style=\"font-size: 14px\">\r\n				<span class=\"lastpostbit\">{$thread[\'author\']}</span> \r\n			</span>\r\n			\r\n		</div>\r\n		<div class=\"col-auto align-items-center d-flex justify-content-center\">\r\n			\r\n			{$thread[\'threadprefix\']}\r\n			\r\n		</div>\r\n		\r\n			\r\n			\r\n		<div class=\"col-2 text-end align-self-center\">\r\n			\r\n			<span class=\"text-muted\" style=\"font-size: 14px\">{$lang->replies}</span> <span style=\"font-size: 14px\">{$thread[\'replies\']}</span><br />\r\n			<span class=\"text-muted\" style=\"font-size: 14px\">{$lang->views}</span> <span style=\"font-size: 14px\">{$thread[\'views\']}</span>\r\n			\r\n		</div>\r\n		<div class=\"col-auto text-center\" style=\"padding-left: 30px\">\r\n			\r\n			<avatarep_uid_[{$thread[\'lastposteruid\']}]>\r\n				\r\n		</div>\r\n			<div class=\"col-auto text-start align-self-center\">\r\n				\r\n				<span class=\"lastpostbit mb-0\" style=\"font-size: 14px\">{$lastposterlink}</span> \r\n				<span class=\"text-muted mt-0\" style=\"font-size: 14px\"><avatarep_uid_[{$thread[\'lastposteruid\']}]>{$lastpostdate}</span>\r\n				\r\n			</div>\r\n			\r\n			\r\n	</div>\r\n</div>\r\n	\r\n		<div class=\"d-block d-sm-block d-md-block d-lg-none d-xl-none d-xxl-none\">\r\n	<div class=\"card border-0\">\r\n    <div class=\"card-body border-0\">\r\n        <h4 class=\"card-title\"><a href=\"{$thread[\'threadlink\']}\">{$thread[\'subject\']}</a></h4>\r\n        <h6 class=\"text-muted card-subtitle\"><span class=\"lastpostbit\">{$thread[\'author\']}</span></h6>\r\n        <p class=\"card-text text-muted\">{$lang->replies} {$thread[\'replies\']}, {$lang->views} {$thread[\'views\']}</p>\r\n        <div class=\"row p-3 bg-light m-0 rounded\">\r\n			<div class=\"col-auto align-self-center\"><avatarep_uid_[{$thread[\'lastposteruid\']}]></div>\r\n            <div class=\"col align-self-center\">{$lastposterlink}<span class=\"text-muted\"><avatarep_uid_[{$thread[\'lastposteruid\']}]>{$lastpostdate}</span></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n		</div>','2','1830','','1720609281');
