INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1582','usercp_latest_threads_threads','<div class=\"row p-3\">\r\n<div class=\"col-auto align-self-center\">\r\n<avatarep_uid_[{$thread[\'lastposteruid\']}]>\r\n</div>\r\n<div class=\"col align-self-center\">\r\n<a href=\"{$thread[\'threadlink\']}\">{$thread[\'subject\']}</a><br />\r\n<span class=\"little text-muted\">{$lang->replies} {$thread[\'replies\']} / {$lang->views} {$thread[\'views\']}</span>\r\n</div>\r\n<div class=\"col-auto text-end align-self-center text-muted little\">\r\n<span class=\"lastpostbit\">{$lastposterlink}</span> replied {$lastpostdate}\r\n</div></div>','2','1837','','1720609281');
