INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1592','usercp_nav_misc','<div class=\"user-cp-nav d-flex flex-column gap-2\">\r\n  \r\n    <div class=\"nav-section\">\r\n       \r\n        <a href=\"usercp.php?action=editlists\" class=\"btn btn-menu d-flex align-items-center\">\r\n            <i class=\"fa-solid fa-user-group fa-fw me-2\"></i>\r\n            <span>{$lang->usercpnav[\'ucp_nav_editlists\']}</span>\r\n        </a>\r\n    </div>\r\n\r\n    \r\n   \r\n    <div class=\"nav-section\">\r\n        {$attachmentop}\r\n    </div>\r\n    \r\n\r\n    <!-- Контент и подписки -->\r\n    <div class=\"nav-section\">\r\n        <a href=\"usercp.php?action=drafts\" class=\"btn btn-menu d-flex align-items-center\">\r\n            <i class=\"fa-solid fa-pen-ruler fa-fw me-2\"></i>\r\n            <span class=\"badge bg-secondary ms-auto\">{$draftcount}</span>\r\n        </a>\r\n        <a href=\"usercp.php?action=subscriptions\" class=\"btn btn-menu d-flex align-items-center\">\r\n            <i class=\"fa-solid fa-comment fa-fw me-2\"></i>\r\n            <span>{$lang->usercpnav[\'ucp_nav_subscribed_threads\']}</span>\r\n        </a>\r\n        <a href=\"usercp.php?action=forumsubscriptions\" class=\"btn btn-menu d-flex align-items-center\">\r\n            <i class=\"fa-solid fa-eye fa-fw me-2\"></i>\r\n            <span>{$lang->usercpnav[\'ucp_nav_forum_subscriptions\']}</span>\r\n        </a>\r\n    </div>\r\n\r\n    <!-- Закладки и файлы -->\r\n    <div class=\"nav-section\">\r\n        <a href=\"usercp.php?action=bookmarks\" class=\"btn btn-menu d-flex align-items-center\">\r\n            <i class=\"fa-solid fa-bookmark fa-fw me-2\"></i>\r\n            <span>{$lang->usercpnav[\'ucp_nav_book\']}</span>\r\n        </a>\r\n        <a href=\"usercp.php?action=manage_files\" class=\"btn btn-menu d-flex align-items-center\">\r\n            <i class=\"fa-solid fa-folder-open fa-fw me-2\"></i>\r\n            <span>My Files</span>\r\n        </a>\r\n    </div>\r\n\r\n    <!-- Профиль -->\r\n    <div class=\"nav-section mt-3\">\r\n        <a href=\"{$profile_link}\" class=\"btn btn-menu btn-profile d-flex align-items-center\">\r\n            <i class=\"fa-solid fa-id-card-clip fa-fw me-2\"></i>\r\n            <span>{$lang->usercpnav[\'ucp_nav_view_profile\']}</span>\r\n            <i class=\"fa-solid fa-arrow-up-right-from-square ms-auto text-muted small\"></i>\r\n        </a>\r\n    </div>\r\n</div>\r\n\r\n<style>\r\n.user-cp-nav {\r\n    padding: 1rem;\r\n}\r\n\r\n.nav-section {\r\n    padding: 0.5rem 0;\r\n    border-bottom: 1px solid rgba(0,0,0,0.05);\r\n}\r\n\r\n.nav-section:last-child {\r\n    border-bottom: none;\r\n}\r\n\r\n.btn-menu {\r\n    text-align: left;\r\n    padding: 0.75rem 1rem;\r\n    border-radius: 8px;\r\n    transition: all 0.2s ease;\r\n    color: #495057;\r\n    background: #f8f9fa;\r\n    border: 1px solid transparent;\r\n    margin-bottom: 0.25rem;\r\n}\r\n\r\n.btn-menu:hover {\r\n    background: #e9ecef;\r\n    border-color: #dee2e6;\r\n    color: #0d6efd;\r\n    transform: translateX(3px);\r\n}\r\n\r\n.btn-menu .badge {\r\n    font-size: 0.75em;\r\n    padding: 0.25em 0.5em;\r\n}\r\n\r\n.btn-profile {\r\n    background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);\r\n    border: 1px solid #dee2e6;\r\n}\r\n\r\n.btn-profile:hover {\r\n    background: linear-gradient(135deg, #e9ecef 0%, #dde1e6 100%);\r\n    border-color: #0d6efd;\r\n}\r\n</style>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1593','usercp_nav_profile','<div>\r\n<a class=\"btn btn-menu\"data-bs-toggle=\"collapse\" aria-expanded=\"false\" aria-controls=\"collapse-1\" href=\"#collapse-modu\" role=\"button\"><i class=\"fa-solid fa-gears me-2\"></i>{$lang->usercpnav[\'ucp_nav_profile\']}</a>\r\n								\r\n<div id=\"collapse-modu\" class=\"collapse bg-transparent\">\r\n<ul class=\"list-group list-group-flush\">\r\n<a href=\"usercp.php?action=profile\" class=\"btn btn-menu-coll\"><i class=\"fa-solid fa-user-pen ms-2\"></i> &nbsp;&nbsp; {$lang->usercpnav[\'ucp_nav_edit_profile\']}</a>\r\n{$changenameop}\r\n<a href=\"usercp.php?action=password\" class=\"btn btn-menu-coll\"><i class=\"fa-solid fa-key ms-2\"></i> &nbsp;&nbsp; {$lang->usercpnav[\'ucp_nav_change_pass\']}</a>\r\n<a href=\"usercp.php?action=email\" class=\"btn btn-menu-coll\"><i class=\"fa-solid fa-at ms-2\"></i> &nbsp;&nbsp; {$lang->usercpnav[\'ucp_nav_change_email\']}</a>     \r\n<a href=\"usercp.php?action=avatar\" class=\"btn btn-menu-coll\"><i class=\"fa-solid fa-image ms-2\"></i> &nbsp;&nbsp; {$lang->usercpnav[\'ucp_nav_change_avatar\']}</a>	\r\n{$changesigop} \r\n<a href=\"usercp.php?action=options\" class=\"btn btn-menu-coll\"><i class=\"fa-solid fa-gears ms-2\"></i> &nbsp;&nbsp; {$lang->usercpnav[\'ucp_nav_edit_options\']}</a>\r\n</ul>\r\n	\r\n</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1594','usercp_notepad','<form action=\"usercp.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"card mb-4\">\r\n<div class=\"card-body\">\r\n	<label><strong>{$lang->personal_notepad}</strong></label>\r\n	\r\n\r\n	<textarea name=\"notepad\" id=\"notepad\" cols=\"1\" rows=\"10\" class=\"form-control form-control-sm border\" style=\"height: 200px; resize: none\">{$mybb->user[\'notepad\']}</textarea>\r\n		</div>\r\n	<div class=\"card-footer text-center\">\r\n		<input type=\"hidden\" name=\"action\" value=\"do_notepad\" />\r\n<button type=\"submit\" class=\"btn btn-primary\" name=\"submit\" value=\"{$lang->update_notepad}\" /><i class=\"fa-solid fa-note-sticky\"></i> &nbsp;{$lang->update_notepad}</button>\r\n</form>\r\n</div>\r\n</div>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1595','usercp_options','<!DOCTYPE html>\r\n<html lang=\"en\" data-bs-theme=\"light\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <title>{$SITENAME} - {$lang->usercp[\'edit_options\']} | Настройки профиля</title>\r\n    \r\n    <!-- Bootstrap Icons -->\r\n    \r\n    <link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css\">\r\n    \r\n    <style>\r\n        /* ========= ПОДДЕРЖКА ТЕМ ЧЕРЕЗ DATA-BS-THEME ========= */\r\n        /* Светлая тема (по умолчанию) */\r\n        :root,\r\n        [data-bs-theme=\"light\"] {\r\n            --bg-primary: #ffffff;\r\n            --bg-secondary: #f8fafc;\r\n            --bg-card: #ffffff;\r\n            --bg-nav: linear-gradient(135deg, #f0f5fa 0%, #e9eef3 100%);\r\n            --text-primary: #1e293b;\r\n            --text-secondary: #2c3e4e;\r\n            --text-muted: #64748b;\r\n            --border-color: #e2e8f0;\r\n            --border-light: #e0edf5;\r\n            --input-bg: #fefefe;\r\n            --input-border: #cfdfed;\r\n            --shadow: 0 8px 20px rgba(0,0,0,0.05);\r\n            --shadow-hover: 0 12px 28px rgba(0,0,0,0.1);\r\n            --category-bg: #fafdff;\r\n            --category-border: #e9f0f5;\r\n            --info-bg: #f0f9ff;\r\n            --card-footer-bg: #ffffff;\r\n            --btn-primary: #2c7da0;\r\n            --btn-primary-hover: #1f5e7a;\r\n            --icon-primary: #2c7da0;\r\n            --icon-secondary: #64748b;\r\n            --icon-success: #10b981;\r\n            --icon-warning: #f59e0b;\r\n            --icon-danger: #ef4444;\r\n            --icon-info: #3b82f6;\r\n        }\r\n        \r\n        /* Темная тема */\r\n        [data-bs-theme=\"dark\"] {\r\n            --bg-primary: #0f172a;\r\n            --bg-secondary: #1e293b;\r\n            --bg-card: #1e293b;\r\n            --bg-nav: linear-gradient(135deg, #1e293b 0%, #0f172a 100%);\r\n            --text-primary: #f1f5f9;\r\n            --text-secondary: #cbd5e1;\r\n            --text-muted: #94a3b8;\r\n            --border-color: #334155;\r\n            --border-light: #2d3a4e;\r\n            --input-bg: #0f172a;\r\n            --input-border: #334155;\r\n            --shadow: 0 8px 20px rgba(0,0,0,0.3);\r\n            --shadow-hover: 0 12px 28px rgba(0,0,0,0.4);\r\n            --category-bg: #0f172a;\r\n            --category-border: #334155;\r\n            --info-bg: #1e2a3a;\r\n            --card-footer-bg: #1e293b;\r\n            --btn-primary: #3b82f6;\r\n            --btn-primary-hover: #2563eb;\r\n            --icon-primary: #3b82f6;\r\n            --icon-secondary: #94a3b8;\r\n            --icon-success: #34d399;\r\n            --icon-warning: #fbbf24;\r\n            --icon-danger: #f87171;\r\n            --icon-info: #60a5fa;\r\n        }\r\n        \r\n        \r\n        .card {\r\n            background: var(--bg-card);\r\n            border: none;\r\n            border-radius: 1.25rem;\r\n            box-shadow: var(--shadow);\r\n            overflow: hidden;\r\n            transition: all 0.3s ease;\r\n        }\r\n        \r\n        .card:hover {\r\n            box-shadow: var(--shadow-hover);\r\n        }\r\n        \r\n        .card-body {\r\n            padding: 1.8rem;\r\n        }\r\n        \r\n        .card-footer {\r\n            background: var(--card-footer-bg);\r\n            border-top: 1px solid var(--border-color);\r\n            padding: 1.2rem;\r\n        }\r\n        \r\n        .bg-nav {\r\n            background: var(--bg-nav);\r\n            font-weight: 600;\r\n            color: var(--text-primary);\r\n            border-left: 4px solid var(--btn-primary);\r\n            font-size: 1rem;\r\n            transition: all 0.3s ease;\r\n        }\r\n        \r\n        .border-bottom {\r\n            border-bottom: 1px solid var(--border-color) !important;\r\n        }\r\n        \r\n        .form-check-label, label {\r\n            font-weight: 500;\r\n            color: var(--text-secondary);\r\n            transition: color 0.3s ease;\r\n        }\r\n        \r\n        .form-check-input {\r\n            background-color: var(--input-bg);\r\n            border-color: var(--input-border);\r\n            transition: all 0.2s ease;\r\n        }\r\n        \r\n        \r\n        \r\n        .form-select, .form-select-sm {\r\n            border-radius: 0.75rem;\r\n            background-color: var(--input-bg);\r\n            border: 1px solid var(--input-border);\r\n            color: var(--text-primary);\r\n            transition: all 0.2s ease;\r\n        }\r\n        \r\n        .form-select:hover, .form-select:focus {\r\n            border-color: var(--btn-primary);\r\n            box-shadow: 0 0 0 2px rgba(59,130,246,0.1);\r\n        }\r\n        \r\n        .text-muted {\r\n            color: var(--text-muted) !important;\r\n        }\r\n        \r\n        .col-lg-3.border-end {\r\n            border-right: 2px solid var(--border-light) !important;\r\n        }\r\n        \r\n        .category-grid {\r\n            max-height: 240px;\r\n            overflow-y: auto;\r\n            background: var(--category-bg);\r\n            padding: 0.75rem;\r\n            border-radius: 1rem;\r\n            border: 1px solid var(--category-border);\r\n            transition: all 0.3s ease;\r\n        }\r\n        \r\n        /* Кастомный скроллбар для темной темы */\r\n        .category-grid::-webkit-scrollbar {\r\n            width: 8px;\r\n        }\r\n        \r\n        .category-grid::-webkit-scrollbar-track {\r\n            background: var(--bg-secondary);\r\n            border-radius: 10px;\r\n        }\r\n        \r\n        .category-grid::-webkit-scrollbar-thumb {\r\n            background: var(--text-muted);\r\n            border-radius: 10px;\r\n        }\r\n        \r\n        .category-grid::-webkit-scrollbar-thumb:hover {\r\n            background: var(--btn-primary);\r\n        }\r\n        \r\n        /* Инфо-блоки */\r\n        .info-hint {\r\n            background: var(--info-bg);\r\n            border-left: 3px solid var(--btn-primary);\r\n            padding: 0.75rem;\r\n            border-radius: 0.5rem;\r\n        }\r\n        \r\n        /* Анимация для чекбоксов */\r\n        .form-check {\r\n            transition: transform 0.2s ease;\r\n        }\r\n        \r\n        .form-check:hover {\r\n            transform: translateX(4px);\r\n        }\r\n        \r\n   \r\n        \r\n        /* Иконки с динамическими цветами */\r\n        .text-primary {\r\n            color: var(--icon-primary) !important;\r\n        }\r\n        \r\n        .text-secondary {\r\n            color: var(--icon-secondary) !important;\r\n        }\r\n        \r\n        .text-success {\r\n            color: var(--icon-success) !important;\r\n        }\r\n        \r\n        .text-warning {\r\n            color: var(--icon-warning) !important;\r\n        }\r\n        \r\n        .text-danger {\r\n            color: var(--icon-danger) !important;\r\n        }\r\n        \r\n        .text-info {\r\n            color: var(--icon-info) !important;\r\n        }\r\n        \r\n        /* Иконки в селектах */\r\n        select option {\r\n            background: var(--input-bg);\r\n            color: var(--text-primary);\r\n        }\r\n        \r\n        /* Адаптация ссылок */\r\n        a {\r\n            color: var(--btn-primary);\r\n        }\r\n        \r\n        /* Стили для кастомных элементов */\r\n        .icon-md {\r\n            width: 1.8rem;\r\n            display: inline-block;\r\n            text-align: center;\r\n        }\r\n        \r\n        .section-icon {\r\n            font-size: 1.25rem;\r\n            width: 2rem;\r\n            display: inline-block;\r\n        }\r\n        \r\n        hr {\r\n            border-color: var(--border-color);\r\n        }\r\n        \r\n        /* Плавные переходы для всех элементов */\r\n        * {\r\n            transition: background-color 0.3s ease, border-color 0.3s ease, color 0.2s ease;\r\n        }\r\n        \r\n        /* Адаптация для мобильных */\r\n        @media (max-width: 768px) {\r\n            .card-body {\r\n                padding: 1.2rem;\r\n            }\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n\r\n<form action=\"usercp.php\" method=\"post\">\r\n<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n<div class=\"container-md py-4\">\r\n<div class=\"row g-4\">\r\n<div class=\"col-lg-3\">\r\n    {$usercpnav}\r\n</div>\r\n<div class=\"col-lg-9\">\r\n\r\n    {$errors}				\r\n    <div class=\"card\">\r\n        <div class=\"card-body\">\r\n            \r\n            {$canbeinvisible}\r\n            \r\n            <!-- ========= MESSAGING & NOTIFICATION SECTION ========= -->\r\n            <div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">\r\n                <i class=\"fas fa-comment-dots me-2 text-primary\"></i> {$lang->usercp[\'messaging_notification\']}\r\n            </div>\r\n            <div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mb-2\">\r\n                <div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n                    <i class=\"fas fa-envelope-open-text me-2 text-info\"></i> {$lang->usercp[\'messaging_notification\']}\r\n                </div>\r\n                <div class=\"col\">\r\n                    <!-- Comment PM -->\r\n                    <div class=\"form-check mb-2\">\r\n                        <input type=\"checkbox\" class=\"form-check-input\" name=\"commentpm\" id=\"commentpm\" value=\"1\" {$allowcommentpm} />\r\n                        <label class=\"form-check-label\" for=\"commentpm\">\r\n                            <i class=\"fas fa-paper-plane text-primary\"></i> {$lang->usercp[\'pm10\']}\r\n                        </label>\r\n                    </div>\r\n                    <!-- Allow Notices -->\r\n                    <div class=\"form-check mb-2\">\r\n                        <input type=\"checkbox\" class=\"form-check-input\" name=\"allownotices\" id=\"allownotices\" value=\"1\" {$allownoticescheck} />\r\n                        <label class=\"form-check-label\" for=\"allownotices\">\r\n                            <i class=\"fas fa-bell text-warning\"></i> {$lang->usercp[\'allow_notices\']}\r\n                        </label>\r\n                    </div>\r\n                    <!-- Hide email / allow emails -->\r\n                    <div class=\"form-check mb-2\">\r\n                        <input type=\"checkbox\" class=\"form-check-input\" name=\"hideemail\" id=\"hideemail\" value=\"1\" {$hideemailcheck} />\r\n                        <label class=\"form-check-label\" for=\"hideemail\">\r\n                            <i class=\"fas fa-at text-success\"></i> {$lang->usercp[\'allow_emails\']}\r\n                        </label>\r\n                    </div>\r\n                    {$pms}\r\n                    <!-- Buddy requests auto -->\r\n                    <div class=\"form-check mb-2\">\r\n                        <input type=\"checkbox\" class=\"form-check-input\" name=\"buddyrequestsauto\" id=\"buddyrequestsauto\" value=\"1\" {$buddyrequestsautocheck} />\r\n                        <label class=\"form-check-label\" for=\"buddyrequestsauto\">\r\n                            <i class=\"fas fa-user-plus text-secondary\"></i> {$lang->usercp[\'buddyrequests_auto\']}\r\n                        </label>\r\n                    </div>\r\n                    \r\n                    <!-- Subscription method with icon -->\r\n                    <div class=\"form-group mt-4\">\r\n                        <label class=\"fw-semibold mb-2\"><i class=\"fas fa-bell-ring me-2 text-info\"></i> {$lang->usercp[\'subscription_method\']}</label>\r\n                        <select name=\"subscriptionmethod\" id=\"subscriptionmethod\" class=\"form-select form-select-sm border w-auto pe-5\">\r\n                            <option value=\"0\" {$no_auto_subscribe_selected}><i class=\"fas fa-ban\"></i> {$lang->usercp[\'no_auto_subscribe\']}</option>\r\n                            <option value=\"1\" {$no_subscribe_selected}><i class=\"fas fa-eye-slash\"></i> {$lang->usercp[\'no_subscribe\']}</option>\r\n                            <option value=\"2\" {$instant_email_subscribe_selected}><i class=\"fas fa-envelope\"></i> {$lang->usercp[\'instant_email_subscribe\']}</option>\r\n                            <option value=\"3\" {$instant_pm_subscribe_selected}><i class=\"fas fa-comment-dots\"></i> {$lang->usercp[\'instant_pm_subscribe\']}</option>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            \r\n            <!-- ========= TORRENT CATEGORY NOTIFICATIONS ========= -->\r\n            <div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3 mt-3\">\r\n                <i class=\"fas fa-bell me-1\"></i> Torrent Category Notifications\r\n            </div>\r\n            <div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mb-2\">\r\n                <div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n                    <i class=\"fas fa-bell me-1 fa-fw text-warning\"></i> Category Notifications\r\n                </div>\r\n                <div class=\"col\">\r\n                    <p class=\"text-muted small mb-3\">\r\n                        <i class=\"fas fa-info-circle me-1 text-info\"></i>\r\n                        Select categories you want to be notified about when a new torrent is uploaded.\r\n                    </p>\r\n                    <!-- PM / Email toggles with beautiful icons -->\r\n                    <div class=\"d-flex gap-4 mb-3 flex-wrap\">\r\n                        <div class=\"form-check\">\r\n                            <input type=\"checkbox\" class=\"form-check-input\" name=\"pmnotif\" id=\"pmnotif\" value=\"yes\" {$pmnotif} />\r\n                            <label class=\"form-check-label\" for=\"pmnotif\">\r\n                                <i class=\"fas fa-envelope me-1 text-primary\"></i> <strong>PM Notification</strong>\r\n                            </label>\r\n                        </div>\r\n                        <div class=\"form-check\">\r\n                            <input type=\"checkbox\" class=\"form-check-input\" name=\"emailnotif\" id=\"emailnotif\" value=\"yes\" {$emailnotif} />\r\n                            <label class=\"form-check-label\" for=\"emailnotif\">\r\n                                <i class=\"fas fa-at me-1 text-success\"></i> <strong>Email Notification</strong>\r\n                            </label>\r\n                        </div>\r\n                    </div>\r\n                    <!-- Category subscription list (styled) -->\r\n                    <div class=\"category-grid\">\r\n                        {$category_subscriptions}\r\n                    </div>\r\n                </div>\r\n            </div>	\r\n            \r\n            <!-- ========= DATE & TIME OPTIONS ========= -->\r\n            <div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3 mt-3\">\r\n                <i class=\"fas fa-calendar-alt me-2\"></i> {$lang->usercp[\'date_time_options\']}\r\n            </div>\r\n            <div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mb-2\">\r\n                <div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n                    <i class=\"fas fa-calendar-week me-2 text-secondary\"></i> {$lang->usercp[\'date_time_options\']}\r\n                </div>\r\n                <div class=\"col\">\r\n                    <!-- Date format -->\r\n                    <div class=\"mb-3 pb-2\">\r\n                        <label class=\"fw-semibold mb-2\"><i class=\"fas fa-calendar-day me-2 text-primary\"></i> {$lang->usercp[\'date_format\']}</label>\r\n                        <select name=\"dateformat\" class=\"form-select form-select-sm border pe-5 w-auto\">\r\n                            <option value=\"0\"><i class=\"fas fa-globe\"></i> {$lang->usercp[\'use_default\']}</option>\r\n                            {$date_format_options}\r\n                        </select>\r\n                    </div>\r\n                    <!-- Time format -->\r\n                    <div class=\"mb-3 pb-2\">\r\n                        <label class=\"fw-semibold mb-2\"><i class=\"fas fa-clock me-2 text-success\"></i> {$lang->usercp[\'time_format\']}</label>\r\n                        <select name=\"timeformat\" class=\"form-select form-select-sm border pe-5 w-auto\">\r\n                            <option value=\"0\"><i class=\"fas fa-globe\"></i> {$lang->usercp[\'use_default\']}</option>\r\n                            {$time_format_options}\r\n                        </select>\r\n                    </div>\r\n                    <!-- Time offset -->\r\n                    <div class=\"mb-2\">\r\n                        <label class=\"fw-semibold\"><i class=\"fas fa-globe-americas me-2 text-info\"></i> {$lang->usercp[\'time_offset\']}</label>\r\n                        {$tzselect}\r\n                    </div>\r\n                    <!-- DST correction -->\r\n                    <div class=\"mt-3\">\r\n                        <label class=\"fw-semibold mb-2\"><i class=\"fas fa-sun me-2 text-warning\"></i> {$lang->usercp[\'dst_correction\']}</label>\r\n                        <select name=\"dstcorrection\" class=\"form-select form-select-sm border w-auto pe-5\">\r\n                            <option value=\"2\" {$dst_auto_selected}><i class=\"fas fa-robot\"></i> {$lang->usercp[\'dst_correction_auto\']}</option>\r\n                            <option value=\"1\" {$dst_enabled_selected}><i class=\"fas fa-check-circle text-success\"></i> {$lang->usercp[\'dst_correction_enabled\']}</option>\r\n                            <option value=\"0\" {$dst_disabled_selected}><i class=\"fas fa-ban text-danger\"></i> {$lang->usercp[\'dst_correction_disabled\']}</option>\r\n                        </select>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            \r\n            <!-- ========= FORUM DISPLAY OPTIONS ========= -->\r\n            <div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3 mt-3\">\r\n                <i class=\"fas fa-chalkboard-user me-2\"></i> {$lang->usercp[\'forum_display_options\']}\r\n            </div>\r\n            <div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mb-2\">\r\n                <div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n                    <i class=\"fas fa-desktop me-2 text-info\"></i> {$lang->usercp[\'forum_display_options\']}\r\n                </div>\r\n                <div class=\"col\">\r\n                    <!-- Thread view cutoff (daysprune) -->\r\n                    <div class=\"mb-3 pb-2\">\r\n                        <label class=\"fw-semibold mb-2\"><i class=\"fas fa-hourglass-half me-2 text-secondary\"></i> {$lang->usercp[\'thread_view\']}</label>\r\n                        <select name=\"daysprune\" class=\"form-select form-select-sm border pe-5 w-auto\">\r\n                            <option value=\"\"><i class=\"fas fa-star-of-life\"></i> {$lang->usercp[\'use_default\']}</option>\r\n                            <option value=\"1\" {$daysprunesel[\'1\']}><i class=\"fas fa-calendar-day\"></i> {$lang->usercp[\'thread_view_lastday\']}</option>\r\n                            <option value=\"5\" {$daysprunesel[\'5\']}><i class=\"fas fa-calendar-week\"></i> {$lang->usercp[\'thread_view_5days\']}</option>\r\n                            <option value=\"10\" {$daysprunesel[\'10\']}><i class=\"fas fa-calendar-week\"></i> {$lang->usercp[\'thread_view_10days\']}</option>\r\n                            <option value=\"20\" {$daysprunesel[\'20\']}><i class=\"fas fa-calendar-alt\"></i> {$lang->usercp[\'thread_view_20days\']}</option>\r\n                            <option value=\"50\" {$daysprunesel[\'50\']}><i class=\"fas fa-calendar-alt\"></i> {$lang->usercp[\'thread_view_50days\']}</option>\r\n                            <option value=\"75\" {$daysprunesel[\'75\']}><i class=\"fas fa-calendar-alt\"></i> {$lang->usercp[\'thread_view_75days\']}</option>\r\n                            <option value=\"100\" {$daysprunesel[\'100\']}><i class=\"fas fa-calendar-alt\"></i> {$lang->usercp[\'thread_view_100days\']}</option>\r\n                            <option value=\"365\" {$daysprunesel[\'365\']}><i class=\"fas fa-calendar-check\"></i> {$lang->usercp[\'thread_view_year\']}</option>\r\n                            <option value=\"9999\" {$daysprunesel[\'9999\']}><i class=\"fas fa-infinity\"></i> {$lang->usercp[\'thread_view_all\']}</option>\r\n                        </select>\r\n                    </div>\r\n                    <!-- Topics per page (tpp) dynamic -->\r\n                    {$tppselect}\r\n                </div>\r\n            </div>\r\n            \r\n            <!-- ========= THREAD VIEW OPTIONS ========= -->\r\n            <div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3 mt-3\">\r\n                <i class=\"fas fa-comment-dots me-2\"></i> {$lang->usercp[\'thread_view_options\']}\r\n            </div>\r\n            <div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mb-2\">\r\n                <div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n                    <i class=\"fas fa-eye me-2 text-primary\"></i> {$lang->usercp[\'thread_view_options\']}\r\n                </div>\r\n                <div class=\"col\">\r\n                    <!-- Show signatures & avatars -->\r\n                    <div class=\"mb-3 pb-2\">\r\n                        <div class=\"form-check mb-2\">\r\n                            <input type=\"checkbox\" class=\"form-check-input\" name=\"showsigs\" id=\"showsigs\" value=\"1\" {$showsigscheck} />\r\n                            <label class=\"form-check-label\" for=\"showsigs\">\r\n                                <i class=\"fas fa-signature text-secondary\"></i> {$lang->usercp[\'show_sigs\']}\r\n                            </label>\r\n                        </div>\r\n                        <div class=\"form-check\">\r\n                            <input type=\"checkbox\" class=\"form-check-input\" name=\"showavatars\" id=\"showavatars\" value=\"1\" {$showavatarscheck} />\r\n                            <label class=\"form-check-label\" for=\"showavatars\">\r\n                                <i class=\"fas fa-user-circle text-info\"></i> {$lang->usercp[\'show_avatars\']}\r\n                            </label>\r\n                        </div>\r\n                    </div>\r\n                    <!-- Posts per page (ppp) -->\r\n                    {$pppselect}\r\n                    {$pppselect2}\r\n                </div>\r\n            </div>\r\n            \r\n            <!-- ========= OTHER OPTIONS ========= -->\r\n            <div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3 mt-3\">\r\n                <i class=\"fas fa-ellipsis-h me-2\"></i> {$lang->usercp[\'other_options\']}\r\n            </div>\r\n            <div class=\"row g-3 m-auto pb-0 pt-0 mb-2\">\r\n                <div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n                    <i class=\"fas fa-cog me-2 text-muted\"></i> {$lang->usercp[\'other_options\']}\r\n                </div>\r\n                <div class=\"col\">\r\n                    <div class=\"mb-3\">\r\n                        <div class=\"form-check\">\r\n                            <input type=\"checkbox\" class=\"form-check-input\" name=\"showredirect\" id=\"showredirect\" value=\"1\" {$showredirectcheck} />\r\n                            <label class=\"form-check-label\" for=\"showredirect\">\r\n                                <i class=\"fas fa-share-square text-success\"></i> {$lang->usercp[\'show_redirect\']}\r\n                            </label>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        \r\n        </div> <!-- card-body -->\r\n        \r\n        <div class=\"card-footer text-center\">\r\n            <input type=\"hidden\" name=\"action\" value=\"do_options\" />\r\n            <button type=\"submit\" class=\"btn btn-primary\" name=\"regsubmit\" value=\"{$lang->usercp[\'update_options\']}\">\r\n                <i class=\"fas fa-sliders-h me-2\"></i> {$lang->usercp[\'update_options\']}\r\n            </button>\r\n        </div>\r\n    </div> <!-- card -->\r\n</div> <!-- col -->\r\n</div> <!-- row -->\r\n</div> <!-- container -->\r\n</form>\r\n\r\n<!-- Optional: small script to add icons to dynamically generated selects (if any extra custom) -->\r\n<script>\r\n    // Ваш существующий скрипт переключения темы\r\n    document.addEventListener(\'DOMContentLoaded\', (event) => {\r\n        const htmlElement = document.documentElement;\r\n        const switchElement = document.getElementById(\'darkModeSwitch\');\r\n        const prefersDarkScheme = window.matchMedia(\"(prefers-color-scheme: dark)\").matches;\r\n        const currentTheme = localStorage.getItem(\'bsTheme\') || (prefersDarkScheme ? \'dark\' : \'light\');\r\n\r\n        htmlElement.setAttribute(\'data-bs-theme\', currentTheme);\r\n        if (switchElement) {\r\n            switchElement.checked = currentTheme === \'dark\';\r\n        }\r\n\r\n        switchElement?.addEventListener(\'change\', function () {\r\n            const newTheme = this.checked ? \'dark\' : \'light\';\r\n            htmlElement.setAttribute(\'data-bs-theme\', newTheme);\r\n            localStorage.setItem(\'bsTheme\', newTheme);\r\n        });\r\n\r\n        // Tooltip activation\r\n        const tooltipTriggerList = [].slice.call(document.querySelectorAll(\'[data-bs-toggle=\"tooltip\"]\'));\r\n        tooltipTriggerList.map(function (tooltipTriggerEl) {\r\n            return new bootstrap.Tooltip(tooltipTriggerEl);\r\n        });\r\n    });\r\n</script>\r\n</body>\r\n</html>','2','1837','','1720609281');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1596','usercp_options_invisible','<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->usercp[\'login_cookies_privacy\']}</div>\r\n	<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mb-2\">\r\n		<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n			{$lang->usercp[\'login_cookies_privacy\']}\r\n			\r\n		</div>\r\n		<div class=\"col\">\r\n			\r\n<div class=\"form-check\">\r\n  <input type=\"checkbox\" class=\"form-check-input\" name=\"invisible\" id=\"invisible\" value=\"1\" {$invisiblecheck} />\r\n  <label class=\"form-check-label fw-normal\" for=\"flexSwitchCheckDefault\">{$lang->usercp[\'invisible_mode\']}</label>\r\n	</div>\r\n			\r\n		</div>\r\n		</div>','2','1837','','1720609281');
