INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1603','usercp_options_timezone','<div class=\"mb-3 pb-4 border-bottom\">\r\n\r\n<select name=\"{$name}\" id=\"{$name}\" class=\"form-select form-select-sm border w-100 pe-5\">\r\n{$timezone_option}\r\n</select>\r\n	<span class=\"text-desc small mt-1\">{$lang->usercp[\'time_offset_desc\']}</span>\r\n</div>','2','1837','','1720609281');
