INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('1621','usercp_profile_website','<div class=\"bg-nav p-2 rounded text-16 d-block d-sm-block d-md-block d-lg-none mb-3\">{$lang->website_url}</div>\r\n	<div class=\"row g-3 m-auto border-bottom pb-4 pt-0 mb-2\">\r\n		<div class=\"col-lg-3 d-none d-sm-none d-md-none d-lg-block text-center text-sm-center text-md-center text-lg-end border-end text-16 fw-bold pe-3 me-3\">\r\n			{$lang->website_url}\r\n			\r\n		</div>\r\n		<div class=\"col\">\r\n			\r\n<input type=\"text\" class=\"form-control form-control-sm border\" name=\"website\" maxlength=\"75\" id=\"weburl\" value=\"{$user[\'website\']}\" />\r\n		</div>\r\n		\r\n		</div>','2','1837','','1720609281');
