INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('3000','usercp_substorrents','\r\n<head>\r\n	<title>{$SITENAME} - {$lang->usercp[\'subscriptions\']}</title>\r\n	\r\n</head>\r\n<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">\r\n			\r\n	<form action=\"usercp.php\" method=\"post\" name=\"unsubscribe_torrents\">\r\n    <input type=\"hidden\" name=\"action\" value=\"unsubscribe_torrents\" />\r\n<div class=\"card mb-4\">\r\n	<div class=\"card-header bg-white text-dark border-bottom-0 text-19 fw-bold mt-2 pb-0\">\r\n		\r\n		<span class=\"float-end\"><input name=\"allbox\" type=\"checkbox\" class=\"form-check-input checkall\" value=\"1\" /></span>\r\n		\r\n		</div>\r\n	<div class=\"card-body\">\r\n		\r\n		{$substorrents}\r\n	</div>\r\n	<div class=\"card-footer\">\r\n						{$remove_options}\r\n	</div>\r\n		</div>\r\n				\r\n				</form>\r\n				{$multipage}\r\n				\r\n				\r\n	</div>\r\n	</div>\r\n</div>','2','1837','','1720609281');
