INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('565','similartorrents_table','<div class=\"container mt-4\">\r\n    <div class=\"card border-0 shadow-sm\">\r\n        <div class=\"card-header bg-light\">\r\n            <h5 class=\"mb-0\"><i class=\"bi bi-collection me-2\"></i>{$lang->details[\'smililartorrents\']}</h5>\r\n        </div>\r\n        <div class=\"card-body\">\r\n            <div class=\"row g-3\">\r\n                {$FoundSMTQ}\r\n            </div>\r\n        </div>\r\n    </div>\r\n</div>\r\n<style>\r\n/* Similar Torrents Cards */\r\n.similar-torrent-card {\r\n    border-radius: 10px;\r\n    overflow: hidden;\r\n    transition: transform 0.2s ease, box-shadow 0.2s ease;\r\n}\r\n\r\n.similar-torrent-card:hover {\r\n    transform: translateY(-4px);\r\n    box-shadow: 0 8px 20px rgba(0,0,0,0.15) !important;\r\n}\r\n\r\n.similar-overlay {\r\n    background: rgba(0,0,0,0.3);\r\n    opacity: 0;\r\n    transition: opacity 0.3s ease;\r\n}\r\n\r\n.similar-torrent-card:hover .similar-overlay {\r\n    opacity: 1;\r\n}\r\n\r\n.similar-torrent-card:hover img {\r\n    transform: scale(1.05);\r\n}\r\n</style>\r\n<br>','2','1837','','1728810794');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('566','peers_table','<table width=\"100%\" border=\"0\" class=\"tborder\" cellspacing=\"0\" cellpadding=\"3\">\r\n					<tr>\r\n						<td colspan=\"11\" class=\"thead\">{$p}</td>\r\n					</tr>\r\n					<tr>\r\n						<td class=\"trow2\">{$lang->details[\'userip\']}</td>\r\n						<td class=\"trow2\" align=\"center\">{$lang->details[\'conn\']}</td>\r\n						<td class=\"trow2\" align=\"center\">{$lang->details[\'up\']}</td>\r\n						<td class=\"trow2\" align=\"center\">{$lang->details[\'urate\']}</td>\r\n						<td class=\"trow2\" align=\"center\">{$lang->details[\'down\']}</td>\r\n						<td class=\"trow2\" align=\"center\">{$lang->details[\'drate\']}</td>\r\n						<td class=\"trow2\" align=\"center\">{$lang->details[\'ratio\']}</td>\r\n						<td class=\"trow2\" align=\"center\">{$lang->details[\'done\']}</td>\r\n						<td class=\"trow2\" align=\"center\">{$lang->details[\'since\']}</td>\r\n						<td class=\"trow2\" align=\"center\">{$lang->details[\'idle\']}</td>\r\n						<td class=\"trow2\" align=\"center\">{$lang->details[\'client\']}</td>\r\n				</tr>','2','1837','','1728810794');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('567','imdb_table','<div class=\"container mt-3\">\r\n  <div class=\"card\">\r\n    <div class=\"card-header rounded-bottom text-19 fw-bold\">\r\n	<span style=\"float: right;\">\r\n		<div id=\"imdbupdatebutton\" name=\"imdbupdatebutton\">\r\n		<a href=\"#\" onclick=\"TS_IMDB({$id}); return false;\"><b><u><i>{$refresh}</i></u></b></a></div></span>{$lang->details[\'t_link\']}\r\n		\r\n		\r\n     </div>\r\n	 \r\n	 \r\n    <div class=\"card-body\"><div id=\"imdbdetails\" name=\"imdbdetails\">{$Torrent[\'t_link\']}</div></div> \r\n   \r\n  </div>\r\n</div>\r\n	\r\n	\r\n	\r\n	\r\n	\r\n	\r\n	<br />','2','1837','','1728810794');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('572','details_table','<div class=\"container mt-3\">\r\n  <h2>{$isfree}{$issilver}{$isdoubleupload} {$nname}</h2>\r\n  <div class=\"card\">\r\n  \r\n  \r\n	<div class=\"card-header\">\r\n		\r\n		\r\n	<button type=\"button\" class=\"btn btn-secondary\">\r\n		\r\n		<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" fill=\"currentColor\" class=\"bi bi-download\" viewBox=\"0 0 16 16\">\r\n           <path d=\"M.5 9.9a.5.5 0 0 1 .5.5v2.5a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-2.5a.5.5 0 0 1 1 0v2.5a2 2 0 0 1-2 2H2a2 2 0 0 1-2-2v-2.5a.5.5 0 0 1 .5-.5\"></path>\r\n           <path d=\"M7.646 11.854a.5.5 0 0 0 .708 0l3-3a.5.5 0 0 0-.708-.708L8.5 10.293V1.5a.5.5 0 0 0-1 0v8.793L5.354 8.146a.5.5 0 1 0-.708.708z\"></path>\r\n        </svg>\r\n\r\n           <a href=\"{$dowwn}\" alt=\"{$lang->details[\'dltorrent\']}\" title=\"{$lang->details[\'dltorrent\']}\">{$nname}</a>\r\n		   \r\n    </button>\r\n\r\n    </div>\r\n		\r\n		\r\n		\r\n\r\n	<div class=\"card-body\">\r\n\r\n	\r\n		\r\n	<div class=\"container mt-3\">	\r\n		\r\n   <!-- a link that triggers modal -->\r\n\r\n<a href=\"#myModal\" type=\"\" class=\"\" data-bs-toggle=\"modal\" data-bs-target=\"#myModal\">\r\n<img src=\"{$imaages}\" class=\"rounded\" border=\"0\" width=\"400\"></a>\r\n\r\n<div class=\"modal fade\" id=\"myModal\" tabindex=\"-1\" aria-labelledby=\"exampleModalLabel\" aria-hidden=\"true\">\r\n  <div class=\"modal-dialog modal-lg modal-dialog-scrollable\">\r\n    <div class=\"modal-content\">\r\n      <div class=\"modal-header\">\r\n        <h5 class=\"modal-title\" id=\"exampleModalLabel\">{$nname}</h5>\r\n        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\r\n      </div>\r\n      <div class=\"modal-body\">\r\n       \r\n        <img src=\"{$imaages}\" alt=\"Image Title\" class=\"img-fluid\">\r\n      </div>\r\n      <div class=\"modal-footer\">\r\n        <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Close</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n</div>\r\n		\r\n		\r\n	\r\n	\r\n	<ul class=\"list-group list-group-flush\">\r\n    <li class=\"list-group-item\">\r\n	{$lang->details[\'added\']}\r\n	{$adsss}</td>\r\n     </li>\r\n	 \r\n	 \r\n    <li class=\"list-group-item\">{$lang->details[\'type\']}\r\n		{$dfsdsfdssdfsdass}</li>\r\n    <li class=\"list-group-item\">{$lang->details[\'snatched\']}\r\n		<a href=\"{$BASEURL}/viewsnatches.php?id={$id}\">{$zaw}</a> {$lang->details[\'snatched2\']}\r\n	</li>\r\n    <li class=\"list-group-item\">{$lang->details[\'size\']}\r\n		{$sdfsadsa} {$azaza}\r\n	</li>\r\n	\r\n	\r\n	 <li class=\"list-group-item\">Tags\r\n		{$keywords}\r\n		</li>\r\n		\r\n		\r\n		\r\n		\r\n		\r\n	  <li class=\"list-group-item\">{$lang->details[\'comments\']}\r\n		  {$xza} {$lang->details[\'comments\']}</li>\r\n	   \r\n	   \r\n	   <li class=\"list-group-item\">{$lang->details[\'hits\']}</td>\r\n		   {$tys}</li>\r\n	   \r\n	   <li class=\"list-group-item\">{$lang->details[\'uppedby\']}\r\n		   {$username}</li>\r\n	   \r\n	   \r\n	   {$azazaaza}\r\n	  \r\n	   \r\n	\r\n  </ul>\r\n		\r\n		\r\n	\r\n	</br>\r\n	\r\n\r\n	\r\n	{$xzcxcxzz}\r\n	\r\n	\r\n	\r\n</div> \r\n    <div class=\"card-footer\">\r\n	\r\n	<div class=\"accordion accordion-flush\" id=\"accordionFlushExample\">\r\n  <div class=\"accordion-item\">\r\n    <h2 class=\"accordion-header\" id=\"flush-headingOne\">\r\n      <button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#flush-collapseOne\" aria-expanded=\"false\" aria-controls=\"flush-collapseOne\">\r\n       {$lang->details[\'peersb\']}</td>\r\n	   \r\n	   {$dffsdsfdsf}\r\n      </button>\r\n    </h2>\r\n    <div id=\"flush-collapseOne\" class=\"accordion-collapse collapse\" aria-labelledby=\"flush-headingOne\" data-bs-parent=\"#accordionFlushExample\">\r\n      <div class=\"accordion-body\">\r\n	  \r\n	  {$peerstable}\r\n	  \r\n	  </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n	\r\n	</div>\r\n  </div>\r\n</div>\r\n\r\n\r\n	\r\n	\r\n	<br />\r\n	{$ShowTLINK}\r\n	\r\n	\r\n	\r\n	<div class=\"container mt-3\">\r\n  \r\n  <div class=\"card\">\r\n    <div class=\"card-header rounded-bottom text-19 fw-bold\">{$sdfsdfsdf}</div>\r\n    <div class=\"card-body\">{$fddsfsffsdfs34}</div> \r\n    \r\n  </div>\r\n</div>\r\n	\r\n	\r\n	\r\n	<br />\r\n	{$SimilarTorrents}\r\n	{$showcommenttable}','2','1837','','1728810794');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('589','torrents_completed','<table class=\"table table-hover\">\r\n    <thead>\r\n      <tr>\r\n        <th>{$lang->global[\'type\']}</th>\r\n        <th>{$lang->global[\'name\']}</th>\r\n		<th>Seeders</th>\r\n		<th>Leechers</th>\r\n		\r\n		\r\n		\r\n		<th>{$lang->global[\'uploaded\']}</th>\r\n		<th>{$lang->global[\'downloaded\']}</th>\r\n		<th>{$lang->global[\'ratio\']}</th>\r\n		\r\n		\r\n		<th>{$lang->global[\'whencompleted\']}</th>\r\n		<th>{$lang->global[\'lastaction\']}</th>\r\n		\r\n      </tr>\r\n    </thead>','2','1821','','1728810794');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('590','maketable_torrents','<table class=\"table table-hover\">\r\n    <thead>\r\n      <tr>\r\n        <th>{$lang->global[\'type\']}</th>\r\n        <th>{$lang->global[\'name\']}</th>\r\n		<th>{$lang->global[\'size\']}</th>\r\n		\r\n		<th>Seeders</th>\r\n		<th>Leechers</th>\r\n		\r\n		<th>{$lang->global[\'uploaded\']}</th>\r\n		<th>{$lang->global[\'downloaded\']}</th>\r\n		<th>{$lang->global[\'ratio\']}</th>\r\n      </tr>\r\n    </thead>','2','1837','','1728810794');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('604','forumdisplay_inlinemoderation_selectall','<tr id=\"selectAllrow\" class=\"hiddenrow\">\r\n	<td colspan=\"8\" class=\"selectall\">{$page_selected} <a href=\"javascript:void(0)\" onclick=\'inlineModeration.selectAll(); return false;\'>{$select_all}</a></td>\r\n</tr>\r\n<tr id=\"allSelectedrow\" class=\"hiddenrow\">\r\n	<td colspan=\"8\" class=\"selectall\">{$all_selected} <a href=\"javascript:void(0)\" onclick=\'inlineModeration.clearChecked(); return false;\'>{$lang->forumdisplay[\'clear_selection\']}</a></td>\r\n</tr>','2','1821','','1728810794');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('605','misc_whoposted_page','<html>\r\n<head>\r\n<title>{$thread[\'subject\']} - {$lang->misc[\'who_posted\']}</title>\r\n{$headerinclude}\r\n</head>\r\n<body>\r\n{$header}\r\n<br />\r\n<table border=\"0\" cellspacing=\"{$theme[\'borderwidth\']}\" cellpadding=\"{$theme[\'tablespace\']}\" class=\"tborder\">\r\n<tr>\r\n<td colspan=\"2\" class=\"thead\"><strong>{$lang->misc[\'total_posts\']} {$numposts}</strong></td>\r\n</tr>\r\n<tr>\r\n<td class=\"tcat\"><span class=\"smalltext\"><strong><a href=\"{$BASEURL}/misc.php?action=whoposted&tid={$thread[\'tid\']}&sort=username\">{$lang->misc[\'user\']}</a></strong></span></td>\r\n<td class=\"tcat\"><span class=\"smalltext\"><strong><a href=\"{$BASEURL}/misc.php?action=whoposted&tid={$thread[\'tid\']}\">{$lang->misc[\'num_posts\']}</a></strong></span></td>\r\n</tr>\r\n{$whoposted}\r\n</table>\r\n{$footer}\r\n</body>\r\n</html>','2','1813','','1728810794');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('607','error_nopermission_loggedin','{$lang->global[\'error_nopermission_user_1\']}\r\n<ol>\r\n	<li>{$lang->global[\'error_nopermission_user_2\']}</li>\r\n	<li>{$lang->global[\'error_nopermission_user_3\']}</li>\r\n	<li>{$lang->global[\'error_nopermission_user_4\']} (<a href=\"member.php?action=resendactivation\">{$lang->global[\'error_nopermission_user_resendactivation\']}</a>)</li>\r\n	<li>{$lang->global[\'error_nopermission_user_5\']}</li>\r\n</ol>\r\n<br />\r\n{$error_nopermission_user_username}','2','1837','','1728810794');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('577','global_bannedwarning','<html>\r\n<head>\r\n    <title>{$title}</title>\r\n    \r\n    <link href=\"{$BASEURL}/include/templates/default/style/bootstrap-icons.css\" rel=\"stylesheet\">\r\n    <style>\r\n       \r\n        .ban-container {\r\n            max-width: 600px;\r\n            margin: 0 auto;\r\n            width: 100%;\r\n            animation: slideUp 0.6s cubic-bezier(0.68, -0.55, 0.265, 1.55);\r\n        }\r\n\r\n        /* Премиум карточка */\r\n        .ban-card {\r\n            background: rgba(255, 255, 255, 0.95);\r\n            backdrop-filter: blur(20px);\r\n            border-radius: 40px;\r\n            overflow: hidden;\r\n            box-shadow: \r\n                0 30px 60px rgba(0, 0, 0, 0.3),\r\n                0 0 0 1px rgba(220, 53, 69, 0.2) inset,\r\n                0 0 20px rgba(220, 53, 69, 0.3);\r\n            position: relative;\r\n            transform-style: preserve-3d;\r\n            transition: all 0.3s ease;\r\n        }\r\n\r\n        .ban-card:hover {\r\n            transform: translateY(-5px) rotateX(2deg);\r\n            box-shadow: \r\n                0 40px 80px rgba(220, 53, 69, 0.4),\r\n                0 0 0 2px rgba(220, 53, 69, 0.3) inset;\r\n        }\r\n\r\n        /* Анимированный фон */\r\n        .ban-bg-pattern {\r\n            position: absolute;\r\n            top: 0;\r\n            left: 0;\r\n            right: 0;\r\n            bottom: 0;\r\n            background-image: \r\n                radial-gradient(circle at 20px 20px, rgba(220, 53, 69, 0.1) 2px, transparent 2px),\r\n                linear-gradient(45deg, transparent 48%, rgba(220, 53, 69, 0.05) 50%, transparent 52%);\r\n            background-size: 40px 40px, 200% 200%;\r\n            opacity: 0.3;\r\n            pointer-events: none;\r\n            animation: patternMove 20s linear infinite;\r\n        }\r\n\r\n        /* Неоновая линия сверху */\r\n        .ban-glow-line {\r\n            position: absolute;\r\n            top: 0;\r\n            left: 0;\r\n            right: 0;\r\n            height: 4px;\r\n            background: linear-gradient(90deg, \r\n                transparent, \r\n                #ff6b6b, \r\n                #dc3545, \r\n                #c82333, \r\n                #ff6b6b, \r\n                transparent\r\n            );\r\n            background-size: 200% 100%;\r\n            animation: gradientShift 3s ease infinite;\r\n            filter: blur(1px);\r\n        }\r\n\r\n        /* Хедер с иконкой */\r\n        .ban-header {\r\n            background: linear-gradient(135deg, #dc3545, #c82333, #bd2130);\r\n            padding: 30px 30px 40px;\r\n            position: relative;\r\n            overflow: hidden;\r\n            clip-path: polygon(0 0, 100% 0, 100% 85%, 0 100%);\r\n        }\r\n\r\n        .ban-header::before {\r\n            content: \'\';\r\n            position: absolute;\r\n            top: -50%;\r\n            left: -50%;\r\n            width: 200%;\r\n            height: 200%;\r\n            background: radial-gradient(circle, rgba(255,255,255,0.2) 0%, transparent 70%);\r\n            animation: rotate 20s linear infinite;\r\n        }\r\n\r\n        .ban-header::after {\r\n            content: \'\';\r\n            position: absolute;\r\n            bottom: 0;\r\n            left: 0;\r\n            right: 0;\r\n            height: 40px;\r\n            background: linear-gradient(to bottom, transparent, rgba(0,0,0,0.2));\r\n        }\r\n\r\n        .ban-icon-wrapper {\r\n            display: flex;\r\n            align-items: center;\r\n            gap: 20px;\r\n            position: relative;\r\n            z-index: 2;\r\n        }\r\n\r\n        .ban-icon-circle {\r\n            width: 80px;\r\n            height: 80px;\r\n            background: rgba(255, 255, 255, 0.2);\r\n            backdrop-filter: blur(10px);\r\n            border-radius: 30px;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            position: relative;\r\n            animation: float 3s ease-in-out infinite;\r\n            box-shadow: 0 10px 30px rgba(0,0,0,0.3);\r\n        }\r\n\r\n        .ban-icon-circle::before {\r\n            content: \'\';\r\n            position: absolute;\r\n            inset: -2px;\r\n            border-radius: 32px;\r\n            background: linear-gradient(45deg, #fff, transparent);\r\n            opacity: 0.5;\r\n        }\r\n\r\n        .ban-icon {\r\n            font-size: 3rem;\r\n            color: white;\r\n            filter: drop-shadow(0 0 10px rgba(255,255,255,0.5));\r\n            animation: pulse 2s infinite;\r\n        }\r\n\r\n        .ban-header-text {\r\n            flex: 1;\r\n        }\r\n\r\n        .ban-header-text h1 {\r\n            font-size: 2.5rem;\r\n            font-weight: 800;\r\n            margin: 0;\r\n            color: white;\r\n            text-shadow: \r\n                0 2px 10px rgba(0,0,0,0.3),\r\n                0 0 20px rgba(255,255,255,0.3);\r\n            letter-spacing: -1px;\r\n        }\r\n\r\n        .ban-header-text p {\r\n            font-size: 1rem;\r\n            margin: 5px 0 0;\r\n            opacity: 0.9;\r\n            color: white;\r\n            text-shadow: 0 2px 5px rgba(0,0,0,0.2);\r\n        }\r\n\r\n        /* Тело карточки */\r\n        .ban-body {\r\n            padding: 30px;\r\n            position: relative;\r\n        }\r\n\r\n        /* Метка бана */\r\n        .ban-badge {\r\n            display: inline-block;\r\n            padding: 8px 20px;\r\n            background: linear-gradient(135deg, #ff6b6b, #dc3545);\r\n            color: white;\r\n            border-radius: 30px;\r\n            font-weight: 600;\r\n            font-size: 0.9rem;\r\n            text-transform: uppercase;\r\n            letter-spacing: 2px;\r\n            margin-bottom: 20px;\r\n            box-shadow: 0 5px 15px rgba(220, 53, 69, 0.3);\r\n            animation: badgePulse 2s infinite;\r\n        }\r\n\r\n        /* Сообщение о бане */\r\n        .ban-message {\r\n            background: linear-gradient(135deg, rgba(220, 53, 69, 0.05), rgba(255, 107, 107, 0.1));\r\n            border-left: 5px solid #dc3545;\r\n            border-radius: 20px;\r\n            padding: 25px;\r\n            margin-bottom: 25px;\r\n            position: relative;\r\n            overflow: hidden;\r\n            transition: all 0.3s ease;\r\n        }\r\n\r\n        .ban-message:hover {\r\n            transform: translateX(5px);\r\n            background: linear-gradient(135deg, rgba(220, 53, 69, 0.08), rgba(255, 107, 107, 0.15));\r\n        }\r\n\r\n        .ban-message::before {\r\n            content: \'\';\r\n            position: absolute;\r\n            top: 0;\r\n            left: 0;\r\n            right: 0;\r\n            height: 2px;\r\n            background: linear-gradient(90deg, transparent, #dc3545, transparent);\r\n            animation: scan 3s infinite;\r\n        }\r\n\r\n        .ban-message-content {\r\n            display: flex;\r\n            align-items: flex-start;\r\n            gap: 20px;\r\n        }\r\n\r\n        .ban-message-icon {\r\n            width: 50px;\r\n            height: 50px;\r\n            background: rgba(220, 53, 69, 0.1);\r\n            border-radius: 15px;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            font-size: 1.8rem;\r\n            color: #dc3545;\r\n            animation: iconPulse 2s infinite;\r\n        }\r\n\r\n        .ban-message-text {\r\n            flex: 1;\r\n        }\r\n\r\n        .ban-message-text strong {\r\n            font-size: 1.2rem;\r\n            color: #dc3545;\r\n            display: block;\r\n            margin-bottom: 10px;\r\n        }\r\n\r\n        /* Детали бана */\r\n        .ban-details {\r\n            display: grid;\r\n            grid-template-columns: 1fr 1fr;\r\n            gap: 15px;\r\n            margin-bottom: 30px;\r\n        }\r\n\r\n        .ban-detail-item {\r\n            background: rgba(255, 255, 255, 0.8);\r\n            backdrop-filter: blur(10px);\r\n            border: 1px solid rgba(0, 0, 0, 0.05);\r\n            border-radius: 20px;\r\n            padding: 20px;\r\n            text-align: center;\r\n            transition: all 0.3s ease;\r\n            position: relative;\r\n            overflow: hidden;\r\n            box-shadow: 0 5px 15px rgba(0,0,0,0.05);\r\n        }\r\n\r\n        .ban-detail-item::before {\r\n            content: \'\';\r\n            position: absolute;\r\n            top: 0;\r\n            left: 0;\r\n            right: 0;\r\n            height: 3px;\r\n            background: linear-gradient(90deg, #dc3545, #ff6b6b);\r\n            transform: translateX(-100%);\r\n            transition: transform 0.3s ease;\r\n        }\r\n\r\n        .ban-detail-item:hover::before {\r\n            transform: translateX(0);\r\n        }\r\n\r\n        .ban-detail-item:hover {\r\n            transform: translateY(-3px);\r\n            box-shadow: 0 10px 25px rgba(220, 53, 69, 0.15);\r\n        }\r\n\r\n        .ban-detail-item i {\r\n            font-size: 2rem;\r\n            color: #dc3545;\r\n            margin-bottom: 10px;\r\n            animation: float 3s ease-in-out infinite;\r\n        }\r\n\r\n        .ban-detail-item h6 {\r\n            font-size: 0.9rem;\r\n            color: #6c757d;\r\n            margin: 0 0 5px;\r\n            text-transform: uppercase;\r\n            letter-spacing: 1px;\r\n        }\r\n\r\n        .ban-detail-item .ban-value {\r\n            font-size: 1.3rem;\r\n            font-weight: 700;\r\n            color: #dc3545;\r\n            word-break: break-word;\r\n        }\r\n\r\n        /* Кнопки действий */\r\n        .ban-actions {\r\n            display: flex;\r\n            gap: 15px;\r\n            margin-top: 30px;\r\n        }\r\n\r\n        .ban-btn {\r\n            flex: 1;\r\n            padding: 15px 25px;\r\n            border: none;\r\n            border-radius: 15px;\r\n            font-weight: 600;\r\n            font-size: 1rem;\r\n            cursor: pointer;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            gap: 10px;\r\n            transition: all 0.3s ease;\r\n            text-decoration: none;\r\n            position: relative;\r\n            overflow: hidden;\r\n        }\r\n\r\n        .ban-btn::before {\r\n            content: \'\';\r\n            position: absolute;\r\n            top: 50%;\r\n            left: 50%;\r\n            width: 0;\r\n            height: 0;\r\n            border-radius: 50%;\r\n            background: rgba(255, 255, 255, 0.2);\r\n            transform: translate(-50%, -50%);\r\n            transition: width 0.6s, height 0.6s;\r\n        }\r\n\r\n        .ban-btn:hover::before {\r\n            width: 300px;\r\n            height: 300px;\r\n        }\r\n\r\n        .ban-btn-primary {\r\n            background: linear-gradient(135deg, #dc3545, #c82333);\r\n            color: white;\r\n            box-shadow: 0 10px 20px rgba(220, 53, 69, 0.3);\r\n        }\r\n\r\n        .ban-btn-primary:hover {\r\n            transform: translateY(-3px);\r\n            box-shadow: 0 15px 30px rgba(220, 53, 69, 0.4);\r\n        }\r\n\r\n        .ban-btn-secondary {\r\n            background: rgba(255, 255, 255, 0.9);\r\n            backdrop-filter: blur(10px);\r\n            border: 1px solid rgba(220, 53, 69, 0.2);\r\n            color: #dc3545;\r\n        }\r\n\r\n        .ban-btn-secondary:hover {\r\n            background: white;\r\n            border-color: #dc3545;\r\n            transform: translateY(-3px);\r\n            box-shadow: 0 10px 25px rgba(0,0,0,0.1);\r\n        }\r\n\r\n        /* Footer */\r\n        .ban-footer {\r\n            background: rgba(0, 0, 0, 0.02);\r\n            padding: 20px 30px;\r\n            text-align: center;\r\n            border-top: 1px solid rgba(0,0,0,0.05);\r\n        }\r\n\r\n        .ban-footer small {\r\n            color: #6c757d;\r\n            display: flex;\r\n            align-items: center;\r\n            justify-content: center;\r\n            gap: 8px;\r\n        }\r\n\r\n        .ban-footer a {\r\n            color: #dc3545;\r\n            text-decoration: none;\r\n            font-weight: 500;\r\n            transition: all 0.3s ease;\r\n        }\r\n\r\n        .ban-footer a:hover {\r\n            color: #c82333;\r\n            text-decoration: underline;\r\n        }\r\n\r\n        /* Анимации */\r\n        @keyframes slideUp {\r\n            from {\r\n                opacity: 0;\r\n                transform: translateY(50px) scale(0.8);\r\n            }\r\n            to {\r\n                opacity: 1;\r\n                transform: translateY(0) scale(1);\r\n            }\r\n        }\r\n\r\n        @keyframes float {\r\n            0%, 100% { transform: translateY(0); }\r\n            50% { transform: translateY(-10px); }\r\n        }\r\n\r\n        @keyframes pulse {\r\n            0%, 100% { transform: scale(1); }\r\n            50% { transform: scale(1.1); }\r\n        }\r\n\r\n        @keyframes iconPulse {\r\n            0%, 100% { \r\n                transform: scale(1);\r\n                box-shadow: 0 0 0 0 rgba(220, 53, 69, 0.3);\r\n            }\r\n            50% { \r\n                transform: scale(1.05);\r\n                box-shadow: 0 0 20px rgba(220, 53, 69, 0.5);\r\n            }\r\n        }\r\n\r\n        @keyframes gradientShift {\r\n            0%, 100% { background-position: 0% 50%; }\r\n            50% { background-position: 100% 50%; }\r\n        }\r\n\r\n        @keyframes rotate {\r\n            from { transform: rotate(0deg); }\r\n            to { transform: rotate(360deg); }\r\n        }\r\n\r\n        @keyframes patternMove {\r\n            from { background-position: 0 0; }\r\n            to { background-position: 100% 100%; }\r\n        }\r\n\r\n        @keyframes scan {\r\n            0% { transform: translateX(-100%); }\r\n            100% { transform: translateX(100%); }\r\n        }\r\n\r\n        @keyframes badgePulse {\r\n            0%, 100% { box-shadow: 0 5px 15px rgba(220, 53, 69, 0.3); }\r\n            50% { box-shadow: 0 5px 25px rgba(220, 53, 69, 0.6); }\r\n        }\r\n\r\n        /* Темная тема для body */\r\n        body {\r\n            background: var(--dark-gradient);\r\n        }\r\n\r\n        /* Адаптивность */\r\n        @media (max-width: 576px) {\r\n            .ban-header {\r\n                padding: 20px 20px 30px;\r\n            }\r\n\r\n            .ban-icon-wrapper {\r\n                flex-direction: column;\r\n                text-align: center;\r\n            }\r\n\r\n            .ban-header-text h1 {\r\n                font-size: 2rem;\r\n            }\r\n\r\n            .ban-body {\r\n                padding: 20px;\r\n            }\r\n\r\n            .ban-details {\r\n                grid-template-columns: 1fr;\r\n            }\r\n\r\n            .ban-actions {\r\n                flex-direction: column;\r\n            }\r\n\r\n            .ban-message-content {\r\n                flex-direction: column;\r\n                text-align: center;\r\n            }\r\n\r\n            .ban-message-icon {\r\n                margin: 0 auto;\r\n            }\r\n        }\r\n\r\n        /* Поддержка Bootstrap иконок */\r\n        .bi {\r\n            line-height: 1;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n\r\n    <div class=\"ban-container\">\r\n        <div class=\"ban-card\">\r\n            <!-- Анимированный фон -->\r\n            <div class=\"ban-bg-pattern\"></div>\r\n            \r\n            <!-- Неоновая линия -->\r\n            <div class=\"ban-glow-line\"></div>\r\n            \r\n            <!-- Хедер -->\r\n            <div class=\"ban-header\">\r\n                <div class=\"ban-icon-wrapper\">\r\n                    <div class=\"ban-icon-circle\">\r\n                        <i class=\"bi bi-shield-lock-fill ban-icon\"></i>\r\n                    </div>\r\n                    <div class=\"ban-header-text\">\r\n                        <h1>{$lang->global[\'banned_warning\']}</h1>\r\n                        <p>{$lang->global[\'banned_warning\']} - Access Restricted</p>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            \r\n            <!-- Тело карточки -->\r\n            <div class=\"ban-body\">\r\n                <!-- Бейдж -->\r\n                <div class=\"ban-badge\">\r\n                    <i class=\"bi bi-exclamation-triangle-fill me-2\"></i>\r\n                    ACCOUNT SUSPENDED\r\n                </div>\r\n                \r\n                <!-- Сообщение о бане -->\r\n                <div class=\"ban-message\">\r\n                    <div class=\"ban-message-content\">\r\n                        <div class=\"ban-message-icon\">\r\n                            <i class=\"bi bi-shield-exclamation\"></i>\r\n                        </div>\r\n                        <div class=\"ban-message-text\">\r\n                            <strong>{$lang->global[\'banned_warning\']}</strong>\r\n                            <p class=\"mb-0 text-muted\">{$lang->global[\'banned_warning2\']}:</p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n                \r\n                <!-- Детали бана -->\r\n                <div class=\"ban-details\">\r\n                    <div class=\"ban-detail-item\">\r\n                        <i class=\"bi bi-chat-quote-fill\"></i>\r\n                        <h6>{$lang->global[\'banned_warning2\']}</h6>\r\n                        <div class=\"ban-value\">{$reason}</div>\r\n                    </div>\r\n                    \r\n                    <div class=\"ban-detail-item\">\r\n                        <i class=\"bi bi-calendar-event-fill\"></i>\r\n                        <h6>{$lang->global[\'banned_warning3\']}</h6>\r\n                        <div class=\"ban-value\">{$banlift}</div>\r\n                    </div>\r\n                </div>\r\n                \r\n                <!-- Дополнительная информация -->\r\n                <div class=\"alert alert-warning d-flex align-items-center\" role=\"alert\" style=\"border-radius: 15px; background: rgba(255, 193, 7, 0.1); border: 1px solid rgba(255, 193, 7, 0.2);\">\r\n                    <i class=\"bi bi-info-circle-fill me-3\" style=\"color: #ffc107; font-size: 1.5rem;\"></i>\r\n                    <div>\r\n                        <strong>Important:</strong> If you believe this is a mistake, please contact the administrator for assistance.\r\n                    </div>\r\n                </div>\r\n                \r\n                <!-- Кнопки действий -->\r\n                <div class=\"ban-actions\">\r\n                    <button onclick=\"history.back()\" class=\"ban-btn ban-btn-secondary\">\r\n                        <i class=\"bi bi-arrow-left\"></i>\r\n                        Go Back\r\n                    </button>\r\n                    <a href=\"{$BASEURL}/\" class=\"ban-btn ban-btn-primary\">\r\n                        <i class=\"bi bi-house-door\"></i>\r\n                        Home Page\r\n                    </a>\r\n                </div>\r\n            </div>\r\n            \r\n            <!-- Footer -->\r\n            <div class=\"ban-footer\">\r\n                <small>\r\n                    <i class=\"bi bi-envelope me-1\"></i>\r\n                    Need help? Contact \r\n                    <a href=\"{$BASEURL}/contact.php\">Support Team</a>\r\n                </small>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n</body>\r\n</html>','2','1837','','1728810794');
