INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('716','search_posts_inlinemoderation_selectall','<tr id=\"selectAllrow\" class=\"hiddenrow\">\r\n	<td colspan=\"9\" class=\"selectall\">{$lang->search[\'page_selected\']} <a href=\"javascript:void(0)\" onclick=\'inlineModeration.selectAll(); return false;\'>{$lang->search[\'select_all\']}</a></td>\r\n</tr>\r\n<tr id=\"allSelectedrow\" class=\"hiddenrow\">\r\n	<td colspan=\"9\" class=\"selectall\">{$lang->search[\'all_selected\']} <a href=\"javascript:void(0)\" onclick=\'inlineModeration.clearChecked(); return false;\'>{$lang->search[\'clear_selection\']}</a></td>\r\n</tr>','2','1809','','1728810794');
