INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('5600','usercp_bookmarks','<html>\r\n<head>\r\n	<title>{$SITENAME} - {Bookmarked Torrents}</title>\r\n</head>\r\n<body>\r\n	{$header}\r\n	<div class=\"container-md\">\r\n<div class=\"row\">\r\n<div class=\"col-lg-3\">\r\n\r\n{$usercpnav}\r\n				\r\n</div>\r\n<div class=\"col\">\r\n			\r\n	<form action=\"usercp.php\" method=\"post\" name=\"input\">\r\n					<input type=\"hidden\" name=\"my_post_key\" value=\"{$mybb->post_code}\" />\r\n					<input type=\"hidden\" name=\"action\" value=\"do_removebookmarks\" />\r\n<div class=\"card mb-4\">\r\n	<div class=\"card-header bg-white text-dark border-bottom-0 text-19 fw-bold mt-2 pb-0\">\r\n		\r\n		Bookmarked Torrents ({$threadcount}) <span class=\"float-end\"><input name=\"allbox\" type=\"checkbox\" class=\"form-check-input checkall\" value=\"1\" /></span>\r\n		\r\n		</div>\r\n	<div class=\"card-body\">\r\n		\r\n		{$substorrents}\r\n	</div>\r\n	<div class=\"card-footer\">\r\n						{$remove_options}\r\n	</div>\r\n		</div>\r\n				\r\n				</form>\r\n				{$multipage}\r\n				\r\n				\r\n	</div>\r\n	</div>\r\n</div>\r\n\r\n	\r\n</body>\r\n</html>','2','1837','','1728810794');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('7080','usercp_bookmarks_remove','<div class=\"row g-3\">\r\n	<div class=\"col-lg text-center text-sm-center text-md-center text-lg-start text-xl-start text-xxl-start\">\r\n		<a href=\"usercp.php?action=removebookmarks&amp;my_post_key={$mybb->post_code}\" class=\"btn btn-primary btn-sm\"><i class=\"fa-solid fa-xmark\"></i> &nbsp;{$lang->usercp[\'remove_all_book\']}</a>\r\n	</div>\r\n	<div class=\"col-lg-auto text-lg-end\">\r\n		<div class=\"input-group\">\r\n            <select name=\"do\" class=\"form-select form-select-sm border pe-5 w-auto rounded me-2\">\r\n			<option value=\"delete\">Delete Bookmarks</option>\r\n		</select> \r\n			{$gobutton}\r\n		</div>\r\n	</div>\r\n</div>','2','1800','','1728810794');
