INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('2300','modal_edit','<!-- Quick Edit Modal -->\r\n<div class=\"modal fade\" id=\"editPostModal{$post[\'pid\']}\" tabindex=\"-1\" aria-labelledby=\"editPostModalLabel{$post[\'pid\']}\" aria-hidden=\"true\">\r\n  <div class=\"modal-dialog modal-lg\">\r\n    <div class=\"modal-content\">\r\n      <div class=\"modal-header bg-primary text-white\">\r\n        <h5 class=\"modal-title\" id=\"editPostModalLabel{$post[\'pid\']}\">Edit Post</h5>\r\n        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\r\n      </div>\r\n\r\n      <div class=\"modal-body\">\r\n        <!-- BBCode Toolbar -->\r\n        <div class=\"mb-2\">\r\n          <!-- Text Styles -->\r\n          <button class=\"btn btn-sm btn-light\" onclick=\"wrapBBCode(\'[b]\',\'[/b]\',{$post[\'pid\']})\"><b>B</b></button>\r\n          <button class=\"btn btn-sm btn-light\" onclick=\"wrapBBCode(\'[i]\',\'[/i]\',{$post[\'pid\']})\"><i>I</i></button>\r\n          <button class=\"btn btn-sm btn-light\" onclick=\"wrapBBCode(\'[u]\',\'[/u]\',{$post[\'pid\']})\"><u>U</u></button>\r\n          <button class=\"btn btn-sm btn-light\" onclick=\"wrapBBCode(\'[s]\',\'[/s]\',{$post[\'pid\']})\"><s>S</s></button>\r\n\r\n          <!-- Alignment -->\r\n          <button class=\"btn btn-sm btn-light\" onclick=\"wrapBBCode(\'[left]\',\'[/left]\',{$post[\'pid\']})\">Left</button>\r\n          <button class=\"btn btn-sm btn-light\" onclick=\"wrapBBCode(\'[center]\',\'[/center]\',{$post[\'pid\']})\">Center</button>\r\n          <button class=\"btn btn-sm btn-light\" onclick=\"wrapBBCode(\'[right]\',\'[/right]\',{$post[\'pid\']})\">Right</button>\r\n\r\n          <!-- Color & Size -->\r\n          <button class=\"btn btn-sm btn-light\" onclick=\"wrapBBCode(\'[color=red]\',\'[/color]\',{$post[\'pid\']})\">Red</button>\r\n          <button class=\"btn btn-sm btn-light\" onclick=\"wrapBBCode(\'[size=18]\',\'[/size]\',{$post[\'pid\']})\">Size</button>\r\n\r\n          <!-- Links & Media -->\r\n          <button class=\"btn btn-sm btn-light\" onclick=\"wrapBBCode(\'[url]\',\'[/url]\',{$post[\'pid\']})\">URL</button>\r\n          <button class=\"btn btn-sm btn-light\" onclick=\"wrapBBCode(\'[img]\',\'[/img]\',{$post[\'pid\']})\">IMG</button>\r\n          <button class=\"btn btn-sm btn-light\" onclick=\"wrapBBCode(\'[video]\',\'[/video]\',{$post[\'pid\']})\">Video</button>\r\n          <button class=\"btn btn-sm btn-light\" onclick=\"wrapBBCode(\'[youtube]\',\'[/youtube]\',{$post[\'pid\']})\">YouTube</button>\r\n\r\n          <!-- Quote & Code -->\r\n          <button class=\"btn btn-sm btn-light\" onclick=\"wrapBBCode(\'[quote]\',\'[/quote]\',{$post[\'pid\']})\">Quote</button>\r\n          <button class=\"btn btn-sm btn-light\" onclick=\"wrapBBCode(\'[code]\',\'[/code]\',{$post[\'pid\']})\">Code</button>\r\n\r\n          <!-- Lists -->\r\n          <button class=\"btn btn-sm btn-light\" onclick=\"wrapBBCode(\'[list]\\n[*]\',\'\\n[/list]\',{$post[\'pid\']})\">List</button>\r\n          <button class=\"btn btn-sm btn-light\" onclick=\"wrapBBCode(\'[list=1]\\n[*]\',\'\\n[/list]\',{$post[\'pid\']})\">#List</button>\r\n        </div>\r\n\r\n        <!-- Textarea -->\r\n        <textarea id=\"editPostTextarea{$post[\'pid\']}\" class=\"form-control mb-3\" rows=\"6\" placeholder=\"Edit your post...\">{$post[\'message\']}</textarea>\r\n\r\n        <!-- Edit Reason -->\r\n        <div class=\"mb-3\">\r\n          <label for=\"editReasonInput{$post[\'pid\']}\" class=\"form-label\">Edit Reason (optional)</label>\r\n          <input type=\"text\" class=\"form-control\" id=\"editReasonInput{$post[\'pid\']}\" value=\"{$post[\'editreason\']}\" placeholder=\"Enter reason for editing...\">\r\n        </div>\r\n\r\n        <!-- Live Preview -->\r\n        <h6>Live Preview</h6>\r\n        <div id=\"editPostPreview{$post[\'pid\']}\" class=\"border p-2 bg-light rounded\" style=\"min-height: 100px;\"></div>\r\n      </div>\r\n\r\n      <div class=\"modal-footer\">\r\n        <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Cancel</button>\r\n        <button type=\"button\" class=\"btn btn-primary\" id=\"savePostBtn{$post[\'pid\']}\">Save Changes</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>','2','1800','','1720609120');
INSERT INTO templates (`tid`,`title`,`template`,`sid`,`version`,`status`,`dateline`) VALUES ('2301','modal_delete','<!-- Delete Post Modal -->\r\n<div class=\"modal fade\" id=\"deletePostModal{$post[\'pid\']}\" tabindex=\"-1\" aria-labelledby=\"deletePostModalLabel{$post[\'pid\']}\" aria-hidden=\"true\">\r\n  <div class=\"modal-dialog modal-dialog-centered modal-lg\">\r\n    <div class=\"modal-content\">\r\n      <div class=\"modal-header bg-danger text-white\">\r\n        <h5 class=\"modal-title\" id=\"deletePostModalLabel{$post[\'pid\']}\">\r\n          <i class=\"fa-solid fa-trash me-2\"></i>Delete Post\r\n        </h5>\r\n        <button type=\"button\" class=\"btn-close btn-close-white\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\r\n      </div>\r\n      <div class=\"modal-body\">\r\n\r\n        <div class=\"text-center mb-3\">\r\n          <i class=\"fa-solid fa-triangle-exclamation text-warning fa-3x mb-3\"></i>\r\n          <h6 class=\"fw-bold\">Are you sure you want to delete this post?</h6>\r\n          <p class=\"text-muted mb-0\">This action cannot be undone. The post will be permanently removed.</p>\r\n        </div>\r\n\r\n        <!-- Превью поста -->\r\n        <div class=\"card border-danger border-opacity-25 mb-3\">\r\n          <div class=\"card-header py-2 px-3 bg-danger bg-opacity-10 d-flex justify-content-between align-items-center\">\r\n            <span class=\"small fw-bold text-danger\">\r\n              <i class=\"fas fa-user me-1\"></i>{$post[\'username\']}\r\n            </span>\r\n            <div class=\"d-flex gap-2 align-items-center\">\r\n              <span class=\"text-muted small\">{$post[\'postdate\']}</span>\r\n              <span class=\"badge bg-secondary\">PID: {$post[\'pid\']}</span>\r\n            </div>\r\n          </div>\r\n          \r\n		 <div class=\"card-body py-2 px-3\">\r\n    <div class=\"small\" style=\"max-height: 350px; overflow-y: auto;\">\r\n        <style scoped>\r\n            #deletePostModal{$post[\'pid\']} .post_body img { max-width: 100%; height: auto; }\r\n            #deletePostModal{$post[\'pid\']} .post_body blockquote { font-size: 0.8rem; padding: 0.5rem; }\r\n        </style>\r\n        <div>{$message2}</div>\r\n    </div>\r\n</div>\r\n		  \r\n		  \r\n		  \r\n		  \r\n        </div>\r\n\r\n        <!-- Loading indicator -->\r\n        <div id=\"deleteLoading{$post[\'pid\']}\" class=\"text-center mt-3\" style=\"display: none;\">\r\n          <div class=\"spinner-border text-primary\" role=\"status\">\r\n            <span class=\"visually-hidden\">Deleting...</span>\r\n          </div>\r\n          <p class=\"mt-2 text-muted\">Deleting post...</p>\r\n        </div>\r\n\r\n      </div>\r\n      <div class=\"modal-footer\">\r\n        <button type=\"button\" class=\"btn btn-outline-secondary\" data-bs-dismiss=\"modal\">\r\n          <i class=\"fa-solid fa-xmark me-1\"></i>Cancel\r\n        </button>\r\n        <button type=\"button\" class=\"btn btn-danger\" id=\"confirmDeleteBtn{$post[\'pid\']}\">\r\n          <i class=\"fa-solid fa-trash me-1\"></i>Delete Post\r\n        </button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>','2','1800','','1720609120');
