CREATE TABLE `reports` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `addedby` int unsigned NOT NULL DEFAULT '0',
  `added` int unsigned NOT NULL DEFAULT '0',
  `reported_id` int unsigned NOT NULL DEFAULT '0',
  `reported_user_id` int unsigned NOT NULL DEFAULT '0',
  `forum_id` int DEFAULT '0',
  `thread_id` int DEFAULT '0',
  `type` enum('torrent','user','comment','forumpost') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'torrent',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `rule_violation` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `dealtby` int unsigned NOT NULL DEFAULT '0',
  `dealtwith` tinyint unsigned NOT NULL DEFAULT '0',
  `updated_at` int unsigned NOT NULL DEFAULT '0',
  `ip_address` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_reported_id` (`reported_id`),
  KEY `idx_type_reported` (`type`,`reported_id`),
  KEY `idx_addedby` (`addedby`),
  KEY `idx_dealtwith` (`dealtwith`),
  KEY `idx_forum` (`forum_id`),
  KEY `idx_thread` (`thread_id`)
) ENGINE=MyISAM AUTO_INCREMENT=180 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `rules` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `usergroups` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '[0]',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'general',
  `priority` tinyint unsigned DEFAULT '50' COMMENT '1-100, higher = more important',
  `is_active` tinyint(1) DEFAULT '1',
  `icon` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `last_updated_by` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `category` (`category`),
  KEY `priority` (`priority`),
  KEY `is_active` (`is_active`),
  KEY `created_at` (`created_at`),
  KEY `idx_category_priority` (`category`,`priority`),
  FULLTEXT KEY `ft_title_text` (`title`,`text`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Community rules and guidelines system';
CREATE TABLE `screenshots` (
  `id` int NOT NULL AUTO_INCREMENT,
  `torrent_id` int NOT NULL,
  `filename` varchar(255) NOT NULL,
  `uploaded_at` int unsigned NOT NULL DEFAULT '0',
  `sort_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6005 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `searchlog` (
  `sid` varchar(32) NOT NULL DEFAULT '',
  `uid` int unsigned NOT NULL DEFAULT '0',
  `dateline` int unsigned NOT NULL DEFAULT '0',
  `ipaddress` varbinary(16) NOT NULL DEFAULT '',
  `threads` longtext NOT NULL,
  `posts` longtext NOT NULL,
  `resulttype` varchar(10) NOT NULL DEFAULT '',
  `querycache` text NOT NULL,
  `keywords` text NOT NULL,
  PRIMARY KEY (`sid`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;
CREATE TABLE `seedbonus_settings` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `setting_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `setting_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `setting_type` enum('boolean','integer','float','string','array') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'string',
  `setting_group` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'general',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `setting_key` (`setting_key`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `sessions` (
  `sid` varchar(32) NOT NULL DEFAULT '',
  `uid` int unsigned NOT NULL DEFAULT '0',
  `ip` varbinary(16) NOT NULL DEFAULT '',
  `time` int unsigned NOT NULL DEFAULT '0',
  `location` varchar(150) NOT NULL DEFAULT '',
  `useragent` varchar(200) NOT NULL DEFAULT '',
  `anonymous` tinyint(1) NOT NULL DEFAULT '0',
  `nopermission` tinyint(1) NOT NULL DEFAULT '0',
  `location1` int unsigned NOT NULL DEFAULT '0',
  `location2` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`sid`),
  KEY `location` (`location1`,`location2`),
  KEY `time` (`time`),
  KEY `uid` (`uid`),
  KEY `ip` (`ip`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;
CREATE TABLE `settings` (
  `sid` smallint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(120) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `value` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  PRIMARY KEY (`sid`)
) ENGINE=MyISAM AUTO_INCREMENT=96 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `sitelog` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `uid` int unsigned NOT NULL DEFAULT '0',
  `ipaddress` varbinary(16) NOT NULL DEFAULT '',
  `added` int unsigned NOT NULL DEFAULT '0',
  `txt` text,
  `category` varchar(50) NOT NULL DEFAULT '',
  `level` tinyint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `uid` (`uid`),
  KEY `category` (`category`),
  KEY `level` (`level`),
  KEY `added` (`added`)
) ENGINE=MyISAM AUTO_INCREMENT=215 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `smilies` (
  `sid` smallint unsigned NOT NULL AUTO_INCREMENT,
  `stitle` char(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `stext` char(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `spath` char(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `sorder` smallint unsigned NOT NULL DEFAULT '1',
  PRIMARY KEY (`sid`)
) ENGINE=MyISAM AUTO_INCREMENT=150 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `snatched` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `torrentid` int unsigned DEFAULT '0',
  `userid` int unsigned DEFAULT '0',
  `port` smallint unsigned NOT NULL DEFAULT '0',
  `uploaded` bigint unsigned NOT NULL DEFAULT '0',
  `downloaded` bigint unsigned NOT NULL DEFAULT '0',
  `to_go` bigint unsigned NOT NULL DEFAULT '0',
  `seeder` enum('yes','no') NOT NULL DEFAULT 'no',
  `last_action` int unsigned NOT NULL DEFAULT '0',
  `startdat` int unsigned NOT NULL DEFAULT '0',
  `completedat` int unsigned NOT NULL DEFAULT '0',
  `connectable` enum('yes','no') NOT NULL DEFAULT 'yes',
  `agent` char(32) NOT NULL DEFAULT '',
  `finished` enum('yes','no') NOT NULL DEFAULT 'no',
  `downspeed` bigint unsigned NOT NULL DEFAULT '0',
  `upspeed` bigint unsigned NOT NULL DEFAULT '0',
  `seedtime` int unsigned NOT NULL DEFAULT '0',
  `leechtime` int unsigned NOT NULL DEFAULT '0',
  `ip` char(15) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `seeder` (`seeder`,`last_action`),
  KEY `torrentid` (`torrentid`),
  KEY `userid` (`userid`),
  KEY `finished` (`finished`)
) ENGINE=MyISAM AUTO_INCREMENT=3635 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `spiders` (
  `sid` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL DEFAULT '',
  `theme` smallint unsigned NOT NULL DEFAULT '0',
  `language` varchar(20) NOT NULL DEFAULT '',
  `usergroup` smallint unsigned NOT NULL DEFAULT '0',
  `useragent` varchar(200) NOT NULL DEFAULT '',
  `lastvisit` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`sid`)
) ENGINE=MyISAM AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb3;
CREATE TABLE `staffmessages` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `sender` int unsigned NOT NULL DEFAULT '0',
  `added` int unsigned NOT NULL DEFAULT '0',
  `msg` text,
  `subject` varchar(100) NOT NULL DEFAULT '',
  `answeredby` int unsigned NOT NULL DEFAULT '0',
  `answered` tinyint unsigned NOT NULL DEFAULT '0',
  `answer` text,
  PRIMARY KEY (`id`),
  KEY `answered` (`answered`)
) ENGINE=MyISAM AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `staffpanel` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` char(32) NOT NULL DEFAULT '',
  `description` varchar(64) NOT NULL DEFAULT '',
  `filename` char(32) NOT NULL DEFAULT '',
  `usergroups` char(32) NOT NULL DEFAULT '[8]',
  PRIMARY KEY (`id`),
  KEY `usergroups` (`usergroups`),
  KEY `name` (`name`)
) ENGINE=MyISAM AUTO_INCREMENT=119 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `stats` (
  `dateline` int unsigned NOT NULL DEFAULT '0',
  `numusers` int unsigned NOT NULL DEFAULT '0',
  `numthreads` int unsigned NOT NULL DEFAULT '0',
  `numposts` int unsigned NOT NULL DEFAULT '0',
  `torrents` int unsigned NOT NULL DEFAULT '0',
  `seeders` int unsigned NOT NULL DEFAULT '0',
  `leechers` int unsigned NOT NULL DEFAULT '0',
  `peers` int unsigned NOT NULL DEFAULT '0',
  `totaldownloaded` bigint unsigned NOT NULL DEFAULT '0',
  `totaluploaded` bigint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`dateline`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;
CREATE TABLE `templates` (
  `tid` int unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(120) NOT NULL DEFAULT '',
  `template` text NOT NULL,
  `sid` smallint NOT NULL DEFAULT '0',
  `version` varchar(20) NOT NULL DEFAULT '0',
  `status` varchar(10) NOT NULL DEFAULT '',
  `dateline` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`tid`),
  KEY `sid` (`sid`,`title`)
) ENGINE=MyISAM AUTO_INCREMENT=10000 DEFAULT CHARSET=utf8mb3;
CREATE TABLE `torrents` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `info_hash` varchar(40) NOT NULL,
  `name` tinytext,
  `filename` varchar(255) NOT NULL DEFAULT '',
  `descr` longtext,
  `tags` text,
  `category` int unsigned NOT NULL DEFAULT '0',
  `size` bigint unsigned NOT NULL DEFAULT '0',
  `added` int unsigned NOT NULL DEFAULT '0',
  `numfiles` int unsigned NOT NULL DEFAULT '0',
  `comments` int unsigned NOT NULL DEFAULT '0',
  `hits` int unsigned NOT NULL DEFAULT '0',
  `times_completed` int unsigned NOT NULL DEFAULT '0',
  `leechers` int unsigned NOT NULL DEFAULT '0',
  `seeders` int unsigned NOT NULL DEFAULT '0',
  `last_action` int unsigned NOT NULL DEFAULT '0',
  `visible` enum('yes','no') NOT NULL DEFAULT 'yes',
  `banned` enum('yes','no') NOT NULL DEFAULT 'no',
  `owner` int unsigned NOT NULL DEFAULT '0',
  `anonymous` enum('yes','no') NOT NULL DEFAULT 'no',
  `free` enum('yes','no') DEFAULT 'no',
  `silver` enum('yes','no') NOT NULL DEFAULT 'no',
  `doubleupload` enum('yes','no') NOT NULL DEFAULT 'no',
  `sticky` enum('yes','no') NOT NULL DEFAULT 'no',
  `allowcomments` enum('yes','no') NOT NULL DEFAULT 'yes',
  `t_image` varchar(255) NOT NULL DEFAULT '',
  `t_image2` varchar(255) NOT NULL DEFAULT '',
  `t_link` text NOT NULL,
  `isnuked` enum('yes','no') NOT NULL DEFAULT 'no',
  `WhyNuked` varchar(255) NOT NULL DEFAULT 'Bad quality!',
  `isrequest` enum('yes','no') NOT NULL DEFAULT 'no',
  `ts_external` enum('yes','no') NOT NULL DEFAULT 'no',
  `ts_external_url` varchar(128) NOT NULL DEFAULT '',
  `ts_external_lastupdate` int unsigned NOT NULL DEFAULT '0',
  `mtime` int unsigned NOT NULL DEFAULT '0',
  `ctime` int unsigned NOT NULL DEFAULT '0',
  `promotion_time_type` tinyint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `info_hash` (`info_hash`),
  KEY `added` (`added`),
  KEY `category` (`category`),
  KEY `times_completed` (`times_completed`,`leechers`,`seeders`),
  KEY `owner` (`owner`),
  KEY `visible` (`visible`,`banned`),
  KEY `t_image` (`t_image`(250)),
  FULLTEXT KEY `name` (`name`),
  FULLTEXT KEY `descr` (`descr`),
  FULLTEXT KEY `name_descr` (`name`,`descr`),
  FULLTEXT KEY `name_fulltext` (`name`)
) ENGINE=MyISAM AUTO_INCREMENT=298 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `torrents_nfo` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `torrent_id` int unsigned NOT NULL,
  `nfo` longtext NOT NULL,
  `uploaded_at` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `torrent_id` (`torrent_id`)
) ENGINE=MyISAM AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `ts_secret_questions` (
  `userid` int unsigned NOT NULL DEFAULT '0',
  `passhint` tinyint unsigned NOT NULL DEFAULT '0',
  `hintanswer` char(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`userid`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `tsf_announcements` (
  `aid` int unsigned NOT NULL AUTO_INCREMENT,
  `fid` int NOT NULL DEFAULT '0',
  `uid` int unsigned NOT NULL DEFAULT '0',
  `subject` varchar(120) NOT NULL DEFAULT '',
  `message` text NOT NULL,
  `startdate` int unsigned NOT NULL DEFAULT '0',
  `enddate` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`aid`),
  KEY `fid` (`fid`)
) ENGINE=MyISAM AUTO_INCREMENT=62 DEFAULT CHARSET=utf8mb3;
CREATE TABLE `tsf_forums` (
  `fid` smallint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(120) NOT NULL DEFAULT '',
  `description` text NOT NULL,
  `linkto` varchar(180) NOT NULL DEFAULT '',
  `type` char(1) NOT NULL DEFAULT '',
  `pid` smallint unsigned NOT NULL DEFAULT '0',
  `parentlist` text NOT NULL,
  `disporder` smallint unsigned NOT NULL DEFAULT '0',
  `active` tinyint(1) NOT NULL DEFAULT '1',
  `open` tinyint(1) NOT NULL DEFAULT '1',
  `threads` int unsigned NOT NULL DEFAULT '0',
  `posts` int unsigned NOT NULL DEFAULT '0',
  `lastpost` int unsigned NOT NULL DEFAULT '0',
  `lastposter` varchar(120) NOT NULL DEFAULT '',
  `lastposteruid` int unsigned NOT NULL DEFAULT '0',
  `lastposttid` int NOT NULL DEFAULT '0',
  `lastpostsubject` varchar(120) NOT NULL DEFAULT '',
  `password` varchar(50) NOT NULL DEFAULT '',
  `usepostcounts` tinyint(1) NOT NULL DEFAULT '1',
  `usethreadcounts` tinyint(1) NOT NULL DEFAULT '1',
  `unapprovedthreads` int unsigned NOT NULL DEFAULT '0',
  `unapprovedposts` int unsigned NOT NULL DEFAULT '0',
  `defaultdatecut` smallint unsigned NOT NULL DEFAULT '0',
  `defaultsortby` varchar(10) NOT NULL DEFAULT '',
  `defaultsortorder` varchar(4) NOT NULL DEFAULT '',
  PRIMARY KEY (`fid`),
  KEY `pid` (`pid`),
  KEY `password` (`password`),
  KEY `type` (`type`,`pid`,`disporder`)
) ENGINE=MyISAM AUTO_INCREMENT=116 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `tsf_forumsread` (
  `fid` int unsigned NOT NULL DEFAULT '0',
  `uid` int unsigned NOT NULL DEFAULT '0',
  `dateline` int unsigned NOT NULL DEFAULT '0',
  UNIQUE KEY `fid` (`fid`,`uid`),
  KEY `dateline` (`dateline`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `tsf_forumsubscriptions` (
  `fsid` int unsigned NOT NULL AUTO_INCREMENT,
  `fid` smallint unsigned NOT NULL DEFAULT '0',
  `uid` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`fsid`),
  KEY `uid` (`uid`)
) ENGINE=MyISAM AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb3;
CREATE TABLE `tsf_moderators` (
  `moderatorid` smallint unsigned NOT NULL AUTO_INCREMENT,
  `userid` int unsigned NOT NULL DEFAULT '0',
  `forumid` smallint NOT NULL DEFAULT '0',
  PRIMARY KEY (`moderatorid`),
  KEY `userid` (`userid`,`forumid`)
) ENGINE=MyISAM AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `tsf_polls` (
  `pid` int unsigned NOT NULL AUTO_INCREMENT,
  `tid` int unsigned NOT NULL DEFAULT '0',
  `question` varchar(200) NOT NULL DEFAULT '',
  `dateline` int unsigned NOT NULL DEFAULT '0',
  `options` text NOT NULL,
  `votes` text NOT NULL,
  `numoptions` smallint unsigned NOT NULL DEFAULT '0',
  `numvotes` int unsigned NOT NULL DEFAULT '0',
  `timeout` int unsigned NOT NULL DEFAULT '0',
  `closed` tinyint(1) NOT NULL DEFAULT '0',
  `multiple` tinyint(1) NOT NULL DEFAULT '0',
  `public` tinyint(1) NOT NULL DEFAULT '0',
  `maxoptions` smallint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`pid`),
  KEY `tid` (`tid`)
) ENGINE=MyISAM AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb3;
CREATE TABLE `tsf_pollvotes` (
  `vid` int unsigned NOT NULL AUTO_INCREMENT,
  `pid` int unsigned NOT NULL DEFAULT '0',
  `uid` int unsigned NOT NULL DEFAULT '0',
  `voteoption` smallint unsigned NOT NULL DEFAULT '0',
  `dateline` int unsigned NOT NULL DEFAULT '0',
  `ipaddress` varbinary(16) NOT NULL DEFAULT '',
  PRIMARY KEY (`vid`),
  KEY `pid` (`pid`,`uid`)
) ENGINE=MyISAM AUTO_INCREMENT=76 DEFAULT CHARSET=utf8mb3;
CREATE TABLE `tsf_posts` (
  `pid` int unsigned NOT NULL AUTO_INCREMENT,
  `tid` int unsigned NOT NULL DEFAULT '0',
  `replyto` int unsigned NOT NULL DEFAULT '0',
  `fid` smallint unsigned NOT NULL DEFAULT '0',
  `subject` varchar(120) NOT NULL DEFAULT '',
  `uid` int unsigned NOT NULL DEFAULT '0',
  `username` char(32) NOT NULL DEFAULT '',
  `dateline` int unsigned NOT NULL DEFAULT '0',
  `message` text NOT NULL,
  `ipaddress` varbinary(16) NOT NULL DEFAULT '',
  `edituid` int unsigned NOT NULL DEFAULT '0',
  `edittime` int NOT NULL DEFAULT '0',
  `editreason` varchar(150) NOT NULL DEFAULT '',
  `visible` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`pid`),
  KEY `tid` (`tid`,`uid`),
  KEY `uid` (`uid`),
  KEY `visible` (`visible`),
  KEY `dateline` (`dateline`),
  KEY `ipaddress` (`ipaddress`),
  KEY `tiddate` (`tid`,`dateline`),
  FULLTEXT KEY `message` (`message`)
) ENGINE=MyISAM AUTO_INCREMENT=5409 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `tsf_threads` (
  `tid` int unsigned NOT NULL AUTO_INCREMENT,
  `fid` smallint unsigned NOT NULL DEFAULT '0',
  `subject` varchar(120) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `uid` int unsigned NOT NULL DEFAULT '0',
  `username` char(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `dateline` int unsigned NOT NULL DEFAULT '0',
  `firstpost` int unsigned NOT NULL DEFAULT '0',
  `lastpost` int unsigned NOT NULL DEFAULT '0',
  `lastposter` char(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `lastposteruid` int unsigned NOT NULL DEFAULT '0',
  `views` int NOT NULL DEFAULT '0',
  `replies` int NOT NULL DEFAULT '0',
  `closed` varchar(30) NOT NULL DEFAULT '',
  `sticky` tinyint(1) NOT NULL DEFAULT '0',
  `votenum` smallint unsigned NOT NULL DEFAULT '0',
  `votetotal` smallint unsigned NOT NULL DEFAULT '0',
  `poll` int unsigned NOT NULL DEFAULT '0',
  `visible` tinyint(1) NOT NULL DEFAULT '1',
  `attachmentcount` int unsigned NOT NULL DEFAULT '0',
  `prefix` smallint unsigned NOT NULL DEFAULT '0',
  `notes` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `numratings` smallint unsigned NOT NULL DEFAULT '0',
  `totalratings` smallint unsigned NOT NULL DEFAULT '0',
  `unapprovedposts` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`tid`),
  KEY `fid` (`fid`,`visible`,`sticky`),
  KEY `dateline` (`dateline`),
  KEY `lastpost` (`lastpost`,`fid`),
  KEY `firstpost` (`firstpost`),
  KEY `uid` (`uid`),
  FULLTEXT KEY `subject` (`subject`)
) ENGINE=MyISAM AUTO_INCREMENT=1180 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `tsf_threadsread` (
  `tid` int unsigned NOT NULL DEFAULT '0',
  `uid` int unsigned NOT NULL DEFAULT '0',
  `dateline` int unsigned NOT NULL DEFAULT '0',
  UNIQUE KEY `tid` (`tid`,`uid`),
  KEY `dateline` (`dateline`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `tsf_threadsubscriptions` (
  `sid` int unsigned NOT NULL AUTO_INCREMENT,
  `uid` int unsigned NOT NULL DEFAULT '0',
  `tid` int unsigned NOT NULL DEFAULT '0',
  `notification` tinyint(1) NOT NULL DEFAULT '0',
  `dateline` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`sid`),
  KEY `uid` (`uid`),
  KEY `tid` (`tid`,`notification`)
) ENGINE=MyISAM AUTO_INCREMENT=213 DEFAULT CHARSET=utf8mb3;
CREATE TABLE `tsf_threadviews` (
  `tid` int unsigned NOT NULL DEFAULT '0',
  KEY `tid` (`tid`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `unbanrequests` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `ip` char(15) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `realip` char(15) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `email` char(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `comment` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `added` int unsigned NOT NULL DEFAULT '0',
  `reply` varchar(150) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  FULLTEXT KEY `reply` (`reply`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `userfields` (
  `ufid` int unsigned NOT NULL DEFAULT '0',
  `fid1` text NOT NULL,
  `fid2` text NOT NULL,
  `fid3` text NOT NULL,
  PRIMARY KEY (`ufid`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;
CREATE TABLE `usergroups` (
  `gid` smallint unsigned NOT NULL AUTO_INCREMENT,
  `disporder` smallint unsigned NOT NULL DEFAULT '0',
  `type` tinyint unsigned NOT NULL DEFAULT '1',
  `title` char(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '',
  `usertitle` varchar(120) NOT NULL DEFAULT '',
  `description` tinytext CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `isbannedgroup` tinyint(1) NOT NULL DEFAULT '0',
  `cansettingspanel` tinyint(1) NOT NULL DEFAULT '0',
  `canstaffpanel` tinyint(1) NOT NULL DEFAULT '0',
  `canuserdetails` tinyint(1) NOT NULL DEFAULT '0',
  `floodlimit` tinyint unsigned NOT NULL DEFAULT '60',
  `autoinvite` tinyint unsigned NOT NULL DEFAULT '3',
  `namestyle` char(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '{username}',
  `issupermod` tinyint(1) NOT NULL DEFAULT '0',
  `isvipgroup` enum('yes','no') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT 'no',
  `canfreeleech` enum('yes','no') CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT 'no',
  `candeletetorrent` tinyint(1) NOT NULL DEFAULT '0',
  `attachquota` int unsigned NOT NULL DEFAULT '0',
  `maxpmrecipients` int unsigned NOT NULL DEFAULT '5',
  `pmquota` int unsigned NOT NULL DEFAULT '0',
  `maxposts` int unsigned NOT NULL DEFAULT '0',
  `showforumteam` tinyint(1) NOT NULL DEFAULT '0',
  `cansendemail` tinyint(1) NOT NULL DEFAULT '0',
  `cansendemailoverride` tinyint(1) NOT NULL DEFAULT '0',
